// Generated by scripts/pieces-source.ts from src/pieces/ and src/sections/ — do not edit by hand.
import type { HeroId, PieceId, SectionId } from '@/types/domain'

export const pieceSource: Record<PieceId, string> = {
  "text-effect": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Effect\" (MIT © 2024 ibelick, https://motion-primitives.com); the `cut`\n// preset from Fancy Components \"Vertical Cut Reveal\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// Reveals a headline word by word (or letter by letter) once it enters the viewport: `slide`, `blur`, `fade`, or `cut` —\n// each word slides up out of a hard mask, sharper than a fade. Colors and fonts come from the recipe tokens.\nimport { motion, useReducedMotion, type Variants } from 'motion/react'\nimport type { JSX } from 'react'\n\ntype Preset = 'blur' | 'slide' | 'fade' | 'cut'\nconst ITEM: Record<Preset, Variants> = {\n  blur: { hidden: { opacity: 0, filter: 'blur(10px)', y: 8 }, visible: { opacity: 1, filter: 'blur(0px)', y: 0 } },\n  slide: { hidden: { opacity: 0, y: '0.6em' }, visible: { opacity: 1, y: 0 } },\n  fade: { hidden: { opacity: 0 }, visible: { opacity: 1 } },\n  cut: { hidden: { y: '105%' }, visible: { y: 0 } },\n}\n\nexport function TextEffect({ children, as = 'h2', per = 'word', preset = 'slide', delay = 0, className }: {\n  children: string; as?: keyof JSX.IntrinsicElements; per?: 'word' | 'char'; preset?: Preset; delay?: number; className?: string\n}) {\n  const reduce = useReducedMotion()\n  const Tag = motion[as as 'h2']\n  const parts = per === 'word' ? children.split(/(\\s+)/) : children.split('')\n  const timing = reduce ? { duration: 0 } : preset === 'cut' ? { type: 'spring' as const, stiffness: 190, damping: 22 } : { duration: 0.5, ease: [0.22, 1, 0.36, 1] as const }\n  return (\n    <Tag className={className} initial=\"hidden\" whileInView=\"visible\" viewport={{ once: true, amount: 0.6 }}\n      transition={reduce ? { duration: 0 } : { staggerChildren: per === 'word' ? (preset === 'cut' ? 0.07 : 0.06) : 0.025, delayChildren: delay }}> {/* same markup either way (hydration); reduced motion only drops the timing */}\n      <span className=\"sr-only\">{children}</span>\n      {parts.map((p, i) => /^\\s+$/.test(p) ? p /* plain spaces, so a wrapped line never starts indented */ : preset === 'cut' ? (\n        <span key={i} aria-hidden className=\"inline-flex overflow-hidden pb-[0.08em] align-bottom\">\n          <motion.span className=\"inline-block whitespace-pre\" variants={ITEM.cut} transition={timing}>{p}</motion.span>\n        </span>\n      ) : (\n        <motion.span key={i} aria-hidden className=\"inline-block whitespace-pre\" variants={ITEM[preset]} transition={timing}>{p}</motion.span>\n      ))}\n    </Tag>\n  )\n}\n",
  "text-loop": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Loop\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// One word of a headline cycles through a short list (\"We build | shops | archives | tools\").\nimport { AnimatePresence, motion, useReducedMotion } from 'motion/react'\nimport { useEffect, useState } from 'react'\n\nexport function TextLoop({ words, interval = 2.4, className }: { words: string[]; interval?: number; className?: string }) {\n  const [i, setI] = useState(0)\n  const reduce = useReducedMotion()\n  useEffect(() => {\n    if (reduce || words.length < 2) return\n    const t = setInterval(() => setI((x) => (x + 1) % words.length), interval * 1000)\n    return () => clearInterval(t)\n  }, [reduce, words.length, interval])\n  return (\n    <span className={`relative inline-block whitespace-nowrap align-bottom ${className ?? ''}`} aria-live=\"off\">\n      <span className=\"sr-only\">{words.join(', ')}</span>\n      <AnimatePresence mode=\"popLayout\" initial={false}>\n        <motion.span key={i} aria-hidden className=\"inline-block\" initial={{ y: '100%', opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: '-100%', opacity: 0 }} transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}>\n          {words[i]}\n        </motion.span>\n      </AnimatePresence>\n    </span>\n  )\n}\n",
  "split-flap": "'use client'\n// OpusKit piece — based on Componentry \"Split Flap Display\" (MIT © Componentry, https://componentry.dev).\n// Departure-board letters that flick through characters until they land. Dates, times, gate numbers, short words.\nimport { useInView, useReducedMotion } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nconst FLAPS = ' ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-–:./'\n\nexport function SplitFlap({ text, className }: { text: string; className?: string }) {\n  const ref = useRef<HTMLSpanElement>(null)\n  const inView = useInView(ref, { once: true, amount: 0.8 })\n  const reduce = useReducedMotion()\n  const target = text.toUpperCase()\n  const [shown, setShown] = useState(target.replace(/\\S/g, ' '))\n  useEffect(() => {\n    if (!inView || reduce) return\n    let tick = 0\n    const t = setInterval(() => {\n      tick++\n      setShown(target.split('').map((c, i) => (c === ' ' || tick > 6 + i * 2 ? c : FLAPS[(tick * 7 + i * 3) % FLAPS.length])).join(''))\n      if (tick > 6 + target.length * 2) clearInterval(t)\n    }, 55)\n    return () => clearInterval(t)\n  }, [inView, reduce, target])\n  return (\n    <span ref={ref} className={`inline-flex gap-[0.08em] ${className ?? ''}`} aria-label={text}>\n      {(reduce ? target : shown).split('').map((c, i) => (\n        <span key={i} aria-hidden className=\"relative inline-grid w-[0.78em] place-items-center overflow-hidden rounded-[0.08em] bg-(--color-text) py-[0.08em] text-(--color-background) tabular-nums\">\n          {c === ' ' ? ' ' : c}\n          <span className=\"absolute inset-x-0 top-1/2 h-px bg-(--color-background)/40\" />\n        </span>\n      ))}\n    </span>\n  )\n}\n",
  "number-ticker": "'use client'\n// OpusKit piece — adapted from Magic UI \"Number Ticker\" (MIT © Magic UI, https://magicui.design).\n// A number that counts up to its value when it scrolls into view. For real figures only — never decoration.\nimport { useInView, useMotionValue, useReducedMotion, useSpring } from 'motion/react'\nimport { useEffect, useRef } from 'react'\n\nexport function NumberTicker({ value, decimals = 0, locale = 'en-US', className }: { value: number; decimals?: number; locale?: string; className?: string }) {\n  const ref = useRef<HTMLSpanElement>(null)\n  const inView = useInView(ref, { once: true })\n  const reduce = useReducedMotion()\n  const mv = useMotionValue(0)\n  const spring = useSpring(mv, { damping: 60, stiffness: 100 })\n  const fmt = (n: number) => new Intl.NumberFormat(locale, { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(n)\n  useEffect(() => { if (inView) mv.set(value) }, [inView, mv, value])\n  useEffect(() => spring.on('change', (v) => { if (ref.current) ref.current.textContent = fmt(v) }), [spring]) // eslint-disable-line react-hooks/exhaustive-deps\n  return <span ref={ref} className={`tabular-nums ${className ?? ''}`}>{fmt(reduce ? value : 0)}</span>\n}\n",
  "text-scramble": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Scramble\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// Letters resolve out of random characters — on first view, and again on hover. Best on short labels and nav links.\nimport { useInView, useReducedMotion } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nconst CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'\n\nexport function TextScramble({ children, duration = 0.8, className, replayOnHover = true }: {\n  children: string; duration?: number; className?: string; replayOnHover?: boolean\n}) {\n  const ref = useRef<HTMLSpanElement>(null)\n  const inView = useInView(ref, { once: true })\n  const reduce = useReducedMotion()\n  const [text, setText] = useState(children)\n  const timer = useRef<ReturnType<typeof setInterval>>(undefined)\n\n  const run = () => {\n    if (reduce) return\n    clearInterval(timer.current)\n    const steps = Math.max(8, Math.round(duration / 0.04))\n    let step = 0\n    timer.current = setInterval(() => {\n      const shown = (step / steps) * children.length\n      setText(children.split('').map((c, i) => (c === ' ' || i < shown ? c : CHARS[Math.floor(Math.random() * CHARS.length)])).join(''))\n      if (++step > steps) { clearInterval(timer.current); setText(children) }\n    }, 40)\n  }\n  useEffect(() => { if (inView) run() }, [inView]) // eslint-disable-line react-hooks/exhaustive-deps\n  useEffect(() => () => clearInterval(timer.current), [])\n\n  return (\n    <span ref={ref} className={className} onMouseEnter={replayOnHover ? run : undefined}>\n      <span className=\"sr-only\">{children}</span>\n      <span aria-hidden className=\"tabular-nums\">{text}</span>\n    </span>\n  )\n}\n",
  "text-roll": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Roll\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// On hover each letter rolls over to a copy of itself, one after another. For nav links and text buttons.\nimport { motion, useReducedMotion } from 'motion/react'\n\nexport function TextRoll({ children, className }: { children: string; className?: string }) {\n  const reduce = useReducedMotion()\n  const letters = children.split('')\n  return (\n    <motion.span className={`relative inline-flex overflow-hidden ${className ?? ''}`} initial=\"rest\" whileHover={reduce ? undefined : 'hover'} whileFocus={reduce ? undefined : 'hover'} aria-label={children}>\n      {letters.map((l, i) => (\n        <span key={i} aria-hidden className=\"relative inline-block\">\n          <motion.span className=\"inline-block\" variants={{ rest: { y: 0 }, hover: { y: '-100%' } }} transition={{ duration: 0.3, delay: i * 0.02, ease: [0.65, 0, 0.35, 1] }}>{l === ' ' ? ' ' : l}</motion.span>\n          <motion.span className=\"absolute left-0 top-full inline-block\" variants={{ rest: { y: 0 }, hover: { y: '-100%' } }} transition={{ duration: 0.3, delay: i * 0.02, ease: [0.65, 0, 0.35, 1] }}>{l === ' ' ? ' ' : l}</motion.span>\n        </span>\n      ))}\n    </motion.span>\n  )\n}\n",
  "spinning-text": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Spinning Text\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A slowly turning ring of text — a stamp or badge beside a hero, CTA or scroll hint.\nimport { motion, useReducedMotion } from 'motion/react'\nimport type { CSSProperties } from 'react'\n\nexport function SpinningText({ children, radius = 5, duration = 18, className }: { children: string; radius?: number; duration?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const letters = [...children]\n  return (\n    <motion.div className={`relative size-[calc(var(--r)*2ch+2ch)] ${className ?? ''}`} style={{ '--r': radius } as CSSProperties}\n      animate={reduce ? undefined : { rotate: 360 }} transition={{ duration, repeat: Infinity, ease: 'linear' }}>\n      <span className=\"sr-only\">{children}</span>\n      {letters.map((l, i) => (\n        <span key={i} aria-hidden className=\"absolute left-1/2 top-1/2 inline-block\"\n          style={{ transform: `translate(-50%, -50%) rotate(${(360 / letters.length) * i}deg) translateY(calc(var(--r) * -1ch))` }}>{l}</span>\n      ))}\n    </motion.div>\n  )\n}\n",
  "text-reveal": "'use client'\n// OpusKit piece — adapted from Magic UI \"Text Reveal\" (MIT © Magic UI, https://magicui.design).\n// A statement paragraph whose words light up one by one as the visitor scrolls through it.\nimport { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from 'motion/react'\nimport { useRef } from 'react'\n\nfunction Word({ children, progress, range }: { children: string; progress: MotionValue<number>; range: [number, number] }) {\n  const opacity = useTransform(progress, range, [0.18, 1])\n  return <motion.span style={{ opacity }} className=\"mr-[0.25em] inline-block\">{children}</motion.span>\n}\n\nexport function TextReveal({ children, className }: { children: string; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start 0.8', 'end 0.4'] })\n  const words = children.split(' ')\n  if (reduce) return <p className={className}>{children}</p>\n  return (\n    <div ref={ref}>\n      <p className={`flex flex-wrap ${className ?? ''}`} aria-label={children}>\n        {words.map((w, i) => <Word key={i} progress={scrollYProgress} range={[i / words.length, (i + 1) / words.length]}>{w}</Word>)}\n      </p>\n    </div>\n  )\n}\n",
  "marquee": "'use client'\n// OpusKit piece — adapted from Magic UI \"Marquee\" (MIT © Magic UI, https://magicui.design).\n// An endless row (logos, photos, words). Pauses on hover and off-screen; reduced motion shows a static, scrollable row.\nimport type { CSSProperties, ReactNode } from 'react'\n\nexport function Marquee({ children, reverse = false, seconds = 40, gap = '1.5rem', pauseOnHover = true, className }: {\n  children: ReactNode; reverse?: boolean; seconds?: number; gap?: string; pauseOnHover?: boolean; className?: string\n}) {\n  return (\n    <div className={`group flex overflow-hidden [gap:var(--gap)] motion-reduce:overflow-x-auto ${className ?? ''}`} style={{ '--gap': gap, '--dur': `${seconds}s` } as CSSProperties}>\n      <style>{`@keyframes opuskit-marquee{to{transform:translateX(calc(-100% - var(--gap)))}}`}</style>\n      {[0, 1].map((k) => (\n        <div key={k} aria-hidden={k === 1 || undefined}\n          className={`flex shrink-0 items-center [gap:var(--gap)] [animation:opuskit-marquee_var(--dur)_linear_infinite] motion-reduce:[animation:none] ${reverse ? '[animation-direction:reverse]' : ''} ${pauseOnHover ? 'group-hover:[animation-play-state:paused]' : ''} ${k === 1 ? 'motion-reduce:hidden' : ''}`}>\n          {children}\n        </div>\n      ))}\n    </div>\n  )\n}\n",
  "image-comparison": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Image Comparison\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// Before / after: drag (or use arrow keys on) the divider to compare two photos of the same frame.\nimport { motion, useMotionValue, useTransform } from 'motion/react'\nimport { useRef, useState } from 'react'\n\nexport function ImageComparison({ before, after, beforeAlt, afterAlt, className }: { before: string; after: string; beforeAlt: string; afterAlt: string; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const pos = useMotionValue(50)\n  const [val, setVal] = useState(50)\n  const clip = useTransform(pos, (v) => `inset(0 ${100 - v}% 0 0)`)\n  const left = useTransform(pos, (v) => `${v}%`)\n  const set = (v: number) => { const c = Math.min(100, Math.max(0, v)); pos.set(c); setVal(Math.round(c)) }\n  const fromPointer = (x: number) => { const r = ref.current!.getBoundingClientRect(); set(((x - r.left) / r.width) * 100) }\n  return (\n    <div ref={ref} className={`relative select-none overflow-hidden touch-pan-y ${className ?? ''}`}\n      onPointerDown={(e) => { e.currentTarget.setPointerCapture(e.pointerId); fromPointer(e.clientX) }}\n      onPointerMove={(e) => { if (e.buttons) fromPointer(e.clientX) }}>\n      <img src={after} alt={afterAlt} className=\"absolute inset-0 size-full object-cover\" draggable={false} />\n      <motion.img src={before} alt={beforeAlt} className=\"absolute inset-0 size-full object-cover\" style={{ clipPath: clip }} draggable={false} />\n      <motion.div style={{ left }} className=\"absolute inset-y-0 w-px -translate-x-1/2 bg-(--color-background)\">\n        <button type=\"button\" role=\"slider\" aria-label=\"Compare photos\" aria-valuemin={0} aria-valuemax={100} aria-valuenow={val}\n          onKeyDown={(e) => { if (e.key === 'ArrowLeft') set(val - 5); if (e.key === 'ArrowRight') set(val + 5) }}\n          className=\"absolute left-1/2 top-1/2 size-10 -translate-x-1/2 -translate-y-1/2 cursor-ew-resize rounded-full border border-(--color-background) bg-(--color-text)/60 backdrop-blur focus-visible:outline-2 focus-visible:outline-(--color-accent)\" />\n      </motion.div>\n    </div>\n  )\n}\n",
  "ring-carousel": "'use client'\n// OpusKit piece — adapted from Cult UI \"3D Carousel\" (MIT © 2023 Jordan-Gilliam, https://www.cult-ui.com).\n// Photos on the inside of a turning cylinder; drag to spin, click to open one large. Reduced motion: a plain swipe row.\nimport { AnimatePresence, animate, motion, useMotionValue, useReducedMotion, useTransform } from 'motion/react'\nimport { useState } from 'react'\n\nexport type RingPhoto = { src: string; alt: string }\n\nexport function RingCarousel({ photos, height = 420, className }: { photos: RingPhoto[]; height?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const [open, setOpen] = useState<RingPhoto | null>(null)\n  const rotation = useMotionValue(0)\n  const transform = useTransform(rotation, (v) => `rotateY(${v}deg)`)\n  const width = Math.max(1100, photos.length * 180)\n  const face = width / photos.length\n  const radius = width / (2 * Math.PI)\n  if (reduce) return (\n    <div className={`flex snap-x gap-4 overflow-x-auto ${className ?? ''}`}>\n      {photos.map((p) => <img key={p.src} src={p.src} alt={p.alt} className=\"h-72 w-auto shrink-0 snap-center object-cover\" />)}\n    </div>\n  )\n  return (\n    <div className={`relative overflow-hidden ${className ?? ''}`} style={{ height, perspective: 1000 }}>\n      <motion.div className=\"relative mx-auto h-full touch-pan-y cursor-grab active:cursor-grabbing\" style={{ width, transform, transformStyle: 'preserve-3d' }}\n        onPan={(_, i) => rotation.set(rotation.get() + i.delta.x * 0.1)}\n        onPanEnd={(_, i) => animate(rotation, rotation.get() + i.velocity.x * 0.02, { type: 'spring', stiffness: 100, damping: 30 })}>\n        {photos.map((p, i) => (\n          <button type=\"button\" key={p.src} onClick={() => setOpen(p)} aria-label={`Open: ${p.alt}`}\n            className=\"absolute inset-y-0 left-1/2 flex items-center p-2\" style={{ width: face, marginLeft: -face / 2, transform: `rotateY(${(360 / photos.length) * i}deg) translateZ(${radius}px)` }}>\n            <img src={p.src} alt=\"\" className=\"pointer-events-none aspect-[3/4] w-full object-cover\" draggable={false} />\n          </button>\n        ))}\n      </motion.div>\n      <AnimatePresence>\n        {open && (\n          <motion.button type=\"button\" onClick={() => setOpen(null)} aria-label=\"Close photo\" className=\"fixed inset-0 z-50 grid place-items-center bg-(--color-text)/80 p-6\"\n            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>\n            <motion.img src={open.src} alt={open.alt} className=\"max-h-full max-w-full object-contain\" initial={{ scale: 0.9 }} animate={{ scale: 1 }} />\n          </motion.button>\n        )}\n      </AnimatePresence>\n    </div>\n  )\n}\n",
  "image-field": "'use client'\n// OpusKit piece — based on Componentry \"Infinite Image Field\" (MIT © Componentry, https://componentry.dev).\n// A field of photos visitors drag in any direction, forever: tiles wrap around so the edge never arrives.\nimport { animate, motion, useMotionValue, useReducedMotion, useTransform, type MotionValue } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nexport type FieldPhoto = { src: string; alt: string }\nconst wrap = (v: number, size: number) => ((v % size) + size) % size\n\nfunction Tile({ photo, x, y, ox, oy, cols, rows, cell }: { photo: FieldPhoto; x: MotionValue<number>; y: MotionValue<number>; ox: number; oy: number; cols: number; rows: number; cell: number }) {\n  const tx = useTransform(x, (v) => wrap(ox * cell + v, cols * cell) - cell)\n  const ty = useTransform(y, (v) => wrap(oy * cell + v, rows * cell) - cell)\n  return (\n    <motion.div className=\"absolute left-0 top-0 p-2\" style={{ x: tx, y: ty, width: cell, height: cell }}>\n      <img src={photo.src} alt={photo.alt} className=\"size-full object-cover\" draggable={false} />\n    </motion.div>\n  )\n}\n\nexport function ImageField({ photos, cell = 260, className }: { photos: FieldPhoto[]; cell?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const [size, setSize] = useState({ w: 1200, h: 700 })\n  const x = useMotionValue(0), y = useMotionValue(0)\n  useEffect(() => {\n    const el = ref.current; if (!el) return\n    const ro = new ResizeObserver(() => setSize({ w: el.offsetWidth, h: el.offsetHeight }))\n    ro.observe(el); return () => ro.disconnect()\n  }, [])\n  const cols = Math.ceil(size.w / cell) + 2, rows = Math.ceil(size.h / cell) + 2\n  if (reduce) return (\n    <div className={`grid grid-cols-2 gap-3 sm:grid-cols-3 ${className ?? ''}`}>{photos.map((p) => <img key={p.src} src={p.src} alt={p.alt} className=\"aspect-square w-full object-cover\" />)}</div>\n  )\n  return (\n    <motion.div ref={ref} className={`relative touch-none cursor-grab overflow-hidden active:cursor-grabbing ${className ?? ''}`}\n      onPan={(_, i) => { x.set(x.get() + i.delta.x); y.set(y.get() + i.delta.y) }}\n      onPanEnd={(_, i) => { const glide = { duration: 0.9, ease: [0.22, 1, 0.36, 1] as const }; animate(x, x.get() + i.velocity.x * 0.25, glide); animate(y, y.get() + i.velocity.y * 0.25, glide) }}>\n      {Array.from({ length: cols * rows }, (_, k) => {\n        const ox = k % cols, oy = Math.floor(k / cols)\n        return <Tile key={k} photo={photos[(ox + oy * 3) % photos.length]} x={x} y={y} ox={ox} oy={oy} cols={cols} rows={rows} cell={cell} />\n      })}\n      <span className=\"pointer-events-none absolute bottom-4 left-1/2 -translate-x-1/2 bg-(--color-background) px-3 py-1 text-sm text-(--color-text)\">Drag to explore</span>\n    </motion.div>\n  )\n}\n",
  "tilted-grid": "'use client'\n// OpusKit piece — based on Componentry \"Scroll Tilted Grid\" (MIT © Componentry, https://componentry.dev).\n// A dense photo grid laid back in perspective that stands up flat as the visitor scrolls into it.\nimport { motion, useReducedMotion, useScroll, useTransform } from 'motion/react'\nimport { useRef } from 'react'\n\nexport function TiltedGrid({ photos, columns = 5, className }: { photos: { src: string; alt: string }[]; columns?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'center center'] })\n  const rotateX = useTransform(scrollYProgress, [0, 1], [45, 0])\n  const scale = useTransform(scrollYProgress, [0, 1], [0.8, 1])\n  const lift = useTransform(scrollYProgress, [0, 1], [80, 0])\n  return (\n    <div ref={ref} className={`overflow-hidden [perspective:1200px] ${className ?? ''}`}>\n      <motion.div className=\"grid gap-3\" style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`, ...(reduce ? {} : { rotateX, scale, transformOrigin: '50% 0%' }) }}>\n        {photos.map((p, i) => (\n          <motion.img key={p.src + i} src={p.src} alt={p.alt} className=\"aspect-[3/4] w-full object-cover\" style={reduce || i % 2 === 0 ? undefined : { y: lift }} />\n        ))}\n      </motion.div>\n    </div>\n  )\n}\n",
  "image-trail": "'use client'\n// OpusKit piece — based on Animata \"Trailing Image\" (MIT © Animata, https://animata.design).\n// Moving the cursor across the section leaves a short trail of photos that fade away. Fine pointers only.\nimport { AnimatePresence, motion, useReducedMotion } from 'motion/react'\nimport { useRef, useState, type ReactNode } from 'react'\n\ntype Drop = { id: number; x: number; y: number; src: string }\n\nexport function ImageTrail({ photos, children, spacing = 90, className }: { photos: string[]; children?: ReactNode; spacing?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const [drops, setDrops] = useState<Drop[]>([])\n  const last = useRef({ x: 0, y: 0, n: 0 })\n  const onMove = (e: React.PointerEvent<HTMLDivElement>) => {\n    if (reduce || e.pointerType !== 'mouse') return\n    const r = e.currentTarget.getBoundingClientRect()\n    const x = e.clientX - r.left, y = e.clientY - r.top\n    if (Math.hypot(x - last.current.x, y - last.current.y) < spacing) return\n    const n = ++last.current.n\n    last.current.x = x; last.current.y = y\n    setDrops((d) => [...d.slice(-6), { id: n, x, y, src: photos[n % photos.length] }])\n    setTimeout(() => setDrops((d) => d.filter((z) => z.id !== n)), 900)\n  }\n  return (\n    <div className={`relative overflow-hidden ${className ?? ''}`} onPointerMove={onMove}>\n      <AnimatePresence>\n        {drops.map((d) => (\n          <motion.img key={d.id} src={d.src} alt=\"\" aria-hidden className=\"pointer-events-none absolute z-0 w-40 -translate-x-1/2 -translate-y-1/2 object-cover\"\n            style={{ left: d.x, top: d.y }} initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.9 }} transition={{ duration: 0.35 }} />\n        ))}\n      </AnimatePresence>\n      <div className=\"relative z-10\">{children}</div>\n    </div>\n  )\n}\n",
  "tilt": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Tilt\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A card that leans toward the cursor in 3D. Keep the angle small (≤ 8°) so it reads as craft, not a gimmick.\nimport { motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring, useTransform } from 'motion/react'\nimport type { ReactNode } from 'react'\n\nexport function Tilt({ children, degrees = 8, className }: { children: ReactNode; degrees?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const x = useSpring(useMotionValue(0), { stiffness: 200, damping: 20 })\n  const y = useSpring(useMotionValue(0), { stiffness: 200, damping: 20 })\n  const rx = useTransform(y, [-0.5, 0.5], [degrees, -degrees])\n  const ry = useTransform(x, [-0.5, 0.5], [-degrees, degrees])\n  const transform = useMotionTemplate`perspective(900px) rotateX(${rx}deg) rotateY(${ry}deg)`\n  if (reduce) return <div className={className}>{children}</div>\n  return (\n    <motion.div className={className} style={{ transform, transformStyle: 'preserve-3d' }}\n      onPointerMove={(e) => { if (e.pointerType !== 'mouse') return; const r = e.currentTarget.getBoundingClientRect(); x.set((e.clientX - r.left) / r.width - 0.5); y.set((e.clientY - r.top) / r.height - 0.5) }}\n      onPointerLeave={() => { x.set(0); y.set(0) }}>\n      {children}\n    </motion.div>\n  )\n}\n",
  "cursor-area": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Cursor\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A custom cursor inside one area (a gallery, a hero) — e.g. a round \"View\" label over project photos.\n// Only on fine pointers; the system cursor stays everywhere else.\nimport { AnimatePresence, motion, useMotionValue, useReducedMotion, useSpring } from 'motion/react'\nimport { useState, type ReactNode } from 'react'\n\nexport function CursorArea({ children, label = 'View', className }: { children: ReactNode; label?: string; className?: string }) {\n  const reduce = useReducedMotion()\n  const [on, setOn] = useState(false)\n  const x = useSpring(useMotionValue(0), { stiffness: 500, damping: 40 })\n  const y = useSpring(useMotionValue(0), { stiffness: 500, damping: 40 })\n  return (\n    <div className={`relative ${on ? 'cursor-none' : ''} ${className ?? ''}`}\n      onPointerEnter={(e) => !reduce && e.pointerType === 'mouse' && setOn(true)} onPointerLeave={() => setOn(false)}\n      onPointerMove={(e) => { const r = e.currentTarget.getBoundingClientRect(); x.set(e.clientX - r.left); y.set(e.clientY - r.top) }}>\n      {children}\n      <AnimatePresence>\n        {on && (\n          <motion.span aria-hidden className=\"pointer-events-none absolute left-0 top-0 z-20 grid size-20 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-(--color-accent) text-sm text-(--color-background)\"\n            style={{ x, y }} initial={{ scale: 0 }} animate={{ scale: 1 }} exit={{ scale: 0 }} transition={{ duration: 0.2 }}>{label}</motion.span>\n        )}\n      </AnimatePresence>\n    </div>\n  )\n}\n",
  "magnetic": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Magnetic\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A button or link that leans toward the cursor when it comes near. Use on one or two primary actions only.\nimport { motion, useMotionValue, useReducedMotion, useSpring } from 'motion/react'\nimport type { ReactNode } from 'react'\n\nexport function Magnetic({ children, strength = 0.35, className }: { children: ReactNode; strength?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const x = useSpring(useMotionValue(0), { stiffness: 150, damping: 12, mass: 0.2 })\n  const y = useSpring(useMotionValue(0), { stiffness: 150, damping: 12, mass: 0.2 })\n  return (\n    <motion.span className={`inline-block ${className ?? ''}`} style={{ x, y }}\n      onPointerMove={(e) => { if (reduce || e.pointerType !== 'mouse') return; // reduced motion: stays put (same markup, so hydration matches)\n      const r = e.currentTarget.getBoundingClientRect(); x.set((e.clientX - r.left - r.width / 2) * strength); y.set((e.clientY - r.top - r.height / 2) * strength) }}\n      onPointerLeave={() => { x.set(0); y.set(0) }}>\n      {children}\n    </motion.span>\n  )\n}\n",
  "hover-highlight": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Animated Background\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// One highlight slides between items as the pointer (or focus) moves — nav links, filters, tabs, a list of names.\nimport { motion } from 'motion/react'\nimport { useId, useState, type ElementType } from 'react'\n\nexport function HoverHighlight({ link: L = 'a', items, className, itemClassName }: { link?: ElementType; items: { label: string; href: string }[]; className?: string; itemClassName?: string }) {\n  const [active, setActive] = useState<string | null>(null)\n  const id = useId()\n  return (\n    <ul className={`flex ${className ?? ''}`} onPointerLeave={() => setActive(null)}>\n      {items.map((it) => (\n        <li key={it.href} className=\"relative\">\n          {active === it.href && <motion.span layoutId={id} className=\"absolute inset-0 bg-(--color-surface)\" transition={{ type: 'spring', bounce: 0.15, duration: 0.35 }} />}\n          <L href={it.href} className={`relative block px-3 py-2 ${itemClassName ?? ''}`} onPointerEnter={() => setActive(it.href)} onFocus={() => setActive(it.href)} onBlur={() => setActive(null)}>{it.label}</L>\n        </li>\n      ))}\n    </ul>\n  )\n}\n",
  "scroll-progress": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Scroll Progress\" (MIT © 2024 ibelick, https://motion-primitives.com).\n// A hairline across the top that fills as the visitor reads. For long pages: journal posts, case studies, FAQs.\nimport { motion, useScroll, useSpring } from 'motion/react'\n\nexport function ScrollProgress({ className }: { className?: string }) {\n  const { scrollYProgress } = useScroll()\n  const scaleX = useSpring(scrollYProgress, { stiffness: 200, damping: 50, restDelta: 0.001 })\n  return <motion.div aria-hidden className={`fixed inset-x-0 top-0 z-50 h-0.5 origin-left bg-(--color-accent) ${className ?? ''}`} style={{ scaleX }} />\n}\n",
  "velocity-band": "'use client'\n// OpusKit piece — adapted from Magic UI \"Scroll Based Velocity\" (MIT © Magic UI, https://magicui.design).\n// A band of big type that drifts sideways and speeds up (or reverses) with the visitor's scroll.\nimport { motion, useAnimationFrame, useMotionValue, useReducedMotion, useScroll, useSpring, useTransform, useVelocity } from 'motion/react'\nimport { useRef } from 'react'\n\nconst wrap = (min: number, max: number, v: number) => ((((v - min) % (max - min)) + (max - min)) % (max - min)) + min\n\nexport function VelocityBand({ text, speed = 3, className }: { text: string; speed?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  const base = useMotionValue(0)\n  const { scrollY } = useScroll()\n  const velocity = useSpring(useVelocity(scrollY), { damping: 50, stiffness: 400 })\n  const factor = useTransform(velocity, [0, 1000], [0, 5], { clamp: false })\n  const x = useTransform(base, (v) => `${wrap(-50, -25, v)}%`)\n  const dir = useRef(1)\n  useAnimationFrame((_, delta) => {\n    if (reduce) return\n    const f = factor.get()\n    if (f < 0) dir.current = -1; else if (f > 0) dir.current = 1\n    base.set(base.get() + dir.current * speed * (delta / 1000) * (1 + Math.abs(f)))\n  })\n  return (\n    <div className={`overflow-hidden whitespace-nowrap ${className ?? ''}`} aria-label={text}>\n      <motion.div aria-hidden className=\"flex w-max\" style={reduce ? undefined : { x }}>\n        {[0, 1, 2, 3].map((k) => <span key={k} className=\"pr-[0.5em]\">{text}</span>)}\n      </motion.div>\n    </div>\n  )\n}\n",
  "pinned-stage": "'use client'\n// OpusKit piece — a pinned stage: the section holds still on screen while the visitor scrolls through its steps, and a\n// thin bar shows how far along they are. The one base for every pinned or scrubbed moment (proof one at a time, scroll\n// into an image, a story told in steps). Each step is a real element in the DOM, in order, for screen readers.\n// Original OpusKit code (MIT).\nimport { motion, useMotionValueEvent, useReducedMotion, useScroll, type MotionValue } from 'motion/react'\nimport { useRef, useState, useSyncExternalStore, type ReactNode } from 'react'\n\nexport function PinnedStage({ steps, perStep = 70, label, children }: {\n  /** One node per step. */ steps: ReactNode[]\n  /** Scroll length per step, in svh. */ perStep?: number\n  /** What the steps are, for the progress bar (e.g. \"Projects\"). */ label?: string\n  /** Optional: draw the stage yourself from the scroll progress (0–1) and the active step. */\n  children?: (p: { progress: MotionValue<number>; active: number }) => ReactNode\n}) {\n  const ref = useRef<HTMLDivElement>(null)\n  // Reduced motion applies once hydrated, so the server HTML and the first client render match.\n  const hydrated = useSyncExternalStore(() => () => {}, () => true, () => false)\n  const reduce = useReducedMotion() && hydrated\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end end'] })\n  const [active, setActive] = useState(0)\n  useMotionValueEvent(scrollYProgress, 'change', (v) => setActive(Math.min(steps.length - 1, Math.floor(v * steps.length))))\n\n  // Reduced motion: no pinning — the steps simply follow each other.\n  if (reduce) return <div ref={ref} className=\"space-y-16\">{steps.map((s, i) => <div key={i}>{s}</div>)}</div>\n\n  return (\n    <div ref={ref} style={{ height: `${steps.length * perStep + 100}svh` }} className=\"relative\">\n      <div className=\"sticky top-0 flex h-svh flex-col justify-center overflow-hidden\">\n        {children ? children({ progress: scrollYProgress, active }) : (\n          <div className=\"relative\">\n            {steps.map((s, i) => (\n              <motion.div key={i} aria-hidden={i !== active} className={i === 0 ? 'relative' : 'absolute inset-0'}\n                animate={{ opacity: i === active ? 1 : 0, y: i === active ? 0 : i < active ? -24 : 24 }} transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}>{s}</motion.div>\n            ))}\n          </div>\n        )}\n        <div className=\"absolute inset-x-(--gutter,24px) bottom-6 flex items-center gap-4 font-(family-name:--font-utility) text-sm text-(--color-muted)\">\n          {label && <span>{label}</span>}\n          <span className=\"relative h-px flex-1 bg-(--color-border)\"><motion.span className=\"absolute inset-y-0 left-0 w-full origin-left bg-(--color-text)\" style={{ scaleX: scrollYProgress }} /></span>\n          <span className=\"tabular-nums\">{active + 1} of {steps.length}</span>\n        </div>\n      </div>\n    </div>\n  )\n}\n",
  "sticky-cards": "'use client'\n// OpusKit piece — based on Componentry \"Sticky Scroll Cards\" (MIT © Componentry, https://componentry.dev).\n// Cards stack on top of each other while scrolling; each one settles and shrinks slightly as the next arrives.\nimport { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from 'motion/react'\nimport { useRef, type ReactNode } from 'react'\n\nfunction Card({ children, i, total, progress }: { children: ReactNode; i: number; total: number; progress: MotionValue<number> }) {\n  const scale = useTransform(progress, [i / total, 1], [1, 1 - (total - i) * 0.04])\n  return (\n    <div className=\"sticky flex h-[85svh] items-start justify-center\" style={{ top: `calc(8svh + ${i * 1.5}rem)` }}>\n      <motion.div className=\"h-[70svh] w-full origin-top overflow-hidden bg-(--color-surface)\" style={{ scale }}>{children}</motion.div>\n    </div>\n  )\n}\n\nexport function StickyCards({ cards, className }: { cards: ReactNode[]; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end end'] })\n  if (reduce) return <div className={`grid gap-6 ${className ?? ''}`}>{cards.map((c, i) => <div key={i} className=\"bg-(--color-surface)\">{c}</div>)}</div>\n  return <div ref={ref} className={className}>{cards.map((c, i) => <Card key={i} i={i} total={cards.length} progress={scrollYProgress}>{c}</Card>)}</div>\n}\n",
  "grid-pattern": "// OpusKit piece — adapted from Magic UI \"Grid Pattern\" (MIT © Magic UI, https://magicui.design).\n// Hairline grid behind a section, drawn in the border token; optional filled cells mark real positions (a seat map, a schedule).\nimport { useId } from 'react'\n\nexport function GridPattern({ size = 48, cells = [], fade = true, className }: { size?: number; cells?: [number, number][]; fade?: boolean; className?: string }) {\n  const id = useId()\n  return (\n    <svg aria-hidden className={`pointer-events-none absolute inset-0 size-full stroke-(--color-border) ${className ?? ''}`}\n      style={fade ? { maskImage: 'radial-gradient(ellipse at center, black 40%, transparent 80%)' } : undefined}>\n      <defs>\n        <pattern id={id} width={size} height={size} patternUnits=\"userSpaceOnUse\" x={-1} y={-1}>\n          <path d={`M.5 ${size}V.5H${size}`} fill=\"none\" />\n        </pattern>\n      </defs>\n      <rect width=\"100%\" height=\"100%\" strokeWidth={0} fill={`url(#${id})`} />\n      {cells.map(([x, y]) => <rect key={`${x}-${y}`} className=\"fill-(--color-accent)/15\" strokeWidth={0} width={size - 1} height={size - 1} x={x * size} y={y * size} />)}\n    </svg>\n  )\n}\n",
  "grain": "// OpusKit piece — adapted from Magic UI \"Noise Texture\" (MIT © Magic UI, https://magicui.design).\n// Film grain over a section or the whole page, generated in SVG (no image file). Keep it at ≤ 4–8% so it is felt, not seen.\nimport { useId } from 'react'\n\nexport function Grain({ opacity = 0.06, frequency = 0.75, fixed = false, className }: { opacity?: number; frequency?: number; fixed?: boolean; className?: string }) {\n  const id = useId()\n  return (\n    <svg aria-hidden className={`pointer-events-none inset-0 z-40 size-full select-none mix-blend-multiply ${fixed ? 'fixed' : 'absolute'} ${className ?? ''}`} style={{ opacity }}>\n      <filter id={id}>\n        <feTurbulence type=\"fractalNoise\" baseFrequency={frequency} numOctaves={3} stitchTiles=\"stitch\" />\n        <feColorMatrix type=\"saturate\" values=\"0\" />\n      </filter>\n      <rect width=\"100%\" height=\"100%\" filter={`url(#${id})`} />\n    </svg>\n  )\n}\n",
  "magnet-lines": "'use client'\n// OpusKit piece — adapted from Componentry \"Magnet Lines\" (MIT © Componentry, https://componentry.dev).\n// A grid of short lines that all turn to point at the cursor, like iron filings. A quiet, graphic hero or footer field.\nimport { useReducedMotion } from 'motion/react'\nimport { useEffect, useRef } from 'react'\n\nexport function MagnetLines({ rows = 9, columns = 12, className }: { rows?: number; columns?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  useEffect(() => {\n    const el = ref.current\n    if (!el || reduce) return\n    const lines = [...el.children] as HTMLElement[]\n    let frame = 0\n    const move = (e: PointerEvent) => {\n      cancelAnimationFrame(frame)\n      frame = requestAnimationFrame(() => {\n        for (const l of lines) {\n          const r = l.getBoundingClientRect()\n          const a = Math.atan2(e.clientY - (r.top + r.height / 2), e.clientX - (r.left + r.width / 2))\n          l.style.transform = `rotate(${a + Math.PI / 2}rad)`\n        }\n      })\n    }\n    window.addEventListener('pointermove', move, { passive: true })\n    return () => { window.removeEventListener('pointermove', move); cancelAnimationFrame(frame) }\n  }, [reduce])\n  return (\n    <div ref={ref} aria-hidden className={`grid place-items-center ${className ?? ''}`} style={{ gridTemplateColumns: `repeat(${columns}, 1fr)`, gridTemplateRows: `repeat(${rows}, 1fr)` }}>\n      {Array.from({ length: rows * columns }, (_, i) => <span key={i} className=\"block h-[3vmin] w-px bg-(--color-text) transition-transform duration-300 ease-out\" />)}\n    </div>\n  )\n}\n",
  "video-dialog": "'use client'\n// OpusKit piece — adapted from Magic UI \"Hero Video Dialog\" (MIT © Magic UI, https://magicui.design).\n// A still (the poster) with a play button; clicking opens the full film with sound in a dialog. Esc or the backdrop closes it.\nimport { AnimatePresence, motion } from 'motion/react'\nimport { useEffect, useState } from 'react'\n\nexport function VideoDialog({ poster, src, title, className }: { poster: string; src: string; title: string; className?: string }) {\n  const [open, setOpen] = useState(false)\n  useEffect(() => {\n    if (!open) return\n    const esc = (e: KeyboardEvent) => e.key === 'Escape' && setOpen(false)\n    window.addEventListener('keydown', esc)\n    return () => window.removeEventListener('keydown', esc)\n  }, [open])\n  return (\n    <>\n      <button type=\"button\" onClick={() => setOpen(true)} className={`group relative block overflow-hidden ${className ?? ''}`} aria-label={`Play: ${title}`}>\n        <img src={poster} alt=\"\" className=\"size-full object-cover transition-transform duration-500 group-hover:scale-[1.02]\" />\n        <span className=\"absolute left-1/2 top-1/2 grid size-20 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-(--color-background) text-(--color-text) transition-transform group-hover:scale-110\">\n          <svg viewBox=\"0 0 24 24\" className=\"ml-1 size-7 fill-current\" aria-hidden><path d=\"M7 4.5v15l13-7.5z\" /></svg>\n        </span>\n      </button>\n      <AnimatePresence>\n        {open && (\n          <motion.div role=\"dialog\" aria-modal=\"true\" aria-label={title} className=\"fixed inset-0 z-50 grid place-items-center bg-(--color-text)/85 p-4 md:p-12\"\n            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setOpen(false)}>\n            <motion.video src={src} poster={poster} controls autoPlay playsInline className=\"max-h-full w-full max-w-6xl bg-black\" onClick={(e) => e.stopPropagation()}\n              initial={{ scale: 0.94, y: 20 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.94, y: 20 }} transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }} />\n            <button type=\"button\" className=\"absolute right-4 top-4 px-3 py-2 text-(--color-background)\" onClick={() => setOpen(false)}>Close</button>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </>\n  )\n}\n",
  "media-between-text": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Media Between Text\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// A headline split in two; when it scrolls into view the words part and a photo (or clip) opens between them.\nimport { motion, useInView, useReducedMotion } from 'motion/react'\nimport { useRef } from 'react'\n\nexport function MediaBetweenText({ before, after, src, alt, video = false, width = '18vw', className }: {\n  before: string; after: string; src: string; alt: string; video?: boolean; width?: string; className?: string\n}) {\n  const ref = useRef<HTMLHeadingElement>(null)\n  const inView = useInView(ref, { once: true, amount: 0.7 })\n  const reduce = useReducedMotion()\n  const open = reduce || inView\n  return (\n    <h2 ref={ref} className={`flex flex-wrap items-center justify-center gap-x-[0.2em] ${className ?? ''}`}>\n      <span>{before}</span>\n      <motion.span className=\"inline-block overflow-hidden align-middle\" initial={false} animate={{ width: open ? width : 0, opacity: open ? 1 : 0 }} transition={{ duration: 0.9, ease: [0.65, 0, 0.35, 1] }} style={{ height: '0.85em' }}>\n        {video ? <video src={src} autoPlay muted loop playsInline className=\"size-full object-cover\" aria-label={alt} />\n          : <img src={src} alt={alt} className=\"size-full object-cover\" />}\n      </motion.span>\n      <span>{after}</span>\n    </h2>\n  )\n}\n",
  "cut-reveal": "'use client'\n// OpusKit piece — adapted from Motion Primitives \"Text Effect\" (MIT © 2024 ibelick, https://motion-primitives.com); the `cut`\n// preset from Fancy Components \"Vertical Cut Reveal\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// Reveals a headline word by word (or letter by letter) once it enters the viewport: `slide`, `blur`, `fade`, or `cut` —\n// each word slides up out of a hard mask, sharper than a fade. Colors and fonts come from the recipe tokens.\nimport { motion, useReducedMotion, type Variants } from 'motion/react'\nimport type { JSX } from 'react'\n\ntype Preset = 'blur' | 'slide' | 'fade' | 'cut'\nconst ITEM: Record<Preset, Variants> = {\n  blur: { hidden: { opacity: 0, filter: 'blur(10px)', y: 8 }, visible: { opacity: 1, filter: 'blur(0px)', y: 0 } },\n  slide: { hidden: { opacity: 0, y: '0.6em' }, visible: { opacity: 1, y: 0 } },\n  fade: { hidden: { opacity: 0 }, visible: { opacity: 1 } },\n  cut: { hidden: { y: '105%' }, visible: { y: 0 } },\n}\n\nexport function TextEffect({ children, as = 'h2', per = 'word', preset = 'slide', delay = 0, className }: {\n  children: string; as?: keyof JSX.IntrinsicElements; per?: 'word' | 'char'; preset?: Preset; delay?: number; className?: string\n}) {\n  const reduce = useReducedMotion()\n  const Tag = motion[as as 'h2']\n  const parts = per === 'word' ? children.split(/(\\s+)/) : children.split('')\n  const timing = reduce ? { duration: 0 } : preset === 'cut' ? { type: 'spring' as const, stiffness: 190, damping: 22 } : { duration: 0.5, ease: [0.22, 1, 0.36, 1] as const }\n  return (\n    <Tag className={className} initial=\"hidden\" whileInView=\"visible\" viewport={{ once: true, amount: 0.6 }}\n      transition={reduce ? { duration: 0 } : { staggerChildren: per === 'word' ? (preset === 'cut' ? 0.07 : 0.06) : 0.025, delayChildren: delay }}> {/* same markup either way (hydration); reduced motion only drops the timing */}\n      <span className=\"sr-only\">{children}</span>\n      {parts.map((p, i) => /^\\s+$/.test(p) ? p /* plain spaces, so a wrapped line never starts indented */ : preset === 'cut' ? (\n        <span key={i} aria-hidden className=\"inline-flex overflow-hidden pb-[0.08em] align-bottom\">\n          <motion.span className=\"inline-block whitespace-pre\" variants={ITEM.cut} transition={timing}>{p}</motion.span>\n        </span>\n      ) : (\n        <motion.span key={i} aria-hidden className=\"inline-block whitespace-pre\" variants={ITEM[preset]} transition={timing}>{p}</motion.span>\n      ))}\n    </Tag>\n  )\n}\n",
  "underline-fill": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Underline To Background\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// A link whose underline grows into a full background block on hover or focus, flipping the text colour.\n// In-site links pass the site's own link component (next/link) as `link`, so they keep client navigation and basePath.\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useState, type ElementType, type ReactNode } from 'react'\n\nexport function UnderlineFill({ link: L = 'a', href, children, className }: { link?: ElementType; href: string; children: ReactNode; className?: string }) {\n  const [on, setOn] = useState(false)\n  const reduce = useReducedMotion()\n  const fill = on && !reduce\n  return (\n    <L href={href} className={`relative inline-block px-[0.1em] ${className ?? ''}`}\n      onPointerEnter={() => setOn(true)} onPointerLeave={() => setOn(false)} onFocus={() => setOn(true)} onBlur={() => setOn(false)}>\n      <motion.span aria-hidden className=\"absolute inset-x-0 bottom-0 -z-0 bg-(--color-text)\" initial={false} animate={{ height: fill ? '100%' : '0.08em' }} transition={{ duration: 0.25, ease: [0.65, 0, 0.35, 1] }} />\n      <motion.span className=\"relative\" initial={false} animate={{ color: fill ? 'var(--color-background)' : 'var(--color-text)' }} transition={{ duration: 0.2 }}>{children}</motion.span>\n    </L>\n  )\n}\n",
  "parallax-floating": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Parallax Floating\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// Photos scattered around a headline drift against the cursor at different depths, like objects in a vitrine.\nimport { motion, useMotionValue, useReducedMotion, useSpring, useTransform, type MotionValue } from 'motion/react'\nimport type { ReactNode } from 'react'\n\nexport type FloatingPhoto = { src: string; alt: string; x: string; y: string; w: string; depth: number }\n\nfunction Floater({ p, mx, my }: { p: FloatingPhoto; mx: MotionValue<number>; my: MotionValue<number> }) {\n  const x = useTransform(mx, (v) => v * p.depth * -30)\n  const y = useTransform(my, (v) => v * p.depth * -30)\n  return <motion.img src={p.src} alt={p.alt} className=\"absolute object-cover\" style={{ left: p.x, top: p.y, width: p.w, x, y }} />\n}\n\nexport function ParallaxFloating({ photos, children, className }: { photos: FloatingPhoto[]; children?: ReactNode; className?: string }) {\n  const reduce = useReducedMotion()\n  const mx = useSpring(useMotionValue(0), { stiffness: 60, damping: 20 })\n  const my = useSpring(useMotionValue(0), { stiffness: 60, damping: 20 })\n  return (\n    <div className={`relative overflow-hidden ${className ?? ''}`}\n      onPointerMove={(e) => { if (reduce || e.pointerType !== 'mouse') return; const r = e.currentTarget.getBoundingClientRect(); mx.set((e.clientX - r.left) / r.width - 0.5); my.set((e.clientY - r.top) / r.height - 0.5) }}\n      onPointerLeave={() => { mx.set(0); my.set(0) }}>\n      {photos.map((p) => <Floater key={p.src + p.x} p={p} mx={mx} my={my} />)}\n      <div className=\"relative z-10 grid size-full place-items-center\">{children}</div>\n    </div>\n  )\n}\n",
  "drag-photos": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Drag Elements\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// Photos scattered like prints on a desk; visitors pick one up and drag it around, the last one lands on top.\nimport { motion } from 'motion/react'\nimport { useRef, useState } from 'react'\n\nexport type DeskPhoto = { src: string; alt: string; x: string; y: string; w: string; rotate: number }\n\nexport function DragPhotos({ photos, className }: { photos: DeskPhoto[]; className?: string }) {\n  const area = useRef<HTMLDivElement>(null)\n  const [order, setOrder] = useState(photos.map((_, i) => i))\n  const front = (i: number) => setOrder((o) => [...o.filter((x) => x !== i), i])\n  return (\n    <div ref={area} className={`relative overflow-hidden ${className ?? ''}`}>\n      {photos.map((p, i) => (\n        <motion.img key={p.src + i} src={p.src} alt={p.alt} draggable={false} drag dragConstraints={area} dragElastic={0.2}\n          onPointerDown={() => front(i)} whileDrag={{ scale: 1.04, rotate: 0 }}\n          className=\"absolute cursor-grab touch-none bg-(--color-surface) object-cover p-[0.6%] shadow-[0_10px_30px_rgb(0_0_0/0.18)] active:cursor-grabbing\"\n          style={{ left: p.x, top: p.y, width: p.w, rotate: p.rotate, zIndex: order.indexOf(i) }} />\n      ))}\n    </div>\n  )\n}\n",
  "text-along-path": "'use client'\n// OpusKit piece — adapted from Fancy Components \"Text Along Path\" (MIT © 2024 Daniel Petho, https://fancycomponents.dev).\n// A line of text that runs along a curve and travels along it as the visitor scrolls.\nimport { motion, useReducedMotion, useScroll, useTransform } from 'motion/react'\nimport { useId, useRef } from 'react'\n\nexport function TextAlongPath({ text, path = 'M0,80 C200,0 400,160 600,80 S1000,0 1200,80', className }: { text: string; path?: string; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const id = useId()\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] })\n  const offset = useTransform(scrollYProgress, [0, 1], ['0%', '-60%'])\n  return (\n    <div ref={ref} className={className}>\n    <svg viewBox=\"0 0 1200 160\" className=\"w-full overflow-visible fill-(--color-text)\" role=\"img\" aria-label={text}>\n      <path id={id} d={path} fill=\"none\" />\n      <text aria-hidden>\n        <motion.textPath href={`#${id}`} startOffset={reduce ? '0%' : offset}>{`${text} ${text} ${text}`}</motion.textPath>\n      </text>\n    </svg>\n    </div>\n  )\n}\n",
  "shader-grain": "'use client'\n// OpusKit piece — uses Paper Shaders \"Grain Gradient\" (Apache-2.0 © Paper Design, https://shaders.paper.design).\n// A slow, grainy colour field drawn on the GPU from the recipe's own colours — a living background with the texture of print.\nimport { GrainGradient } from '@paper-design/shaders-react'\nimport { useReducedMotion } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nconst read = (el: Element, v: string) => getComputedStyle(el).getPropertyValue(v).trim()\n\nexport function ShaderGrain({ shape = 'wave', className }: { shape?: 'wave' | 'dots' | 'truchet' | 'corners' | 'ripple' | 'blob'; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const [c, setC] = useState<{ back: string; colors: string[] } | null>(null)\n  useEffect(() => { const el = ref.current; if (el) setC({ back: read(el, '--color-background'), colors: [read(el, '--color-accent'), read(el, '--color-surface'), read(el, '--color-text')] }) }, [])\n  return (\n    <div ref={ref} aria-hidden className={`pointer-events-none absolute inset-0 ${className ?? ''}`}>\n      {c && <GrainGradient style={{ width: '100%', height: '100%' }} colorBack={c.back} colors={c.colors} softness={0.7} intensity={0.25} noise={0.35} shape={shape} speed={reduce ? 0 : 0.4} />}\n    </div>\n  )\n}\n",
  "shader-dither": "'use client'\n// OpusKit piece — uses Paper Shaders \"Dithering\" (Apache-2.0 © Paper Design, https://shaders.paper.design).\n// A 1-bit dithered pattern in two recipe colours, like an old screen or a risograph — graphic, never glossy.\nimport { Dithering } from '@paper-design/shaders-react'\nimport { useReducedMotion } from 'motion/react'\nimport { useEffect, useRef, useState } from 'react'\n\nconst read = (el: Element, v: string) => getComputedStyle(el).getPropertyValue(v).trim()\n\nexport function ShaderDither({ shape = 'warp', size = 3, className }: { shape?: 'simplex' | 'warp' | 'dots' | 'wave' | 'ripple' | 'swirl' | 'sphere'; size?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = useReducedMotion()\n  const [c, setC] = useState<{ back: string; front: string } | null>(null)\n  useEffect(() => { const el = ref.current; if (el) setC({ back: read(el, '--color-background'), front: read(el, '--color-accent') }) }, [])\n  return (\n    <div ref={ref} aria-hidden className={`pointer-events-none absolute inset-0 ${className ?? ''}`}>\n      {c && <Dithering style={{ width: '100%', height: '100%' }} colorBack={c.back} colorFront={c.front} shape={shape} type=\"4x4\" size={size} speed={reduce ? 0 : 0.3} />}\n    </div>\n  )\n}\n",
  "duo-headline": "'use client'\n// OpusKit piece — two-voice headline: one whole word (or phrase) in the loud display face, the rest in the quiet\n// heading face at the same size; letters rise out of a line mask when it comes into view. Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport type { JSX } from 'react'\n\nfunction Letters({ text, from }: { text: string; from: number }) {\n  return <>{[...text].map((ch, i) => (\n    <span key={i} className=\"inline-block overflow-hidden pb-[0.06em] align-bottom\">\n      <motion.span className=\"inline-block\" variants={{ hidden: { y: '110%' }, shown: { y: 0 } }} transition={{ type: 'spring', stiffness: 200, damping: 24, delay: (from + i) * 0.025 }}>{ch === ' ' ? ' ' : ch}</motion.span>\n    </span>\n  ))}</>\n}\n\nexport function DuoHeadline({ loud, quiet, as = 'h2', className }: { loud: string; quiet: string; as?: keyof JSX.IntrinsicElements; className?: string }) {\n  const reduce = useReducedMotion()\n  const Tag = motion[as as 'h2']\n  return (\n    <Tag className={`type-display flex flex-wrap items-baseline justify-center gap-x-[0.25em] ${className ?? ''}`} initial={reduce ? false : 'hidden'} whileInView=\"shown\" viewport={{ once: true, amount: 0.6 }} aria-label={`${loud} ${quiet}`}>\n      <span aria-hidden><Letters text={loud} from={0} /></span>\n      <span aria-hidden className=\"font-(family-name:--font-heading) [font-stretch:var(--type-heading-stretch)] [font-weight:var(--type-heading-weight)]\"><Letters text={quiet} from={loud.length} /></span>\n    </Tag>\n  )\n}\n",
  "scribble-link": "'use client'\n// OpusKit piece — a link whose underline draws itself on hover or focus; the current page keeps it. Two strokes:\n// `scribble` — a hand-drawn squiggle (navigation), `wave` — an even wave (footer and inline links). Original OpusKit code (MIT).\n// The line hangs just under the text and takes no room, so a link lines up with whatever sits beside it.\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useState, type ElementType, type ReactNode } from 'react'\n\nconst STROKES = {\n  scribble: { d: 'M2 7 C 12 3, 22 10, 34 6 S 58 2, 70 6 S 92 11, 98 5', box: '0 0 100 12', width: 2.2, h: 'h-2', ink: 'text-(--color-chapter-1,var(--color-accent))', time: 0.45 },\n  wave: { d: 'M0 5 Q 5 0 10 5 T 20 5 T 30 5 T 40 5 T 50 5 T 60 5 T 70 5 T 80 5 T 90 5 T 100 5', box: '0 0 100 10', width: 1.6, h: 'h-1.5', ink: 'text-(--color-chapter-2,var(--color-accent))', time: 0.35 },\n}\n\nexport function DrawnLink({ link: L = 'a', href, children, stroke = 'scribble', current = false, className }: { link?: ElementType; href: string; children: ReactNode; stroke?: keyof typeof STROKES; current?: boolean; className?: string }) {\n  const [on, setOn] = useState(false)\n  const reduce = useReducedMotion()\n  const s = STROKES[stroke], drawn = current || on\n  return (\n    <L href={href} aria-current={current ? 'page' : undefined} className={`relative inline-block ${className ?? ''}`}\n      onPointerEnter={() => setOn(true)} onPointerLeave={() => setOn(false)} onFocus={() => setOn(true)} onBlur={() => setOn(false)}>\n      {children}\n      <svg aria-hidden viewBox={s.box} preserveAspectRatio=\"none\" className={`absolute inset-x-0 top-[calc(50%+0.6em)] ${s.h} w-full overflow-visible ${s.ink}`}>\n        <motion.path d={s.d} fill=\"none\" stroke=\"currentColor\" strokeWidth={s.width} strokeLinecap=\"round\" vectorEffect=\"non-scaling-stroke\"\n          initial={false} animate={{ pathLength: drawn ? 1 : 0, opacity: drawn ? 1 : 0 }} transition={{ duration: reduce ? 0 : s.time, ease: [0.65, 0, 0.35, 1] }} />\n      </svg>\n    </L>\n  )\n}\n",
  "wavy-link": "'use client'\n// OpusKit piece — a link whose underline draws itself on hover or focus; the current page keeps it. Two strokes:\n// `scribble` — a hand-drawn squiggle (navigation), `wave` — an even wave (footer and inline links). Original OpusKit code (MIT).\n// The line hangs just under the text and takes no room, so a link lines up with whatever sits beside it.\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useState, type ElementType, type ReactNode } from 'react'\n\nconst STROKES = {\n  scribble: { d: 'M2 7 C 12 3, 22 10, 34 6 S 58 2, 70 6 S 92 11, 98 5', box: '0 0 100 12', width: 2.2, h: 'h-2', ink: 'text-(--color-chapter-1,var(--color-accent))', time: 0.45 },\n  wave: { d: 'M0 5 Q 5 0 10 5 T 20 5 T 30 5 T 40 5 T 50 5 T 60 5 T 70 5 T 80 5 T 90 5 T 100 5', box: '0 0 100 10', width: 1.6, h: 'h-1.5', ink: 'text-(--color-chapter-2,var(--color-accent))', time: 0.35 },\n}\n\nexport function DrawnLink({ link: L = 'a', href, children, stroke = 'scribble', current = false, className }: { link?: ElementType; href: string; children: ReactNode; stroke?: keyof typeof STROKES; current?: boolean; className?: string }) {\n  const [on, setOn] = useState(false)\n  const reduce = useReducedMotion()\n  const s = STROKES[stroke], drawn = current || on\n  return (\n    <L href={href} aria-current={current ? 'page' : undefined} className={`relative inline-block ${className ?? ''}`}\n      onPointerEnter={() => setOn(true)} onPointerLeave={() => setOn(false)} onFocus={() => setOn(true)} onBlur={() => setOn(false)}>\n      {children}\n      <svg aria-hidden viewBox={s.box} preserveAspectRatio=\"none\" className={`absolute inset-x-0 top-[calc(50%+0.6em)] ${s.h} w-full overflow-visible ${s.ink}`}>\n        <motion.path d={s.d} fill=\"none\" stroke=\"currentColor\" strokeWidth={s.width} strokeLinecap=\"round\" vectorEffect=\"non-scaling-stroke\"\n          initial={false} animate={{ pathLength: drawn ? 1 : 0, opacity: drawn ? 1 : 0 }} transition={{ duration: reduce ? 0 : s.time, ease: [0.65, 0, 0.35, 1] }} />\n      </svg>\n    </L>\n  )\n}\n",
  "swap-button": "'use client'\n// OpusKit piece — a playful button: on hover the arrow box hops from the left to the right of the label and the\n// whole button tilts a little, like a sticker being peeled. In-site links pass the site's link component (next/link)\n// as `link`. Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useState, type ElementType } from 'react'\n\nconst Arrow = () => <svg viewBox=\"0 0 16 16\" className=\"size-4\" aria-hidden><path d=\"M2 8h11M9 4l4 4-4 4\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" /></svg>\n\nexport function SwapButton({ link: L = 'a', href, label, className }: { link?: ElementType; href: string; label: string; className?: string }) {\n  const [on, setOn] = useState(false)\n  const reduce = useReducedMotion()\n  const box = <motion.span layout={!reduce} className=\"grid size-11 place-items-center bg-(--color-chapter-2,var(--color-accent)) text-(--color-text)\"><Arrow /></motion.span>\n  return (\n    <L href={href} className={`type-utility inline-flex [font-family:var(--font-body)] ${className ?? ''}`}\n      onPointerEnter={() => setOn(true)} onPointerLeave={() => setOn(false)} onFocus={() => setOn(true)} onBlur={() => setOn(false)}>\n      <motion.span className=\"inline-flex items-stretch gap-1\" animate={{ rotate: on && !reduce ? -3 : 0 }} transition={{ type: 'spring', stiffness: 300, damping: 18 }}>\n        {!on && box}\n        <motion.span layout={!reduce} className=\"flex items-center bg-(--color-chapter-2,var(--color-accent)) px-4 font-semibold uppercase tracking-tight text-(--color-text)\">{label}</motion.span>\n        {on && box}\n      </motion.span>\n    </L>\n  )\n}\n",
  "stickers": "'use client'\n// OpusKit piece — brand stickers stuck onto a section: each sits at its own angle, drifts with scroll at its own depth,\n// and can be picked up and thrown (it slides to a stop). Put it inside a `relative` section. Original OpusKit code (MIT).\nimport { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from 'motion/react'\nimport { useRef } from 'react'\n\nexport type Sticker = { src: string; alt: string; x: string; y: string; w: string; rotate: number; depth?: number }\n\nfunction One({ s, progress, reduce }: { s: Sticker; progress: MotionValue<number>; reduce: boolean }) {\n  const y = useTransform(progress, [0, 1], [0, reduce ? 0 : -(s.depth ?? 1) * 120])\n  return (\n    <motion.div className=\"absolute\" style={{ left: s.x, top: s.y, width: s.w, y }}>\n      <motion.img src={s.src} alt={s.alt} draggable={false} drag={!reduce} dragMomentum dragTransition={{ power: 0.25, timeConstant: 220 }}\n        whileDrag={{ scale: 1.08, rotate: s.rotate + 4 }} whileHover={reduce ? undefined : { scale: 1.04 }} style={{ rotate: s.rotate }}\n        className=\"pointer-events-auto w-full cursor-grab touch-none select-none active:cursor-grabbing\" />\n    </motion.div>\n  )\n}\n\nexport function Stickers({ stickers, className }: { stickers: Sticker[]; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const reduce = !!useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] })\n  return <div ref={ref} className={`pointer-events-none absolute inset-0 z-20 ${className ?? ''}`}>{stickers.map((s) => <One key={s.src + s.x} s={s} progress={scrollYProgress} reduce={reduce} />)}</div>\n}\n",
  "fade-transition": "'use client'\n// OpusKit piece — page transition: clicking an internal link softly veils the page in its own ground colour, the next\n// page loads underneath, and the veil fades away (about half a second in all). For calm sites, where a curtain would\n// shout. Mount once in the root layout. Respects reduced motion (plain navigation). Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { usePathname } from 'next/navigation'\nimport { useEffect, useState } from 'react'\n\nexport function PageFade({ color = 'var(--color-background)' }: { color?: string }) {\n  const path = usePathname()\n  const reduce = useReducedMotion()\n  const [phase, setPhase] = useState<'idle' | 'cover' | 'reveal'>('idle')\n  useEffect(() => {\n    if (reduce) return\n    let replaying = false\n    const onClick = (e: MouseEvent) => {\n      if (replaying) return\n      const a = (e.target as HTMLElement).closest('a')\n      if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || a.target === '_blank' || a.hasAttribute('download')) return\n      const url = new URL(a.href, location.href)\n      if (url.origin !== location.origin || (url.pathname === location.pathname && url.hash)) return\n      e.preventDefault()\n      e.stopPropagation() // capture phase: hold the click, veil the page, then replay it for next/link\n      setPhase('cover')\n      setTimeout(() => { replaying = true; a.click(); replaying = false }, 220)\n      setTimeout(() => setPhase((p) => (p === 'cover' ? 'reveal' : p)), 1200) // same pathname: lift the veil anyway\n    }\n    document.addEventListener('click', onClick, true)\n    return () => document.removeEventListener('click', onClick, true)\n  }, [reduce])\n  // The new page has arrived: lift the veil (state adjusted while rendering, not in an effect).\n  const [shownPath, setShownPath] = useState(path)\n  if (shownPath !== path) { setShownPath(path); if (phase === 'cover') setPhase('reveal') }\n  if (phase === 'idle') return null\n  return (\n    <motion.div aria-hidden className=\"pointer-events-none fixed inset-0 z-[100]\" style={{ background: color }}\n      initial={{ opacity: 0 }} animate={{ opacity: phase === 'cover' ? 1 : 0 }}\n      transition={{ duration: phase === 'cover' ? 0.22 : 0.32, ease: 'easeOut' }}\n      onAnimationComplete={() => { if (phase === 'reveal') setPhase('idle') }} />\n  )\n}\n",
  "blob-transition": "'use client'\n// OpusKit piece — page transition: clicking an internal link sends an organic blob of colour up over the page; the\n// next page is revealed as the blob keeps travelling off the top. Mount once in the root layout. Respects reduced\n// motion (plain navigation). Original OpusKit code (MIT).\nimport { AnimatePresence, motion, useReducedMotion } from 'motion/react'\nimport { usePathname } from 'next/navigation'\nimport { useEffect, useState } from 'react'\n\nexport function BlobTransition({ color = 'var(--color-chapter-1, var(--color-accent))' }: { color?: string }) {\n  const path = usePathname()\n  const reduce = useReducedMotion()\n  const [phase, setPhase] = useState<'idle' | 'cover' | 'reveal'>('idle')\n  useEffect(() => {\n    if (reduce) return\n    let replaying = false\n    const onClick = (e: MouseEvent) => {\n      if (replaying) return\n      const a = (e.target as HTMLElement).closest('a')\n      if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || a.target === '_blank' || a.hasAttribute('download')) return\n      const url = new URL(a.href, location.href)\n      if (url.origin !== location.origin || (url.pathname === location.pathname && url.hash)) return\n      e.preventDefault()\n      e.stopPropagation() // capture phase: hold the click before next/link sees it, then replay it once the page is covered\n      setPhase('cover')\n      setTimeout(() => { replaying = true; a.click(); replaying = false }, 550) // next/link navigates (basePath, prefetch, its own handlers)\n    }\n    document.addEventListener('click', onClick, true)\n    return () => document.removeEventListener('click', onClick, true)\n  }, [reduce])\n  useEffect(() => { setPhase((p) => (p === 'cover' ? 'reveal' : p)) }, [path])\n  return (\n    <AnimatePresence onExitComplete={() => setPhase('idle')}>\n      {phase !== 'idle' && (\n        <motion.div key=\"blob\" aria-hidden className=\"pointer-events-none fixed inset-x-[-20%] z-[100] h-[140svh]\" style={{ background: color }}\n          initial={{ y: '100svh', borderRadius: '50% 50% 0 0 / 30% 30% 0 0' }}\n          animate={phase === 'cover' ? { y: '-20svh', borderRadius: '40% 60% 0 0 / 12% 18% 0 0' } : { y: '-160svh', borderRadius: '0 0 60% 40% / 0 0 30% 20%' }}\n          exit={{ opacity: 0 }} transition={{ duration: 0.55, ease: [0.76, 0, 0.24, 1] }}\n          onAnimationComplete={() => { if (phase === 'reveal') setPhase('idle') }} />\n      )}\n    </AnimatePresence>\n  )\n}\n",
  "brand-cursor": "'use client'\n// OpusKit piece — a brand cursor: a hand-drawn arrow (or your own SVG) replaces the system arrow on fine pointers.\n// Links and buttons keep the system pointer so clickable things still read as clickable. Original OpusKit code (MIT).\nimport { useEffect } from 'react'\n\nconst drawn = (fill: string) => `data:image/svg+xml,${encodeURIComponent(`<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"28\" height=\"32\" viewBox=\"0 0 28 32\"><path d=\"M3 2 C 9 12, 14 20, 17 28 L 19.5 19.5 L 27 17.5 C 19 12, 10 6, 3 2 Z\" fill=\"${fill}\" stroke=\"#111\" stroke-width=\"2\" stroke-linejoin=\"round\"/></svg>`)}`\n\nexport function BrandCursor({ src, hotspot = [3, 2] }: { src?: string; hotspot?: [number, number] }) {\n  useEffect(() => {\n    if (!matchMedia('(pointer: fine)').matches) return\n    const accent = getComputedStyle(document.documentElement).getPropertyValue('--color-chapter-1').trim() || getComputedStyle(document.documentElement).getPropertyValue('--color-accent').trim() || '#0038FF'\n    const url = src ?? drawn(accent)\n    const el = document.createElement('style')\n    el.textContent = `html{cursor:url(\"${url}\") ${hotspot[0]} ${hotspot[1]}, auto}a,button,[role=button],label,summary{cursor:pointer}`\n    document.head.appendChild(el)\n    return () => el.remove()\n  }, [src, hotspot])\n  return null\n}\n",
  "cookie-note": "'use client'\n// OpusKit piece — a cookie notice that looks like part of the brand: a small card with a two-part header (a place and\n// a label), plain words and one clear button. Remembers the answer. Original OpusKit code (MIT).\nimport { AnimatePresence, motion } from 'motion/react'\nimport { useEffect, useState } from 'react'\n\nexport function CookieNote({ text, place = 'Zone 1', label = 'Note', accept = 'Accept', decline = 'Only necessary', storageKey = 'cookie-choice' }: { text: string; place?: string; label?: string; accept?: string; decline?: string; storageKey?: string }) {\n  const [open, setOpen] = useState(false)\n  useEffect(() => { try { if (!localStorage.getItem(storageKey)) setOpen(true) } catch { setOpen(true) } }, [storageKey])\n  const answer = (v: string) => { try { localStorage.setItem(storageKey, v) } catch { /* private mode */ } setOpen(false) }\n  return (\n    <AnimatePresence>\n      {open && (\n        <motion.div role=\"dialog\" aria-live=\"polite\" aria-label={label} className=\"fixed bottom-4 right-4 z-50 w-[min(24rem,calc(100vw-2rem))] border border-(--color-border) bg-(--color-surface) text-(--color-text) shadow-(--shadow-card)\"\n          initial={{ y: 24, opacity: 0, rotate: 2 }} animate={{ y: 0, opacity: 1, rotate: 0 }} exit={{ y: 24, opacity: 0 }} transition={{ type: 'spring', stiffness: 260, damping: 22 }}>\n          <div className=\"type-utility flex items-center gap-3 border-b border-(--color-border) px-4 py-2.5 [font-family:var(--font-body)] [font-size:0.875rem]\">\n            <span>⌖ {place}</span><span aria-hidden className=\"h-4 w-px bg-(--color-border)\" /><span>✓ {label}</span>\n            <button type=\"button\" aria-label=\"Close\" onClick={() => answer('dismissed')} className=\"ml-auto px-1 text-lg leading-none\">×</button>\n          </div>\n          <p className=\"type-body px-4 pt-4 [font-size:0.9rem]\">{text}</p>\n          <div className=\"flex flex-wrap gap-2 px-4 pb-4 pt-4\">\n            <button type=\"button\" onClick={() => answer('all')} className=\"type-body bg-(--color-chapter-1,var(--color-accent)) px-4 py-2 text-(--color-background) [font-size:0.9rem]\">{accept} →</button>\n            <button type=\"button\" onClick={() => answer('necessary')} className=\"type-body px-3 py-2 underline underline-offset-4 [font-size:0.9rem]\">{decline}</button>\n          </div>\n        </motion.div>\n      )}\n    </AnimatePresence>\n  )\n}\n",
  "curtain-transition": "'use client'\n// OpusKit piece — page transition: clicking an internal link raises a plain panel over the page carrying the link's\n// words, then the panel keeps rising off the top to reveal the next page (under 700 ms in all). Mount once in the root\n// layout. Respects reduced motion (plain navigation). Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { usePathname } from 'next/navigation'\nimport { useEffect, useState } from 'react'\n\nconst EASE = [0.76, 0, 0.24, 1] as const\n\nexport function PageCurtain({ color = 'var(--color-text)' }: { color?: string }) {\n  const path = usePathname()\n  const reduce = useReducedMotion()\n  const [phase, setPhase] = useState<'idle' | 'cover' | 'reveal'>('idle')\n  const [name, setName] = useState('')\n  useEffect(() => {\n    if (reduce) return\n    let replaying = false\n    const onClick = (e: MouseEvent) => {\n      if (replaying) return\n      const a = (e.target as HTMLElement).closest('a')\n      if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || a.target === '_blank' || a.hasAttribute('download')) return\n      const url = new URL(a.href, location.href)\n      if (url.origin !== location.origin || (url.pathname === location.pathname && url.hash)) return\n      e.preventDefault()\n      e.stopPropagation() // capture phase: hold the click before next/link sees it, then replay it once the page is covered\n      // A label that is drawn twice (TextRoll) carries its words in aria-label — prefer that over the doubled text.\n      const text = (a.getAttribute('aria-label') ?? a.querySelector('[aria-label]')?.getAttribute('aria-label') ?? a.textContent ?? '').trim().replace(/\\s+/g, ' ')\n      setName(text.length > 40 ? `${text.slice(0, 39)}…` : text)\n      setPhase('cover')\n      setTimeout(() => { replaying = true; a.click(); replaying = false }, 300) // next/link navigates (basePath, prefetch, its own handlers)\n      // Same pathname (only the query changed) never fires the reveal below — lift the curtain anyway.\n      setTimeout(() => setPhase((p) => (p === 'cover' ? 'reveal' : p)), 1200)\n    }\n    document.addEventListener('click', onClick, true)\n    return () => document.removeEventListener('click', onClick, true)\n  }, [reduce])\n  // The new page arrived: lift the curtain (state adjusted while rendering, not in an effect).\n  const [seenPath, setSeenPath] = useState(path)\n  if (seenPath !== path) { setSeenPath(path); if (phase === 'cover') setPhase('reveal') }\n  if (phase === 'idle') return null\n  return (\n    <motion.div aria-hidden className=\"pointer-events-none fixed inset-0 z-[100] grid place-items-center px-6\" style={{ background: color }}\n      initial={{ y: '100%' }} animate={{ y: phase === 'cover' ? '0%' : '-100%' }}\n      transition={{ duration: phase === 'cover' ? 0.3 : 0.35, ease: EASE }}\n      onAnimationComplete={() => { if (phase === 'reveal') setPhase('idle') }}>\n      <span className=\"text-center font-(family-name:--font-display) text-[clamp(2.5rem,8vw,7rem)] leading-none tracking-tight text-(--color-background)\">{name}</span>\n    </motion.div>\n  )\n}\n",
  "preloader": "'use client'\n// OpusKit piece — a designed preloader for the first page view of a visit: the brand name and a 0→100 count that\n// follows real loading (fonts and the page's own load), then the panel lifts away. Never longer than `maxMs`, never a\n// flash (≥ 600 ms). Reduced motion: no count — the name shows for the real load time, then fades. Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useEffect, useLayoutEffect, useRef, useState } from 'react'\n\nconst KEY = 'opuskit-preloaded'\n\nexport function Preloader({ brand, maxMs = 2500 }: { brand: string; maxMs?: number }) {\n  const reduce = useReducedMotion()\n  // Rendered by default so the first paint is the panel, not the page; hidden at once when already seen this visit.\n  // ponytail: a full reload later in the same visit shows the panel until hydration; an inline head script would fix that.\n  const [phase, setPhase] = useState<'on' | 'leaving' | 'off'>('on')\n  const count = useRef<HTMLSpanElement>(null)\n  const shown = phase !== 'off'\n\n  useLayoutEffect(() => {\n    // eslint-disable-next-line react-hooks/set-state-in-effect -- on purpose, before paint: a repeat visit must never see the panel\n    try { if (sessionStorage.getItem(KEY)) { setPhase('off'); return } } catch { /* storage blocked: once per mount */ }\n    const still = matchMedia('(prefers-reduced-motion: reduce)').matches\n    let fonts = 0, loaded = document.readyState === 'complete' ? 1 : 0, value = 0, raf = 0\n    const start = performance.now()\n    document.fonts?.ready.then(() => { fonts = 1 })\n    const onLoad = () => { loaded = 1 }\n    window.addEventListener('load', onLoad, { once: true })\n    const tick = (now: number) => {\n      const t = now - start\n      const target = fonts + loaded === 2 || t >= maxMs ? 100 : (fonts + loaded) * 50\n      value += (target - value) * 0.12\n      if (target === 100 && 100 - value < 0.5) value = 100\n      if (count.current) count.current.textContent = String(Math.round(value))\n      if (value === 100 && (still || t >= 600)) return setPhase('leaving')\n      raf = requestAnimationFrame(tick)\n    }\n    raf = requestAnimationFrame(tick)\n    return () => { cancelAnimationFrame(raf); window.removeEventListener('load', onLoad) }\n  }, [maxMs])\n\n  useEffect(() => {\n    if (!shown) return\n    const root = document.documentElement, prev = root.style.overflow\n    root.style.overflow = 'hidden'\n    return () => { root.style.overflow = prev }\n  }, [shown])\n\n  if (!shown) return null\n  return (\n    <motion.div role=\"status\" aria-label={`Loading ${brand}`} className=\"fixed inset-0 z-[110] flex flex-col justify-between bg-(--color-background) p-6 text-(--color-text) sm:p-10\"\n      initial={false} animate={phase === 'leaving' ? (reduce ? { opacity: 0 } : { y: '-100%' }) : {}}\n      transition={reduce ? { duration: 0.2 } : { duration: 0.6, ease: [0.76, 0, 0.24, 1] }}\n      onAnimationComplete={() => {\n        if (phase !== 'leaving') return\n        try { sessionStorage.setItem(KEY, '1') } catch { /* private mode */ }\n        setPhase('off')\n      }}>\n      <span className=\"font-(family-name:--font-display) text-[clamp(2.5rem,9vw,8rem)] leading-none tracking-tight\">{brand}</span>\n      <span ref={count} aria-hidden className=\"self-end motion-reduce:invisible font-(family-name:--font-utility) text-[clamp(1.5rem,4vw,3rem)] tabular-nums\">0</span>\n    </motion.div>\n  )\n}\n",
  "smooth-scroll": "'use client'\n// OpusKit piece — smooth scroll (Lenis, MIT): the wheel and trackpad glide instead of stepping, so scroll effects move\n// as one. Mouse/trackpad only — touch keeps the phone's own scroll. Off under reduced motion. In-page #anchors glide\n// too. Mount once in the root layout. Original OpusKit code (MIT).\nimport Lenis from 'lenis'\nimport { useEffect } from 'react'\n\nconst CSS = 'html.lenis,html.lenis body{height:auto}.lenis.lenis-smooth{scroll-behavior:auto!important}.lenis:not(.lenis-autoToggle).lenis-stopped{overflow:clip}.lenis [data-lenis-prevent],.lenis [data-lenis-prevent-wheel],.lenis [data-lenis-prevent-touch],.lenis [data-lenis-prevent-vertical],.lenis [data-lenis-prevent-horizontal]{overscroll-behavior:contain}.lenis.lenis-smooth iframe{pointer-events:none}.lenis.lenis-autoToggle{transition-property:overflow;transition-duration:1ms;transition-behavior:allow-discrete}'\n\nexport function SmoothScroll({ lerp = 0.1 }: { lerp?: number }) {\n  useEffect(() => {\n    const fine = matchMedia('(pointer: fine)'), still = matchMedia('(prefers-reduced-motion: reduce)')\n    let lenis: Lenis | undefined\n    const sync = () => {\n      const want = fine.matches && !still.matches\n      if (want && !lenis) lenis = new Lenis({ lerp, anchors: true, autoRaf: true }) // autoRaf: Lenis runs its own requestAnimationFrame loop\n      else if (!want && lenis) { lenis.destroy(); lenis = undefined }\n    }\n    sync()\n    fine.addEventListener('change', sync)\n    still.addEventListener('change', sync)\n    return () => { fine.removeEventListener('change', sync); still.removeEventListener('change', sync); lenis?.destroy() }\n  }, [lerp])\n  return <style>{CSS}</style>\n}\n",
  "ambient-sound": "'use client'\n// OpusKit piece — a quiet sound loop with an always-visible switch (bottom-left by default; `placement` moves it, e.g.\n// into the menu bar, so it never sits on top of text). Off by default and never autoplays:\n// a remembered \"on\" waits for the visitor's first tap or key. Fades in and out, pauses while the tab is hidden.\n// Reduced motion: the little bars stay still. Original OpusKit code (MIT).\nimport { useEffect, useRef, useState } from 'react'\n\nconst KEY = 'opuskit-sound'\nconst CSS = '@keyframes opuskit-bars{from{transform:scaleY(.3)}to{transform:scaleY(1)}}@media (prefers-reduced-motion:no-preference){.opuskit-bars[data-playing]>span{animation:opuskit-bars .9s ease-in-out infinite alternate}}'\n\nexport function AmbientSound({ src, label = 'Sound', volume = 0.4, placement = 'fixed bottom-4 left-4 z-[90]' }: { src: string; label?: string; volume?: number; /** Position classes for the switch; pass '' to place it in the flow (e.g. inside the menu bar). */ placement?: string }) {\n  const [on, setOn] = useState(false)\n  const [playing, setPlaying] = useState(false)\n  const audio = useRef<HTMLAudioElement | null>(null)\n  const fade = useRef(0)\n  const wanted = useRef(false) // the visitor's choice, for listeners\n  const started = useRef(false) // the page has had a user gesture, so play() is allowed\n\n  const ramp = (to: number, after?: () => void) => {\n    const a = audio.current\n    if (!a) return after?.()\n    cancelAnimationFrame(fade.current)\n    const from = a.volume, start = performance.now()\n    const step = (now: number) => {\n      const k = Math.min(1, Math.max(0, (now - start) / 800)) // the first frame can land just before start\n      a.volume = Math.min(1, Math.max(0, from + (to - from) * k))\n      if (k < 1) fade.current = requestAnimationFrame(step)\n      else after?.()\n    }\n    fade.current = requestAnimationFrame(step)\n  }\n  const play = () => {\n    started.current = true\n    if (!src) return\n    const a = (audio.current ??= Object.assign(new Audio(src), { loop: true, volume: 0 }))\n    a.play().then(() => { setPlaying(true); ramp(volume) }).catch(() => { /* blocked or missing file: stay quiet */ })\n  }\n  const stop = () => { setPlaying(false); ramp(0, () => audio.current?.pause()) }\n\n  useEffect(() => {\n    let saved = false\n    try { saved = localStorage.getItem(KEY) === 'on' } catch { /* private mode */ }\n    if (!saved) return\n    // A saved choice can only be read after hydration (the server has no localStorage), so it is restored here.\n    // eslint-disable-next-line react-hooks/set-state-in-effect\n    setOn(true)\n    wanted.current = true\n    // Browsers block sound until a gesture; a press on the switch itself is handled by its own click.\n    const first = (e: Event) => {\n      if ((e.target as HTMLElement | null)?.closest?.('[data-opuskit-sound]')) return\n      remove()\n      if (wanted.current && !started.current) play()\n    }\n    const remove = () => { removeEventListener('pointerdown', first); removeEventListener('keydown', first) }\n    addEventListener('pointerdown', first)\n    addEventListener('keydown', first)\n    return remove\n  }, [])\n\n  useEffect(() => {\n    const onVisibility = () => {\n      const a = audio.current\n      if (!a || !wanted.current) return\n      if (document.hidden) a.pause()\n      else a.play().catch(() => {})\n    }\n    document.addEventListener('visibilitychange', onVisibility)\n    return () => { document.removeEventListener('visibilitychange', onVisibility); cancelAnimationFrame(fade.current); audio.current?.pause() }\n  }, [])\n\n  const toggle = () => {\n    const next = !on\n    setOn(next)\n    wanted.current = next\n    try { localStorage.setItem(KEY, next ? 'on' : 'off') } catch { /* private mode */ }\n    if (next) play()\n    else stop()\n  }\n\n  return (\n    <>\n      <button type=\"button\" data-opuskit-sound aria-pressed={on} aria-label={`${label}: ${on ? 'on' : 'off'}`} onClick={toggle}\n        className={`${placement} inline-flex min-h-11 min-w-11 items-center gap-2.5 rounded-(--radius-button,999px) border border-(--color-border) bg-(--color-background) px-4 font-(family-name:--font-utility) text-sm text-(--color-text)`}>\n        <span aria-hidden className=\"opuskit-bars flex h-3 items-end gap-0.5\" data-playing={playing || undefined}>\n          {[0, 1, 2, 3].map((i) => <span key={i} className=\"h-full w-0.5 origin-bottom bg-current\" style={{ transform: 'scaleY(.3)', animationDelay: `${i * -0.22}s` }} />)}\n        </span>\n        {label} {on ? 'on' : 'off'}\n      </button>\n      <style>{CSS}</style>\n    </>\n  )\n}\n",
  "entry-gate": "'use client'\n// OpusKit piece — a playful way in: the first page view of a visit opens under a sheet the visitor plays away. `drag`:\n// pull the sheet up or off to the side (or press the button); `hold`: press and hold the button until it fills (1.2 s).\n// Skip (focused first) and Esc open the site at once. The page sits in the DOM underneath from the start and is inert\n// until the sheet goes. Reduced motion: one \"Enter\" button, no wipe. Original OpusKit code (MIT).\nimport { animate, motion, useMotionValue, useReducedMotion, useTransform } from 'motion/react'\nimport { useCallback, useEffect, useLayoutEffect, useRef, useState, type PointerEvent, type ReactNode } from 'react'\n\nconst KEY = 'opuskit-gate'\nconst EASE = [0.65, 0, 0.35, 1] as const\n\nexport function EntryGate({ title, hint, action, mode = 'drag', enter = 'Enter', skip = 'Skip', children, className }: {\n  title: string; hint?: string; action: string; mode?: 'drag' | 'hold'; enter?: string; skip?: string\n  /** Shown faintly on the sheet, e.g. the logo or a drawing (decorative). */\n  children?: ReactNode; className?: string\n}) {\n  const reduce = useReducedMotion()\n  // Rendered by default so the first paint is the sheet, not the page; hidden at once when already opened this visit.\n  // ponytail: a full reload later in the same visit shows the sheet until hydration; an inline head script would fix that.\n  const [open, setOpen] = useState(true)\n  const sheet = useRef<HTMLDivElement>(null)\n  const first = useRef<HTMLButtonElement>(null)\n  const x = useMotionValue(0), y = useMotionValue(0), fill = useMotionValue(0)\n  const rotate = useTransform(x, [-400, 400], [-6, 6])\n  const width = useTransform(fill, (v) => `${v * 100}%`)\n\n  const done = useCallback(() => {\n    try { sessionStorage.setItem(KEY, '1') } catch { /* private mode: once per mount */ }\n    setOpen(false)\n  }, [])\n  const lift = useCallback((dir: 'up' | 'left' | 'right' = 'up') => {\n    if (reduce) return done()\n    const off = dir === 'up' ? -innerHeight * 1.15 : (dir === 'left' ? -1 : 1) * innerWidth * 1.15\n    animate(dir === 'up' ? y : x, off, { duration: 0.6, ease: EASE }).then(done)\n  }, [reduce, done, x, y])\n\n  useLayoutEffect(() => { try { if (sessionStorage.getItem(KEY)) setOpen(false) } catch { /* storage blocked */ } }, [])\n\n  // While open: the page behind is inert and does not scroll; focus starts on Skip; Esc skips.\n  useEffect(() => {\n    if (!open) return\n    let top: HTMLElement | null = sheet.current\n    while (top && top.parentElement !== document.body) top = top.parentElement\n    const behind = [...document.body.children].filter((el): el is HTMLElement => el instanceof HTMLElement && el !== top)\n    behind.forEach((el) => el.setAttribute('inert', ''))\n    const root = document.documentElement, prev = root.style.overflow\n    root.style.overflow = 'hidden'\n    first.current?.focus()\n    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') done() }\n    addEventListener('keydown', onKey)\n    return () => { behind.forEach((el) => el.removeAttribute('inert')); root.style.overflow = prev; removeEventListener('keydown', onKey) }\n  }, [open, done])\n\n  // Hold: the button fills while pressed and opens the site when full; letting go early drains it.\n  const hold = (on: boolean) => {\n    if (reduce) return\n    animate(fill, on ? 1 : 0, { duration: on ? 1.2 * (1 - fill.get()) : 0.3, ease: 'linear' }).then(() => { if (on && fill.get() >= 1) lift('up') })\n  }\n\n  if (!open) return null\n  const drag = mode === 'drag' && !reduce\n  const stop = (e: PointerEvent) => e.stopPropagation()\n  return (\n    <motion.div ref={sheet} role=\"dialog\" aria-modal=\"true\" aria-label={title}\n      className={`fixed inset-0 z-[110] select-none bg-(--color-surface)/90 text-(--color-text) backdrop-blur-[4px] ${drag ? 'cursor-grab touch-none active:cursor-grabbing' : ''} ${className ?? ''}`}\n      style={{ x, y, rotate }} drag={drag} dragElastic={0.5} dragMomentum={false}\n      onDragEnd={(_, { offset: o, velocity: v }) => {\n        if (o.y < -140 || v.y < -600) lift('up')\n        else if (Math.abs(o.x) > 180 || Math.abs(v.x) > 700) lift(o.x < 0 ? 'left' : 'right')\n        else { animate(x, 0, { type: 'spring', stiffness: 260, damping: 26 }); animate(y, 0, { type: 'spring', stiffness: 260, damping: 26 }) }\n      }}>\n      {children && <div aria-hidden className=\"pointer-events-none absolute inset-0 grid place-items-center opacity-25\">{children}</div>}\n      <button ref={first} type=\"button\" onClick={done} onPointerDown={stop}\n        className=\"absolute right-4 top-4 min-h-11 cursor-pointer px-4 font-(family-name:--font-utility) text-sm underline underline-offset-4 md:right-8 md:top-6\">\n        {skip}\n      </button>\n      <div className=\"relative flex h-full flex-col items-center justify-end gap-6 px-6 pb-[12svh] text-center\">\n        <p className=\"max-w-[16ch] font-(family-name:--font-display) text-[clamp(2.4rem,7vw,4.5rem)] leading-none\">{title}</p>\n        {hint && !reduce && <p className=\"max-w-[36ch] font-(family-name:--font-body) text-(--color-muted)\">{hint}</p>}\n        <button type=\"button\" onPointerDown={(e) => { stop(e); if (mode === 'hold') hold(true) }}\n          onPointerUp={() => mode === 'hold' && hold(false)} onPointerLeave={() => mode === 'hold' && hold(false)}\n          onClick={() => (reduce || mode === 'drag') && lift('up')}\n          onKeyDown={(e) => { if (mode === 'hold' && !reduce && (e.key === 'Enter' || e.key === ' ') && !e.repeat) { e.preventDefault(); hold(true) } }}\n          onKeyUp={(e) => { if (mode === 'hold' && (e.key === 'Enter' || e.key === ' ')) hold(false) }}\n          className=\"relative min-h-14 cursor-pointer overflow-hidden rounded-(--radius-button,0px) bg-(--color-primary) px-8 font-(family-name:--font-body) text-(--color-background)\">\n          {mode === 'hold' && !reduce && <motion.span aria-hidden className=\"absolute inset-y-0 left-0 bg-(--color-accent)\" style={{ width }} />}\n          <span className=\"relative\">{reduce ? enter : action}</span>\n        </button>\n      </div>\n    </motion.div>\n  )\n}\n",
  "chapter-colours": "'use client'\n// OpusKit piece — each item brings its own colours: as an item reaches the middle of the screen, the whole section\n// takes that item's ground and ink (set on the item as data-ground / data-ink, any CSS colour or token, AA together).\n// Above the first item the section keeps the page's own colours. 500 ms colour transition; reduced motion: instant.\n// Original OpusKit code (MIT).\nimport { useEffect, useRef, useState, type ReactNode } from 'react'\n\nexport function ChapterColours({ children, className }: { children: ReactNode; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null)\n  const [at, setAt] = useState<{ ground: string; ink: string } | null>(null)\n  useEffect(() => {\n    const items = [...(ref.current?.querySelectorAll<HTMLElement>('[data-ground]') ?? [])]\n    const io = new IntersectionObserver((es) => {\n      for (const e of es) {\n        const el = e.target as HTMLElement\n        if (e.isIntersecting) setAt({ ground: el.dataset.ground!, ink: el.dataset.ink ?? 'var(--color-text)' })\n        else if (el === items[0] && e.boundingClientRect.top > 0) setAt(null)\n      }\n    }, { rootMargin: '-45% 0px -45% 0px' })\n    items.forEach((el) => io.observe(el))\n    return () => io.disconnect()\n  }, [])\n  return (\n    <div ref={ref} style={at ? { backgroundColor: at.ground, color: at.ink } : undefined}\n      className={`transition-colors duration-500 ease-out motion-reduce:transition-none ${className ?? ''}`}>\n      {children}\n    </div>\n  )\n}\n",
  "lightbox": "'use client'\n// OpusKit piece — tap a photo to open it large: a full-screen viewer over any photo layout (grid, desk, tilted grid…).\n// Controlled: the layout sets `index` when a photo is clicked; null = closed. Arrow keys and swipe move between photos,\n// Esc or the close button returns focus to where it was; the page behind does not scroll. Reduced motion: photos swap\n// without the slide. Original OpusKit code (MIT).\nimport { motion, useReducedMotion } from 'motion/react'\nimport { useEffect, useRef } from 'react'\n\nexport type LightboxPhoto = { src: string; alt: string; caption?: string }\n\nexport function Lightbox({ photos, index, onIndex, label = 'Photos', close = 'Close', prev = 'Previous', next = 'Next' }: {\n  photos: LightboxPhoto[]; index: number | null; onIndex: (i: number | null) => void\n  label?: string; close?: string; prev?: string; next?: string\n}) {\n  const reduce = useReducedMotion()\n  const box = useRef<HTMLDivElement>(null)\n  const open = index !== null && !!photos[index]\n  const go = (by: number) => index !== null && onIndex((index + by + photos.length) % photos.length)\n\n  useEffect(() => {\n    if (!open) return\n    const back = document.activeElement as HTMLElement | null\n    const root = document.documentElement, prevOverflow = root.style.overflow\n    root.style.overflow = 'hidden'\n    box.current?.querySelector<HTMLElement>('button')?.focus()\n    return () => { root.style.overflow = prevOverflow; back?.focus() }\n  }, [open])\n\n  if (!open) return null\n  const p = photos[index]\n  const btn = 'grid size-11 cursor-pointer place-items-center rounded-(--radius-button,0px) bg-(--color-surface) text-(--color-text) font-(family-name:--font-utility) text-sm'\n  return (\n    <div ref={box} role=\"dialog\" aria-modal=\"true\" aria-label={label}\n      className=\"fixed inset-0 z-[120] flex flex-col bg-(--color-text)/90 p-3 text-(--color-background) md:p-6\"\n      onKeyDown={(e) => {\n        if (e.key === 'Escape') onIndex(null)\n        if (e.key === 'ArrowLeft') go(-1)\n        if (e.key === 'ArrowRight') go(1)\n        if (e.key === 'Tab') { // keep focus inside the viewer\n          const all = [...(box.current?.querySelectorAll<HTMLElement>('button') ?? [])]\n          const i = all.indexOf(document.activeElement as HTMLElement)\n          e.preventDefault(); all[(i + (e.shiftKey ? -1 : 1) + all.length) % all.length]?.focus()\n        }\n      }}\n      onClick={(e) => e.target === e.currentTarget && onIndex(null)}>\n      <div className=\"flex justify-between gap-2\">\n        <span aria-live=\"polite\" className=\"self-center font-(family-name:--font-utility) text-sm\">{index + 1} / {photos.length}</span>\n        <button type=\"button\" onClick={() => onIndex(null)} className={`${btn} w-auto px-4`}>{close}</button>\n      </div>\n      <figure className=\"flex min-h-0 flex-1 flex-col items-center justify-center gap-3 py-3\" onClick={(e) => e.target === e.currentTarget && onIndex(null)}>\n        <motion.img key={p.src} src={p.src} alt={p.alt} draggable={false}\n          className=\"min-h-0 max-w-full flex-1 cursor-grab touch-pan-y object-contain active:cursor-grabbing\"\n          initial={reduce ? false : { opacity: 0, x: 24 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.25, ease: 'easeOut' }}\n          drag={photos.length > 1 ? 'x' : false} dragConstraints={{ left: 0, right: 0 }} dragElastic={0.4}\n          onDragEnd={(_, { offset, velocity }) => { if (offset.x < -80 || velocity.x < -500) go(1); else if (offset.x > 80 || velocity.x > 500) go(-1) }} />\n        {p.caption && <figcaption className=\"max-w-[60ch] text-center font-(family-name:--font-utility) text-sm\">{p.caption}</figcaption>}\n      </figure>\n      {photos.length > 1 && (\n        <div className=\"flex justify-center gap-2\">\n          <button type=\"button\" onClick={() => go(-1)} aria-label={prev} className={btn}>‹</button>\n          <button type=\"button\" onClick={() => go(1)} aria-label={next} className={btn}>›</button>\n        </div>\n      )}\n    </div>\n  )\n}\n",
}

export const blockSource: Partial<Record<SectionId, string>> = {
  "intro": "// OpusKit section — Statement: what this is, or what you believe, in one sentence. Three designs:\n//   lead  — a small label beside the statement, a calm paragraph under it (an introduction).\n//   giant — the statement in the display face across the whole grid (a point of view).\n//   split — the statement large on the left, the paragraph set low on the right, like a magazine opener.\nexport function StatementSection({ tone, variant = 'lead', label, statement, body, attribution }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'lead' | 'giant' | 'split'; label?: string; statement: string; body?: string; attribution?: string }) {\n  const t = tone === 'ground' ? undefined : tone\n  if (variant === 'giant') return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*1.25)]\">\n      <blockquote className=\"mx-auto max-w-(--container)\">\n        {label && <p className=\"type-utility mb-8 text-(--color-muted)\">{label}</p>}\n        <p className=\"type-display text-balance [font-size:clamp(2.5rem,7vw,7rem)]\">{statement}</p>\n        {body && <p className=\"type-body mt-8 max-w-[60ch] text-(--color-muted)\">{body}</p>}\n        {attribution && <footer className=\"type-utility mt-8 text-(--color-muted)\">{attribution}</footer>}\n      </blockquote>\n    </section>\n  )\n  if (variant === 'split') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12 md:items-end\">\n        <div className=\"md:col-span-7\">\n          {label && <p className=\"type-utility mb-6 text-(--color-muted)\">{label}</p>}\n          <p className=\"type-heading text-balance [font-size:clamp(2rem,4.6vw,4.25rem)] leading-[1.02]\">{statement}</p>\n        </div>\n        <div className=\"md:col-span-4 md:col-start-9\">\n          {body && <p className=\"type-body text-(--color-muted)\">{body}</p>}\n          {attribution && <p className=\"type-utility mt-6 text-(--color-muted)\">{attribution}</p>}\n        </div>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-6 md:grid-cols-12\">\n        {label && <p className=\"type-utility text-(--color-muted) md:col-span-3\">{label}</p>}\n        <div className={label ? 'md:col-span-8' : 'md:col-span-9'}>\n          <p className=\"type-heading text-balance [font-size:clamp(1.75rem,3.6vw,3.25rem)]\">{statement}</p>\n          {body && <p className=\"type-body mt-6 max-w-[60ch] text-(--color-muted)\">{body}</p>}\n          {attribution && <p className=\"type-utility mt-6 text-(--color-muted)\">{attribution}</p>}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "manifesto": "// OpusKit section — Statement: what this is, or what you believe, in one sentence. Three designs:\n//   lead  — a small label beside the statement, a calm paragraph under it (an introduction).\n//   giant — the statement in the display face across the whole grid (a point of view).\n//   split — the statement large on the left, the paragraph set low on the right, like a magazine opener.\nexport function StatementSection({ tone, variant = 'lead', label, statement, body, attribution }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'lead' | 'giant' | 'split'; label?: string; statement: string; body?: string; attribution?: string }) {\n  const t = tone === 'ground' ? undefined : tone\n  if (variant === 'giant') return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*1.25)]\">\n      <blockquote className=\"mx-auto max-w-(--container)\">\n        {label && <p className=\"type-utility mb-8 text-(--color-muted)\">{label}</p>}\n        <p className=\"type-display text-balance [font-size:clamp(2.5rem,7vw,7rem)]\">{statement}</p>\n        {body && <p className=\"type-body mt-8 max-w-[60ch] text-(--color-muted)\">{body}</p>}\n        {attribution && <footer className=\"type-utility mt-8 text-(--color-muted)\">{attribution}</footer>}\n      </blockquote>\n    </section>\n  )\n  if (variant === 'split') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12 md:items-end\">\n        <div className=\"md:col-span-7\">\n          {label && <p className=\"type-utility mb-6 text-(--color-muted)\">{label}</p>}\n          <p className=\"type-heading text-balance [font-size:clamp(2rem,4.6vw,4.25rem)] leading-[1.02]\">{statement}</p>\n        </div>\n        <div className=\"md:col-span-4 md:col-start-9\">\n          {body && <p className=\"type-body text-(--color-muted)\">{body}</p>}\n          {attribution && <p className=\"type-utility mt-6 text-(--color-muted)\">{attribution}</p>}\n        </div>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-6 md:grid-cols-12\">\n        {label && <p className=\"type-utility text-(--color-muted) md:col-span-3\">{label}</p>}\n        <div className={label ? 'md:col-span-8' : 'md:col-span-9'}>\n          <p className=\"type-heading text-balance [font-size:clamp(1.75rem,3.6vw,3.25rem)]\">{statement}</p>\n          {body && <p className=\"type-body mt-6 max-w-[60ch] text-(--color-muted)\">{body}</p>}\n          {attribution && <p className=\"type-utility mt-6 text-(--color-muted)\">{attribution}</p>}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "featured-work": "import type { ElementType } from 'react'\n// OpusKit section — Featured Work: 3–6 best projects. Four designs:\n//   staggered — large and small alternating, so the rhythm never repeats.\n//   index     — a typographic list: each project a big title on a rule, its year/kind on the right, a small picture\n//               beside it (many projects, the names matter).\n//   grid      — an even two-column grid, every picture the same shape (a calm catalogue).\n//   stack     — one project per row at full width, the picture first (few projects, big pictures).\nexport type Project = { title: string; meta: string; image: string; alt: string; href: string }\n\nexport function FeaturedWorkSection({ tone, variant = 'staggered', link: L = 'a', title, projects }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'staggered' | 'index' | 'grid' | 'stack'; link?: ElementType; title: string; projects: Project[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  const caption = (p: Project) => (\n    <div className=\"mt-4 flex items-baseline justify-between gap-4\">\n      <h3 className=\"type-heading [font-size:clamp(1.25rem,1.8vw,1.6rem)] group-hover:underline group-hover:underline-offset-4\">{p.title}</h3>\n      <p className=\"type-utility shrink-0 text-(--color-muted)\">{p.meta}</p>\n    </div>\n  )\n  const img = (p: Project, ratio: string) => <div className=\"overflow-hidden rounded-(--radius-media)\"><img src={p.image} alt={p.alt} loading=\"lazy\" className={`w-full object-cover transition-transform duration-500 group-hover:scale-[1.03] ${ratio}`} /></div>\n\n  if (variant === 'index') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        <ul className=\"mt-8 border-t border-(--color-border)\">\n          {projects.map((p) => (\n            <li key={p.href} className=\"border-b border-(--color-border)\">\n              <L href={p.href} className=\"group grid grid-cols-[1fr_auto] items-center gap-6 py-5 md:grid-cols-[1fr_10rem_7rem] md:py-6\">\n                <h3 className=\"type-display [font-size:clamp(1.8rem,4.4vw,4rem)] leading-none transition-transform duration-300 group-hover:translate-x-2\">{p.title}</h3>\n                <p className=\"type-utility text-(--color-muted) md:order-3 md:text-right\">{p.meta}</p>\n                <img src={p.image} alt={p.alt} loading=\"lazy\" className=\"hidden aspect-(--ratio-card) w-full rounded-(--radius-media) object-cover opacity-80 transition-opacity group-hover:opacity-100 md:block\" />\n              </L>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n  if (variant === 'grid') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-12 grid gap-x-6 gap-y-14 md:grid-cols-2\">\n          {projects.map((p) => <li key={p.href}><L href={p.href} className=\"group block\">{img(p, 'aspect-(--ratio-card)')}{caption(p)}</L></li>)}\n        </ul>\n      </div>\n    </section>\n  )\n  if (variant === 'stack') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-12 space-y-20 md:space-y-28\">\n          {projects.map((p) => <li key={p.href}><L href={p.href} className=\"group block\">{img(p, 'aspect-(--ratio-media)')}{caption(p)}</L></li>)}\n        </ul>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-12 grid gap-x-6 gap-y-16 md:grid-cols-12\">\n          {projects.map((p, i) => (\n            <li key={p.href} className={i % 3 === 0 ? 'md:col-span-7' : i % 3 === 1 ? 'md:col-span-5 md:mt-24' : 'md:col-span-6 md:col-start-4'}>\n              <L href={p.href} className=\"group block\">{img(p, i % 3 === 1 ? 'aspect-(--ratio-card)' : 'aspect-(--ratio-media)')}{caption(p)}</L>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "case-study": "import type { ElementType } from 'react'\n// OpusKit section — Case Study preview: one project in depth — media, facts, then problem / approach / result.\n// `media`: full (a wide image first, the story under it), side (a tall image held beside the story) or over (the\n// title and facts on the image, the story after).\ntype P = { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; media?: 'side' | 'full' | 'over'; link?: ElementType; title: string; image: string; alt: string; facts: { label: string; value: string }[]; paragraphs: string[]; href?: string }\nexport function CaseStudySection({ tone, media = 'full', link: L = 'a', title, image, alt, facts, paragraphs, href }: P) {\n  const factList = (cls: string) => <dl className={cls}>{facts.map((f) => <div key={f.label}><dt className=\"type-utility text-(--color-muted)\">{f.label}</dt><dd className=\"type-body mt-1\">{f.value}</dd></div>)}</dl>\n  const story = <div className=\"type-body space-y-5\">{paragraphs.map((p, i) => <p key={i} className=\"max-w-[62ch]\">{p}</p>)}{href && <L href={href} className=\"inline-block underline underline-offset-4\">Read the full case study</L>}</div>\n  if (media === 'over') return (\n    <section data-tone={tone === 'ground' ? undefined : tone}>\n      <div data-tone=\"inverse\" className=\"relative isolate flex min-h-[85svh] items-end px-(--gutter) py-[calc(var(--section-y)*0.6)]\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"absolute inset-0 -z-10 h-full w-full object-cover opacity-55\" />\n        <div className=\"mx-auto grid w-full max-w-(--container) gap-8 md:grid-cols-12 md:items-end\">\n          <h2 className=\"type-display text-balance [font-size:clamp(2.4rem,6vw,5.5rem)] md:col-span-7\">{title}</h2>\n          {factList('grid grid-cols-2 gap-4 md:col-span-4 md:col-start-9')}\n        </div>\n      </div>\n      <div className=\"mx-auto max-w-(--container) px-(--gutter) py-(--section-y)\"><div className=\"md:ml-[33%]\">{story}</div></div>\n    </section>\n  )\n  if (media === 'side') return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-(--ratio-card) w-full rounded-(--radius-media) object-cover md:sticky md:top-24 md:col-span-5 md:self-start\" />\n        <div className=\"md:col-span-6 md:col-start-7\">\n          <h2 className=\"type-heading\">{title}</h2>\n          {factList('mt-6 grid grid-cols-2 gap-4 border-y border-(--color-border) py-6')}\n          <div className=\"mt-8\">{story}</div>\n        </div>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-[21/9] w-full rounded-(--radius-media) object-cover\" />\n        <div className=\"mt-10 grid gap-10 md:grid-cols-12\">\n          <div className=\"md:col-span-4\"><h2 className=\"type-heading\">{title}</h2>{factList('mt-6 grid grid-cols-2 gap-4 md:grid-cols-1')}</div>\n          <div className=\"md:col-span-7 md:col-start-6\">{story}</div>\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "services": "import type { ElementType } from 'react'\n// OpusKit section — Services: what you offer. Three designs:\n//   rows  — one row each, with rules between; the hovered row lifts (a clear list beside the title).\n//   big   — each service name set large in the display face, its line small beneath (few services, said loudly).\n//   cards — a card per service on the surface, in a grid (many services, scanned at a glance).\ntype Service = { name: string; line: string; href?: string }\n\nexport function ServicesSection({ tone, variant = 'rows', link: L = 'a', title, items }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'rows' | 'big' | 'cards'; link?: ElementType; title: string; items: Service[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  const name = (s: Service) => (s.href ? <L href={s.href} className=\"hover:underline hover:underline-offset-4\">{s.name}</L> : s.name)\n  if (variant === 'big') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        <ul className=\"mt-10 space-y-10 md:space-y-14\">\n          {items.map((s) => (\n            <li key={s.name} className=\"grid gap-3 md:grid-cols-12 md:items-baseline\">\n              <h3 className=\"type-display [font-size:clamp(2.2rem,6vw,5.5rem)] leading-[0.95] md:col-span-8\">{name(s)}</h3>\n              <p className=\"type-body text-(--color-muted) md:col-span-4\">{s.line}</p>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n  if (variant === 'cards') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          {items.map((s) => (\n            <li key={s.name} className=\"flex flex-col justify-between gap-10 rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) p-7 shadow-(--shadow-card)\">\n              <h3 className=\"type-heading [font-size:clamp(1.3rem,2vw,1.7rem)]\">{name(s)}</h3>\n              <p className=\"type-body text-(--color-muted)\">{s.line}</p>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <h2 className=\"type-heading md:col-span-4\">{title}</h2>\n        <ul className=\"border-t border-(--color-border) md:col-span-8\">\n          {items.map((s) => (\n            <li key={s.name} className=\"group grid gap-2 border-b border-(--color-border) py-6 transition-colors hover:bg-(--color-surface) md:grid-cols-2 md:px-4\">\n              <h3 className=\"type-heading [font-size:clamp(1.25rem,2vw,1.75rem)]\">{name(s)}</h3>\n              <p className=\"type-body text-(--color-muted)\">{s.line}</p>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "process": "// OpusKit section — Steps: how it goes, 3–5 real steps (numbered, because it is a real sequence). Three designs:\n//   columns — a big number over each step, side by side, a rule above (a studio's process).\n//   cards   — a card per step with its own picture (a product's how-it-works).\n//   rail    — the title holds still on the left while the steps run down a line on the right (a longer journey).\nexport type Step = { name: string; text: string; duration?: string; image?: string; alt?: string }\n\nexport function StepsSection({ tone, variant = 'columns', title, steps }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'columns' | 'cards' | 'rail'; title: string; steps: Step[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  if (variant === 'rail') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <h2 className=\"type-heading self-start text-balance md:sticky md:top-24 md:col-span-5\">{title}</h2>\n        <ol className=\"border-l border-(--color-border) md:col-span-6 md:col-start-7\">\n          {steps.map((s, i) => (\n            <li key={s.name} className=\"relative pb-12 pl-8 last:pb-0\">\n              <span aria-hidden className=\"absolute -left-[5px] top-2 size-[9px] rounded-full bg-(--color-accent)\" />\n              <p className=\"type-utility text-(--color-muted)\">{i + 1}{s.duration ? ` — ${s.duration}` : ''}</p>\n              <h3 className=\"type-heading mt-2 [font-size:clamp(1.3rem,2.2vw,1.9rem)]\">{s.name}</h3>\n              <p className=\"type-body mt-3 max-w-[48ch] text-(--color-muted)\">{s.text}</p>\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n  if (variant === 'cards') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading max-w-[24ch]\">{title}</h2>\n        <ol className=\"mt-12 grid gap-6 md:grid-cols-[repeat(auto-fit,minmax(15rem,1fr))]\">\n          {steps.map((s, i) => (\n            <li key={s.name} className=\"rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) p-5 shadow-(--shadow-card)\">\n              {s.image && <img src={s.image} alt={s.alt ?? ''} loading=\"lazy\" className=\"mb-5 aspect-[4/3] w-full rounded-(--radius-media) object-cover\" />}\n              <p className=\"type-utility text-(--color-accent)\">Step {i + 1}</p>\n              <h3 className=\"type-heading mt-2 [font-size:clamp(1.15rem,1.6vw,1.4rem)]\">{s.name}</h3>\n              <p className=\"type-body mt-2 text-(--color-muted)\">{s.text}</p>\n              {s.duration && <p className=\"type-utility mt-3\">{s.duration}</p>}\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ol className=\"mt-12 grid gap-10 md:grid-cols-[repeat(auto-fit,minmax(14rem,1fr))]\">\n          {steps.map((s, i) => (\n            <li key={s.name} className=\"border-t border-(--color-text) pt-5\">\n              <p className=\"type-display [font-size:clamp(2.5rem,4vw,3.5rem)]\">{i + 1}</p>\n              <h3 className=\"type-heading mt-4 [font-size:clamp(1.15rem,1.6vw,1.4rem)]\">{s.name}</h3>\n              <p className=\"type-body mt-2 text-(--color-muted)\">{s.text}</p>\n              {s.duration && <p className=\"type-utility mt-3\">{s.duration}</p>}\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n}\n",
  "how-it-works": "// OpusKit section — Steps: how it goes, 3–5 real steps (numbered, because it is a real sequence). Three designs:\n//   columns — a big number over each step, side by side, a rule above (a studio's process).\n//   cards   — a card per step with its own picture (a product's how-it-works).\n//   rail    — the title holds still on the left while the steps run down a line on the right (a longer journey).\nexport type Step = { name: string; text: string; duration?: string; image?: string; alt?: string }\n\nexport function StepsSection({ tone, variant = 'columns', title, steps }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'columns' | 'cards' | 'rail'; title: string; steps: Step[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  if (variant === 'rail') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <h2 className=\"type-heading self-start text-balance md:sticky md:top-24 md:col-span-5\">{title}</h2>\n        <ol className=\"border-l border-(--color-border) md:col-span-6 md:col-start-7\">\n          {steps.map((s, i) => (\n            <li key={s.name} className=\"relative pb-12 pl-8 last:pb-0\">\n              <span aria-hidden className=\"absolute -left-[5px] top-2 size-[9px] rounded-full bg-(--color-accent)\" />\n              <p className=\"type-utility text-(--color-muted)\">{i + 1}{s.duration ? ` — ${s.duration}` : ''}</p>\n              <h3 className=\"type-heading mt-2 [font-size:clamp(1.3rem,2.2vw,1.9rem)]\">{s.name}</h3>\n              <p className=\"type-body mt-3 max-w-[48ch] text-(--color-muted)\">{s.text}</p>\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n  if (variant === 'cards') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading max-w-[24ch]\">{title}</h2>\n        <ol className=\"mt-12 grid gap-6 md:grid-cols-[repeat(auto-fit,minmax(15rem,1fr))]\">\n          {steps.map((s, i) => (\n            <li key={s.name} className=\"rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) p-5 shadow-(--shadow-card)\">\n              {s.image && <img src={s.image} alt={s.alt ?? ''} loading=\"lazy\" className=\"mb-5 aspect-[4/3] w-full rounded-(--radius-media) object-cover\" />}\n              <p className=\"type-utility text-(--color-accent)\">Step {i + 1}</p>\n              <h3 className=\"type-heading mt-2 [font-size:clamp(1.15rem,1.6vw,1.4rem)]\">{s.name}</h3>\n              <p className=\"type-body mt-2 text-(--color-muted)\">{s.text}</p>\n              {s.duration && <p className=\"type-utility mt-3\">{s.duration}</p>}\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ol className=\"mt-12 grid gap-10 md:grid-cols-[repeat(auto-fit,minmax(14rem,1fr))]\">\n          {steps.map((s, i) => (\n            <li key={s.name} className=\"border-t border-(--color-text) pt-5\">\n              <p className=\"type-display [font-size:clamp(2.5rem,4vw,3.5rem)]\">{i + 1}</p>\n              <h3 className=\"type-heading mt-4 [font-size:clamp(1.15rem,1.6vw,1.4rem)]\">{s.name}</h3>\n              <p className=\"type-body mt-2 text-(--color-muted)\">{s.text}</p>\n              {s.duration && <p className=\"type-utility mt-3\">{s.duration}</p>}\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n}\n",
  "about": "// OpusKit section — About: a real face and a point of view. Portrait, statement, short bio. `media`: side (portrait\n// beside the words), full (a wide photo above, the words in two columns under it) or over (the words on the photo).\ntype P = { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; media?: 'side' | 'full' | 'over'; title: string; image: string; alt: string; statement: string; bio: string }\nexport function AboutSection({ tone, media = 'side', title, image, alt, statement, bio }: P) {\n  const words = <><h2 className=\"type-utility text-(--color-muted)\">{title}</h2><p className=\"type-heading mt-4 text-balance [font-size:clamp(1.5rem,3vw,2.6rem)]\">{statement}</p></>\n  if (media === 'over') return (\n    <section data-tone=\"inverse\" className=\"relative isolate overflow-hidden px-(--gutter) py-[calc(var(--section-y)*1.4)]\">\n      <img src={image} alt={alt} loading=\"lazy\" className=\"absolute inset-0 -z-10 h-full w-full object-cover opacity-45\" />\n      <div className=\"mx-auto max-w-(--container)\"><div className=\"max-w-[40ch]\">{words}<p className=\"type-body mt-6 text-(--color-muted)\">{bio}</p></div></div>\n    </section>\n  )\n  if (media === 'full') return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-(--ratio-media) w-full rounded-(--radius-media) object-cover\" />\n        <div className=\"mt-10 grid gap-8 md:grid-cols-12\"><div className=\"md:col-span-7\">{words}</div><p className=\"type-body max-w-[58ch] text-(--color-muted) md:col-span-4 md:col-start-9 md:self-end\">{bio}</p></div>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) items-end gap-10 md:grid-cols-12\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-(--ratio-card) w-full rounded-(--radius-media) object-cover md:col-span-5\" />\n        <div className=\"md:col-span-6 md:col-start-7\">{words}<p className=\"type-body mt-6 max-w-[58ch] text-(--color-muted)\">{bio}</p></div>\n      </div>\n    </section>\n  )\n}\n",
  "gallery": "// OpusKit section — Gallery: a mixed-size grid that keeps each photo's own shape; sparse captions.\nexport type GalleryPhoto = { src: string; alt: string; caption?: string }\n\nexport function GallerySection({ tone, title, photos }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title?: string; photos: GalleryPhoto[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        {title && <h2 className=\"type-heading mb-10\">{title}</h2>}\n        <ul className=\"columns-2 gap-4 md:columns-3 [&>li]:mb-4\">\n          {photos.map((p) => (\n            <li key={p.src} className=\"break-inside-avoid\">\n              <figure>\n                <img src={p.src} alt={p.alt} loading=\"lazy\" className=\"w-full rounded-(--radius-media) object-cover\" />\n                {p.caption && <figcaption className=\"type-utility mt-2 text-(--color-muted)\">{p.caption}</figcaption>}\n              </figure>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "editorial-story": "// OpusKit section — Editorial Story: headline, a narrow reading column and one large image with a margin caption.\n// `media`: side (the image beside the column), full (a full-width image opens the story, the column under it) or over\n// (the headline set over the image like a magazine cover, the column after).\ntype P = { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; media?: 'side' | 'full' | 'over'; title: string; image: string; alt: string; caption?: string; paragraphs: string[] }\nexport function EditorialStorySection({ tone, media = 'side', title, image, alt, caption, paragraphs }: P) {\n  const body = <div className=\"type-body space-y-5 [&>p:first-child]:[font-size:1.15em]\">{paragraphs.map((p, i) => <p key={i} className=\"max-w-[60ch]\">{p}</p>)}</div>\n  const cap = caption && <figcaption className=\"type-utility mt-3 text-(--color-muted)\">{caption}</figcaption>\n  if (media === 'over') return (\n    <section data-tone={tone === 'ground' ? undefined : tone}>\n      <figure data-tone=\"inverse\" className=\"relative isolate flex min-h-[80svh] items-end px-(--gutter) pb-[calc(var(--section-y)*0.6)]\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"absolute inset-0 -z-10 h-full w-full object-cover opacity-60\" />\n        <h2 className=\"type-display mx-auto w-full max-w-(--container) text-balance [font-size:clamp(2.6rem,7vw,6.5rem)]\">{title}</h2>\n      </figure>\n      <article className=\"mx-auto max-w-(--container) px-(--gutter) py-(--section-y)\"><div className=\"md:ml-[16.66%]\">{body}{cap && <figure>{cap}</figure>}</div></article>\n    </section>\n  )\n  if (media === 'full') return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <article className=\"mx-auto max-w-(--container)\">\n        <figure><img src={image} alt={alt} loading=\"lazy\" className=\"aspect-[21/9] w-full rounded-(--radius-media) object-cover\" />{cap}</figure>\n        <div className=\"mt-12 grid gap-10 md:grid-cols-12\">\n          <h2 className=\"type-display text-balance [font-size:clamp(2.2rem,5vw,4.5rem)] md:col-span-5\">{title}</h2>\n          <div className=\"md:col-span-6 md:col-start-7\">{body}</div>\n        </div>\n      </article>\n    </section>\n  )\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <article className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <h2 className=\"type-display text-balance [font-size:clamp(2.2rem,5vw,4.5rem)] md:col-span-10\">{title}</h2>\n        <div className=\"md:col-span-5 md:col-start-2\">{body}</div>\n        <figure className=\"md:col-span-5 md:col-start-8\"><img src={image} alt={alt} loading=\"lazy\" className=\"aspect-(--ratio-card) w-full rounded-(--radius-media) object-cover\" />{cap}</figure>\n      </article>\n    </section>\n  )\n}\n",
  "testimonials": "// OpusKit section — Testimonials: what real people said, in their words, with their name and role. No stars, no stock\n// faces, no initials standing in for a picture: a short accent rule leads each name. Three designs:\n//   lead   — one quote leads beside its label; the rest sit in a quiet row of cards.\n//   single — one quote only, large, under a big quotation mark in the accent; the person under it.\n//   wall   — every quote in columns of cards, like notes pinned to a board (many short quotes).\ntype Quote = { quote: string; name: string; role: string }\n\n\nfunction Person({ q, className = '' }: { q: Quote; size?: 'sm' | 'md'; className?: string }) {\n  return (\n    <figcaption className={`flex items-baseline gap-3 ${className}`}>\n      <span aria-hidden className=\"h-px w-6 shrink-0 -translate-y-[0.3em] bg-(--color-accent)\" />\n      <span className=\"min-w-0\">\n        <span className=\"type-body block leading-tight\">{q.name}</span>\n        <span className=\"type-utility block text-(--color-muted)\">{q.role}</span>\n      </span>\n    </figcaption>\n  )\n}\n\n/** The big quotation mark, drawn in the display face and the accent. */\nconst Mark = ({ className = '' }: { className?: string }) => (\n  <span aria-hidden className={`type-display block select-none leading-[0.6] text-(--color-accent) ${className}`}>“</span>\n)\n\nexport function TestimonialsSection({ tone, variant = 'lead', title, quotes }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'lead' | 'single' | 'wall'; title: string; quotes: Quote[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  const [lead, ...rest] = quotes\n  if (variant === 'single') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-8 border-t border-(--color-border) pt-8 md:grid-cols-12 md:gap-6\">\n        <h2 className=\"type-utility text-(--color-muted) md:col-span-3\">{title}</h2>\n        {lead && (\n          <figure className=\"md:col-span-9\">\n            <Mark className=\"[font-size:clamp(4.5rem,9vw,8rem)]\" />\n            <blockquote className=\"type-heading mt-2 max-w-[30ch] text-balance [font-size:clamp(1.6rem,3.4vw,2.9rem)] leading-[1.15]\">{lead.quote}</blockquote>\n            <Person q={lead} className=\"mt-10\" />\n          </figure>\n        )}\n      </div>\n    </section>\n  )\n  if (variant === 'wall') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-12 gap-5 [column-width:18rem]\">\n          {quotes.map((q) => (\n            <li key={q.name} className=\"mb-5 break-inside-avoid\">\n              <figure className=\"flex flex-col gap-6 rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) p-6\">\n                <div>\n                  <Mark className=\"[font-size:3.5rem]\" />\n                  <blockquote className=\"type-body mt-1\">{q.quote}</blockquote>\n                </div>\n                <Person q={q} size=\"sm\" />\n              </figure>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <div className=\"grid gap-8 md:grid-cols-12 md:gap-6\">\n          <h2 className=\"type-utility text-(--color-muted) md:col-span-3\">{title}</h2>\n          {lead && (\n            <figure className=\"md:col-span-9\">\n              <Mark className=\"[font-size:clamp(3.5rem,6vw,5.5rem)]\" />\n              <blockquote className=\"type-heading mt-1 max-w-[34ch] text-balance [font-size:clamp(1.4rem,2.8vw,2.3rem)] leading-[1.2]\">{lead.quote}</blockquote>\n              <Person q={lead} className=\"mt-8\" />\n            </figure>\n          )}\n        </div>\n        {rest.length > 0 && (\n          <ul className={`mt-14 grid gap-5 md:ml-[25%] ${rest.length === 1 ? '' : rest.length === 2 ? 'md:grid-cols-2' : 'md:grid-cols-3'}`}>\n            {rest.map((q) => (\n              <li key={q.name}>\n                <figure className=\"flex h-full flex-col justify-between gap-6 rounded-(--radius-card) border border-(--color-border) p-6\">\n                  <blockquote className=\"type-body\">“{q.quote}”</blockquote>\n                  <Person q={q} size=\"sm\" />\n                </figure>\n              </li>\n            ))}\n          </ul>\n        )}\n      </div>\n    </section>\n  )\n}\n",
  "team": "// OpusKit section — Team: the people, each with a real photo, name, role and one line in their own voice. Three designs:\n//   grid  — four small portraits to a row (a team of many).\n//   large — two big portraits to a row, the line under each (a few founders or makers).\n//   list  — a ruled list: a small portrait, then name, role and line on one row (people over pictures).\ntype Person = { name: string; role: string; line?: string; image: string; alt: string }\n\nexport function TeamSection({ tone, variant = 'grid', title, people }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'grid' | 'large' | 'list'; title: string; people: Person[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading [font-size:clamp(1.6rem,3vw,2.6rem)]\">{title}</h2>\n        {variant === 'list' ? (\n          <ul className=\"mt-10 border-t border-(--color-border)\">\n            {people.map((p) => (\n              <li key={p.name} className=\"grid grid-cols-[auto_1fr] items-center gap-x-6 gap-y-2 border-b border-(--color-border) py-5 md:grid-cols-[auto_1fr_1fr_2fr]\">\n                <img src={p.image} alt={p.alt} loading=\"lazy\" className=\"size-14 rounded-(--radius-media) object-cover max-md:row-span-2 md:size-16\" />\n                <p className=\"type-heading [font-size:clamp(1.15rem,1.8vw,1.5rem)]\">{p.name}</p>\n                <p className=\"type-utility text-(--color-muted) max-md:hidden\">{p.role}</p>\n                <p className=\"type-body text-(--color-muted)\">{p.line ?? p.role}</p>\n              </li>\n            ))}\n          </ul>\n        ) : (\n          <ul className={`mt-10 grid gap-x-5 gap-y-10 ${variant === 'large' ? 'md:grid-cols-2 md:gap-x-8' : 'grid-cols-2 md:grid-cols-4'}`}>\n            {people.map((p) => (\n              <li key={p.name}>\n                <img src={p.image} alt={p.alt} loading=\"lazy\" className=\"aspect-(--ratio-card) w-full rounded-(--radius-media) object-cover\" />\n                <p className={variant === 'large' ? 'type-heading mt-5 [font-size:clamp(1.3rem,2.2vw,1.9rem)]' : 'type-body mt-4 font-medium'}>{p.name}</p>\n                <p className=\"type-utility text-(--color-muted)\">{p.role}</p>\n                {p.line && <p className={`type-body mt-2 text-(--color-muted) ${variant === 'large' ? 'max-w-[44ch]' : ''}`}>{p.line}</p>}\n              </li>\n            ))}\n          </ul>\n        )}\n      </div>\n    </section>\n  )\n}\n",
  "stats": "// OpusKit section — Stats: three or four real numbers that prove something, each with a plain label. Numbers are set\n// in the display face; nothing counts up (a number people can read at once is the point). Three designs:\n//   row    — the numbers side by side under a rule.\n//   giant  — the first number huge across the page, the others small in a row beneath (one number matters most).\n//   ledger — one line per number: the label on the left, the number on the right, rules between (a calm, exact list).\ntype Stat = { value: string; label: string }\n\nexport function StatsSection({ tone, variant = 'row', title, stats, note }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'row' | 'giant' | 'ledger'; title?: string; stats: Stat[]; note?: string }) {\n  const t = tone === 'ground' ? undefined : tone\n  const [first, ...rest] = stats\n  const row = (list: Stat[], size: string) => (\n    <dl className=\"mt-8 grid grid-cols-2 gap-y-10 border-t border-(--color-border) pt-8 md:grid-cols-4\">\n      {list.map((s) => (\n        <div key={s.label} className=\"flex flex-col pr-6\">\n          <dt className=\"type-utility order-2 mt-3 text-(--color-muted)\">{s.label}</dt>\n          <dd className={`type-display order-1 leading-none ${size}`}>{s.value}</dd>\n        </div>\n      ))}\n    </dl>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*0.85)]\">\n      <div className=\"mx-auto max-w-(--container)\">\n        {title && <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>}\n        {variant === 'giant' && first ? <>\n          <p className=\"mt-6 flex flex-wrap items-end gap-x-6 gap-y-2\">\n            <span className=\"type-display leading-[0.85] [font-size:clamp(5rem,18vw,15rem)]\">{first.value}</span>\n            <span className=\"type-heading pb-[0.6em] [font-size:clamp(1.1rem,2vw,1.6rem)]\">{first.label}</span>\n          </p>\n          {rest.length > 0 && row(rest, '[font-size:clamp(1.8rem,3vw,2.6rem)]')}\n        </> : variant === 'ledger' ? (\n          <dl className=\"mt-8 border-t border-(--color-border)\">\n            {stats.map((s) => (\n              <div key={s.label} className=\"flex items-baseline justify-between gap-6 border-b border-(--color-border) py-5\">\n                <dt className=\"type-body text-(--color-muted)\">{s.label}</dt>\n                <dd className=\"type-heading tabular-nums [font-size:clamp(1.6rem,3.2vw,2.8rem)]\">{s.value}</dd>\n              </div>\n            ))}\n          </dl>\n        ) : row(stats, '[font-size:clamp(2.4rem,5vw,4.5rem)]')}\n        {note && <p className=\"type-body mt-8 max-w-[60ch] text-(--color-muted)\">{note}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "clients": "// OpusKit section — Name wall: who you work with or what it connects to, real names set as type (no borrowed logos).\n// Three designs:\n//   grid   — names in ruled cells, a quiet wall of proof.\n//   inline — the names run as one big paragraph, the way a credits list reads.\n//   split  — a title and a line on the left, the names in cells on the right (tools, partners) — names only, never letters standing in for logos.\nexport function NameWallSection({ tone, variant = 'grid', title, text, names }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'grid' | 'inline' | 'split'; title: string; text?: string; names: string[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  if (variant === 'split') return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*0.85)]\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <div className=\"md:col-span-4\">\n          <h2 className=\"type-heading text-balance\">{title}</h2>\n          {text && <p className=\"type-body mt-4 max-w-[40ch] text-(--color-muted)\">{text}</p>}\n        </div>\n        <ul className=\"grid grid-cols-2 self-start border-l border-t border-(--color-border) sm:grid-cols-3 md:col-span-8\">\n          {names.map((n) => (\n            <li key={n} className=\"type-body border-b border-r border-(--color-border) px-4 py-5 md:px-5 md:py-6\">{n}</li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n  if (variant === 'inline') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        <ul className=\"mt-8 flex flex-wrap gap-x-[0.6em] gap-y-1 type-display text-balance [font-size:clamp(1.8rem,4.6vw,4.2rem)] leading-[1.05]\">\n          {names.map((n, i) => <li key={n} className={i % 2 ? 'text-(--color-muted)' : undefined}>{n}{i < names.length - 1 ? ',' : ''}</li>)}\n        </ul>\n        {text && <p className=\"type-body mt-8 max-w-[56ch] text-(--color-muted)\">{text}</p>}\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*0.85)]\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        <ul className=\"mt-8 grid grid-cols-2 border-l border-t border-(--color-border) md:grid-cols-4\">\n          {names.map((n) => <li key={n} className=\"type-heading border-b border-r border-(--color-border) px-5 py-8 [font-size:clamp(1.05rem,1.6vw,1.35rem)]\">{n}</li>)}\n        </ul>\n        {text && <p className=\"type-body mt-6 max-w-[56ch] text-(--color-muted)\">{text}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "menu": "// OpusKit section — Menu: real HTML (readable, searchable, translatable) in two columns, prices aligned.\nexport type MenuGroup = { name: string; items: { name: string; description?: string; price: string }[] }\n\nexport function MenuSection({ tone, title, groups, note }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; groups: MenuGroup[]; note?: string }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <div className=\"mt-12 grid gap-x-16 gap-y-12 md:grid-cols-2\">\n          {groups.map((g) => (\n            <div key={g.name}>\n              <h3 className=\"type-utility border-b border-(--color-text) pb-3\">{g.name}</h3>\n              <ul>\n                {g.items.map((it) => (\n                  <li key={it.name} className=\"border-b border-(--color-border) py-4\">\n                    <p className=\"flex items-baseline gap-3\"><span className=\"type-heading [font-size:1.15rem]\">{it.name}</span><span aria-hidden className=\"flex-1 border-b border-dotted border-(--color-border)\" /><span className=\"type-body tabular-nums\">{it.price}</span></p>\n                    {it.description && <p className=\"type-body mt-1 max-w-[50ch] text-(--color-muted)\">{it.description}</p>}\n                  </li>\n                ))}\n              </ul>\n            </div>\n          ))}\n        </div>\n        {note && <p className=\"type-utility mt-10 text-(--color-muted)\">{note}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "reservation": "// OpusKit section — Reservation: a short invitation, the practical facts, and the booking form beside them. The form is\n// the project's own, built from shadcn/ui (a Calendar in a Popover for the day, Selects for time and party size) and passed\n// in as `form`; it hands off to the booking link or email with the details filled in — no fake confirmation. This section\n// only lays it out, so no plain browser date, time or number input ships.\nimport type { ReactNode } from 'react'\n\nexport function ReservationSection({ tone, title, text, hours, phone, form }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; text: string; hours: string[]; phone: string; form: ReactNode }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-12 md:grid-cols-12\">\n        <div className=\"md:col-span-5\">\n          <h2 className=\"type-heading\">{title}</h2>\n          <p className=\"type-body mt-4 text-(--color-muted)\">{text}</p>\n          <ul className=\"type-body mt-6 space-y-1\">{hours.map((h) => <li key={h}>{h}</li>)}</ul>\n          <p className=\"type-body mt-4\">Rather call? <a href={`tel:${phone.replace(/\\s/g, '')}`} className=\"underline underline-offset-4\">{phone}</a></p>\n        </div>\n        <div className=\"rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) p-6 shadow-(--shadow-card) md:col-span-6 md:col-start-7 md:self-start\">{form}</div>\n      </div>\n    </section>\n  )\n}\n",
  "location": "// OpusKit section — Location: address, hours, how to get there, one exterior photo, and a real map link. `media`: side\n// (photo beside the facts), full (a wide photo, the facts in a row under it) or over (the facts on a card over the photo).\nimport type { ReactNode } from 'react'\ntype P = { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; media?: 'side' | 'full' | 'over'; title: string; address: string; hours: string[]; notes?: ReactNode; mapUrl: string; image: string; alt: string }\nexport function LocationSection({ tone, media = 'side', title, address, hours, notes, mapUrl, image, alt }: P) {\n  const map = <a href={mapUrl} target=\"_blank\" rel=\"noreferrer\" className=\"type-body inline-block rounded-(--radius-button) border border-(--color-text) px-5 py-2.5\">Open in maps</a>\n  const facts = <>\n    <address className=\"type-body whitespace-pre-line not-italic\">{address}</address>\n    <ul className=\"type-body space-y-1 text-(--color-muted)\">{hours.map((h) => <li key={h}>{h}</li>)}</ul>\n    {notes && <p className=\"type-body text-(--color-muted)\">{notes}</p>}\n  </>\n  if (media === 'over') return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"relative isolate px-(--gutter) py-(--section-y)\">\n      <img src={image} alt={alt} loading=\"lazy\" className=\"absolute inset-0 -z-10 h-full w-full object-cover\" />\n      <div className=\"mx-auto flex max-w-(--container) justify-end\">\n        <div className=\"w-full max-w-md space-y-5 rounded-(--radius-card) bg-(--color-background) p-8 shadow-(--shadow-card)\"><h2 className=\"type-heading\">{title}</h2>{facts}{map}</div>\n      </div>\n    </section>\n  )\n  if (media === 'full') return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <img src={image} alt={alt} loading=\"lazy\" className=\"mt-8 aspect-(--ratio-media) w-full rounded-(--radius-media) object-cover\" />\n        <div className=\"mt-8 grid gap-6 md:grid-cols-4 [&>*]:md:col-span-1\">{facts}<div>{map}</div></div>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-[4/3] w-full rounded-(--radius-media) object-cover md:col-span-7\" />\n        <div className=\"space-y-5 md:col-span-4 md:col-start-9\"><h2 className=\"type-heading\">{title}</h2>{facts}<div className=\"pt-1\">{map}</div></div>\n      </div>\n    </section>\n  )\n}\n",
  "collection": "import type { ElementType } from 'react'\n// OpusKit section — Collection: a full-height image with the season's title, then its key pieces.\nexport type Piece = { name: string; price: string; image: string; alt: string; href: string }\n\nexport function CollectionSection({ tone, link: L = 'a', season, title, text, image, alt, pieces }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; link?: ElementType; season: string; title: string; text: string; image: string; alt: string; pieces: Piece[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone}>\n      <div className=\"relative min-h-[90svh] overflow-hidden\">\n        <img src={image} alt={alt} className=\"absolute inset-0 size-full object-cover\" />\n        <div className=\"absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/55 to-transparent px-(--gutter) pb-10 pt-32 text-white\">\n          <p className=\"type-utility\">{season}</p>\n          <h2 className=\"type-display mt-2 [font-size:clamp(2.5rem,8vw,7rem)]\">{title}</h2>\n          <p className=\"type-body mt-4 max-w-[48ch] opacity-90\">{text}</p>\n        </div>\n      </div>\n      <ul className=\"mx-auto grid max-w-(--container) grid-cols-2 gap-4 px-(--gutter) py-[calc(var(--section-y)*0.5)] md:grid-cols-3\">\n        {pieces.map((p) => (\n          <li key={p.href}><L href={p.href} className=\"group block\">\n            <img src={p.image} alt={p.alt} loading=\"lazy\" className=\"aspect-(--ratio-card) w-full rounded-(--radius-media) object-cover\" />\n            <p className=\"mt-3 flex justify-between gap-3\"><span className=\"type-body group-hover:underline group-hover:underline-offset-4\">{p.name}</span><span className=\"type-body tabular-nums text-(--color-muted)\">{p.price}</span></p>\n          </L></li>\n        ))}\n      </ul>\n    </section>\n  )\n}\n",
  "lookbook": "import type { ElementType } from 'react'\n// OpusKit section — Lookbook: magazine spreads, a large and a small photo per look, with what is worn.\nexport type Look = { number: string; image: string; alt: string; detail?: string; detailAlt?: string; pieces: string; href?: string }\n\nexport function LookbookSection({ tone, link: L = 'a', title, looks }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; link?: ElementType; title?: string; looks: Look[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container) space-y-24\">\n        {title && <h2 className=\"type-heading\">{title}</h2>}\n        {looks.map((l, i) => (\n          <article key={l.number} className={`grid items-end gap-6 md:grid-cols-12 ${i % 2 ? 'md:[direction:rtl]' : ''}`}>\n            <img src={l.image} alt={l.alt} loading=\"lazy\" className=\"aspect-[3/4] w-full rounded-(--radius-media) object-cover md:col-span-7 [direction:ltr]\" />\n            <div className=\"md:col-span-4 [direction:ltr]\">\n              {l.detail && <img src={l.detail} alt={l.detailAlt ?? ''} loading=\"lazy\" className=\"mb-6 aspect-square w-2/3 rounded-(--radius-media) object-cover\" />}\n              <p className=\"type-display [font-size:clamp(2rem,4vw,3.5rem)]\">Look {l.number}</p>\n              <p className=\"type-body mt-3 text-(--color-muted)\">{l.pieces}</p>\n              {l.href && <L href={l.href} className=\"type-body mt-4 inline-block underline underline-offset-4\">Shop the look</L>}\n            </div>\n          </article>\n        ))}\n      </div>\n    </section>\n  )\n}\n",
  "product-grid": "import type { ElementType } from 'react'\n// OpusKit section — Product Grid: browse and choose. Even tiles, one ratio, second photo on hover, honest availability.\nexport type Product = { name: string; price: string; image: string; alt: string; hoverImage?: string; href: string; soldOut?: boolean }\n\nexport function ProductGridSection({ tone, link: L = 'a', title, products }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; link?: ElementType; title: string; products: Product[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className=\"mt-10 grid grid-cols-2 gap-x-4 gap-y-10 md:grid-cols-3 xl:grid-cols-4\">\n          {products.map((p) => (\n            <li key={p.href}>\n              <L href={p.href} className=\"group block\">\n                <div className=\"relative overflow-hidden rounded-(--radius-media) bg-(--color-surface)\">\n                  <img src={p.image} alt={p.alt} loading=\"lazy\" className=\"aspect-(--ratio-card) w-full object-cover\" />\n                  {p.hoverImage && <img src={p.hoverImage} alt=\"\" loading=\"lazy\" className=\"absolute inset-0 size-full object-cover opacity-0 transition-opacity duration-300 group-hover:opacity-100\" />}\n                  {p.soldOut && <span className=\"type-utility absolute left-3 top-3 rounded-(--radius-button) bg-(--color-background) px-2 py-1\">Sold out</span>}\n                </div>\n                <p className=\"mt-3 flex justify-between gap-3\"><span className=\"type-body group-hover:underline group-hover:underline-offset-4\">{p.name}</span><span className=\"type-body tabular-nums text-(--color-muted)\">{p.price}</span></p>\n              </L>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "product-highlight": "import type { ElementType } from 'react'\n// OpusKit section — Product Highlight: one product (or feature) in depth — large media and 3–4 real details. `media`:\n// side (media beside the details), full (the product across the page, name and details in a row beneath) or over (the\n// product on its own colour field with the name set over it).\ntype P = { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; media?: 'side' | 'full' | 'over'; link?: ElementType; name: string; text: string; image: string; alt: string; details: { label: string; value: string }[]; action: { label: string; href: string } }\nexport function ProductHighlightSection({ tone, media = 'side', link: L = 'a', name, text, image, alt, details, action }: P) {\n  const list = <dl className=\"divide-y divide-(--color-border) border-y border-(--color-border)\">{details.map((d) => <div key={d.label} className=\"flex justify-between gap-4 py-3\"><dt className=\"type-utility text-(--color-muted)\">{d.label}</dt><dd className=\"type-body text-right\">{d.value}</dd></div>)}</dl>\n  const buy = <L href={action.href} className=\"type-body inline-block rounded-(--radius-button) bg-(--color-primary) px-6 py-3 text-(--color-background)\">{action.label}</L>\n  if (media === 'over') return (\n    <section data-tone={tone === 'ground' ? 'surface' : tone ?? 'surface'} className=\"overflow-hidden px-(--gutter) py-(--section-y)\">\n      <div className=\"relative mx-auto max-w-(--container) text-center\">\n        <h2 className=\"type-display relative z-10 leading-[0.85] [font-size:clamp(3.5rem,13vw,12rem)]\">{name}</h2>\n        <img src={image} alt={alt} loading=\"lazy\" className=\"relative z-20 mx-auto -mt-[6vw] aspect-square w-full max-w-xl object-contain\" />\n        <p className=\"type-body mx-auto mt-8 max-w-[52ch] text-(--color-muted)\">{text}</p>\n        <div className=\"mx-auto mt-8 max-w-xl text-left\">{list}</div>\n        <div className=\"mt-8\">{buy}</div>\n      </div>\n    </section>\n  )\n  if (media === 'full') return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-(--ratio-media) w-full rounded-(--radius-media) bg-(--color-surface) object-cover\" />\n        <div className=\"mt-10 grid gap-10 md:grid-cols-12\">\n          <div className=\"md:col-span-5\"><h2 className=\"type-display [font-size:clamp(2.2rem,4.5vw,4rem)]\">{name}</h2><p className=\"type-body mt-4 text-(--color-muted)\">{text}</p><div className=\"mt-8\">{buy}</div></div>\n          <div className=\"md:col-span-6 md:col-start-7\">{list}</div>\n        </div>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) items-center gap-12 md:grid-cols-12\">\n        <img src={image} alt={alt} loading=\"lazy\" className=\"aspect-square w-full rounded-(--radius-media) bg-(--color-surface) object-cover md:col-span-7\" />\n        <div className=\"md:col-span-4 md:col-start-9\">\n          <h2 className=\"type-display [font-size:clamp(2.2rem,4.5vw,4rem)]\">{name}</h2>\n          <p className=\"type-body mt-4 text-(--color-muted)\">{text}</p>\n          <div className=\"mt-8\">{list}</div>\n          <div className=\"mt-8\">{buy}</div>\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "feature-grid": "// OpusKit section — Features: 3–6 capabilities in concrete language, each with a real visual when there is one.\nexport function FeatureGridSection({ tone, title, features }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; features: { name: string; text: string; image?: string; alt?: string }[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading max-w-[24ch]\">{title}</h2>\n        <ul className=\"mt-12 grid gap-px overflow-hidden rounded-(--radius-card) border border-(--color-border) bg-(--color-border) md:grid-cols-2 xl:grid-cols-3\">\n          {features.map((f) => (\n            <li key={f.name} className=\"bg-(--color-background) p-6 md:p-8\">\n              {f.image && <img src={f.image} alt={f.alt ?? ''} loading=\"lazy\" className=\"mb-6 aspect-(--ratio-media) w-full rounded-(--radius-media) object-cover\" />}\n              <h3 className=\"type-heading [font-size:clamp(1.15rem,1.6vw,1.4rem)]\">{f.name}</h3>\n              <p className=\"type-body mt-2 text-(--color-muted)\">{f.text}</p>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "pricing": "import type { ElementType } from 'react'\n// OpusKit section — Pricing: 2–3 plans, one recommended, everything each includes in plain words. Two designs:\n//   cards — plans side by side as cards, the recommended one outlined in the accent.\n//   table — one ruled row per plan: name and line, price, what it includes, the action (calm, easy to compare).\nexport type Plan = { name: string; price: string; period?: string; line?: string; features: string[]; action: { label: string; href: string }; recommended?: boolean }\n\nexport function PricingSection({ tone, variant = 'cards', link: L = 'a', title, plans, note }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'cards' | 'table'; link?: ElementType; title: string; plans: Plan[]; note?: string }) {\n  const t = tone === 'ground' ? undefined : tone\n  const button = (p: Plan, extra = '') => <L href={p.action.href} className={`type-body rounded-(--radius-button) px-5 py-3 text-center ${p.recommended ? 'bg-(--color-primary) text-(--color-background)' : 'border border-(--color-text)'} ${extra}`}>{p.action.label}</L>\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        {variant === 'table' ? (\n          <ul className=\"mt-12 border-t border-(--color-text)\">\n            {plans.map((p) => (\n              <li key={p.name} className=\"grid gap-6 border-b border-(--color-border) py-8 md:grid-cols-12 md:items-start\">\n                <div className=\"md:col-span-3\">\n                  <h3 className=\"type-heading [font-size:clamp(1.3rem,2vw,1.7rem)]\">{p.name}</h3>\n                  {p.recommended && <p className=\"type-utility mt-1 text-(--color-accent)\">Recommended</p>}\n                  {p.line && <p className=\"type-body mt-2 text-(--color-muted)\">{p.line}</p>}\n                </div>\n                <p className=\"md:col-span-3\"><span className=\"type-display [font-size:clamp(2.2rem,3.6vw,3.2rem)]\">{p.price}</span>{p.period && <span className=\"type-body text-(--color-muted)\"> / {p.period}</span>}</p>\n                <ul className=\"type-body space-y-1 text-(--color-muted) md:col-span-4\">{p.features.map((f) => <li key={f}>{f}</li>)}</ul>\n                <div className=\"md:col-span-2 md:text-right\">{button(p, 'inline-block')}</div>\n              </li>\n            ))}\n          </ul>\n        ) : (\n          <ul className=\"mt-12 grid gap-6 md:grid-cols-[repeat(auto-fit,minmax(16rem,1fr))]\">\n            {plans.map((p) => (\n              <li key={p.name} className={`flex flex-col rounded-(--radius-card) border bg-(--color-surface) p-7 shadow-(--shadow-card) ${p.recommended ? 'border-(--color-accent) ring-1 ring-(--color-accent)' : 'border-(--color-border)'}`}>\n                <div className=\"flex items-baseline justify-between gap-3\"><h3 className=\"type-heading [font-size:1.3rem]\">{p.name}</h3>{p.recommended && <span className=\"type-utility text-(--color-accent)\">Recommended</span>}</div>\n                {p.line && <p className=\"type-body mt-2 text-(--color-muted)\">{p.line}</p>}\n                <p className=\"mt-6\"><span className=\"type-display [font-size:clamp(2.5rem,4vw,3.5rem)]\">{p.price}</span>{p.period && <span className=\"type-body text-(--color-muted)\"> / {p.period}</span>}</p>\n                <ul className=\"type-body mt-6 flex-1 space-y-2\">{p.features.map((f) => <li key={f} className=\"border-t border-(--color-border) pt-2\">{f}</li>)}</ul>\n                {button(p, 'mt-8')}\n              </li>\n            ))}\n          </ul>\n        )}\n        {note && <p className=\"type-utility mt-8 text-(--color-muted)\">{note}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "faq": "// OpusKit section — FAQ: real questions in a narrow column beside the title. The list itself is the project's own\n// shadcn/ui Accordion (type=\"single\" collapsible), passed as children and styled through the tokens — this section only\n// lays it out, so no hand-made disclosure ships.\nimport type { ReactNode } from 'react'\n\nexport function FaqSection({ tone, title, children }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; children: ReactNode }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <h2 className=\"type-heading md:col-span-4\">{title}</h2>\n        <div className=\"border-t border-(--color-border) md:col-span-7 md:col-start-6\">{children}</div>\n      </div>\n    </section>\n  )\n}\n",
  "journal": "import type { ElementType } from 'react'\n// OpusKit section — Journal: the latest 3 entries as an editorial list — date, category, title.\nexport type Entry = { title: string; date: string; category: string; href: string; image?: string; alt?: string }\n\nexport function JournalSection({ tone, link: L = 'a', title, entries, allHref }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; link?: ElementType; title: string; entries: Entry[]; allHref?: string }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <div className=\"flex items-baseline justify-between gap-4\"><h2 className=\"type-heading\">{title}</h2>{allHref && <L href={allHref} className=\"type-body underline underline-offset-4\">All entries</L>}</div>\n        <ul className=\"mt-10 grid gap-8 md:grid-cols-3\">\n          {entries.map((e) => (\n            <li key={e.href}><L href={e.href} className=\"group block\">\n              {e.image && <img src={e.image} alt={e.alt ?? ''} loading=\"lazy\" className=\"mb-4 aspect-(--ratio-media) w-full rounded-(--radius-media) object-cover\" />}\n              <p className=\"type-utility text-(--color-muted)\"><time>{e.date}</time>, {e.category}</p>\n              <h3 className=\"type-heading mt-2 [font-size:clamp(1.15rem,1.6vw,1.45rem)] group-hover:underline group-hover:underline-offset-4\">{e.title}</h3>\n            </L></li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "contact-cta": "import type { ElementType } from 'react'\n// OpusKit section — Closing CTA: one headline in the brand voice (optionally two voices), one action, and a real way\n// to reach you. `tone=\"inverse\"` (or the older `inverse`) ends the page on the text colour. Three designs:\n//   statement — the headline huge, one button and the email under it.\n//   write     — a short letter to fill in: the sentence is the form (\"Hi, I'm ___ and I'd like to talk about ___\"),\n//               sent to `action.href` (your form endpoint) — writing to you feels like talking.\n//   details   — the headline on the left, the ways to reach you set large on the right (email, phone, address).\nexport function ContactCtaSection({ tone, variant = 'statement', link: L = 'a', headline, quiet, action, email, phone, address, inverse = false }: {\n  tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'statement' | 'write' | 'details'; link?: ElementType; headline: string; quiet?: string\n  action: { label: string; href: string }; email?: string; phone?: string; address?: string; inverse?: boolean\n}) {\n  const t = inverse ? 'inverse' : tone === 'ground' ? undefined : tone\n  const title = <h2 className=\"type-display text-balance [font-size:clamp(2.75rem,8vw,7.5rem)]\">{headline}{quiet && <span className=\"block font-(family-name:--font-heading) [font-stretch:var(--type-heading-stretch)] [font-weight:var(--type-heading-weight)]\">{quiet}</span>}</h2>\n  const field = 'mx-1 inline-block min-w-[8ch] border-b border-(--color-text) bg-transparent px-1 align-baseline text-(--color-text) outline-none placeholder:text-(--color-muted) focus:border-(--color-accent)'\n\n  if (variant === 'write') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-utility text-(--color-muted)\">{headline}</h2>\n        <form action={action.href} method=\"post\" className=\"type-heading mt-8 max-w-[36ch] leading-[1.6] [font-size:clamp(1.5rem,3.4vw,2.9rem)]\">\n          Hi, I’m <input name=\"name\" required aria-label=\"Your name\" placeholder=\"your name\" autoComplete=\"name\" className={field} />\n          and I’d like to talk about <input name=\"topic\" required aria-label=\"What it is about\" placeholder=\"a project\" className={`${field} min-w-[12ch]`} />.\n          You can reach me at <input name=\"email\" type=\"email\" required aria-label=\"Your email\" placeholder=\"you@example.com\" autoComplete=\"email\" className={`${field} min-w-[14ch]`} />.\n          <span className=\"mt-10 flex flex-wrap items-center gap-x-8 gap-y-4 [font-size:1rem]\">\n            <button type=\"submit\" className=\"type-body rounded-(--radius-button) bg-(--color-primary) px-7 py-3.5 text-(--color-background)\">{action.label}</button>\n            {email && <a href={`mailto:${email}`} className=\"type-body underline underline-offset-4\">or write to {email}</a>}\n          </span>\n        </form>\n      </div>\n    </section>\n  )\n  if (variant === 'details') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-12 md:grid-cols-12 md:items-end\">\n        <div className=\"md:col-span-7\">{title}</div>\n        <div className=\"space-y-6 md:col-span-5\">\n          {email && <a href={`mailto:${email}`} className=\"type-heading block break-words underline-offset-4 hover:underline [font-size:clamp(1.4rem,2.6vw,2.2rem)]\">{email}</a>}\n          {phone && <a href={`tel:${phone.replace(/\\s/g, '')}`} className=\"type-heading block underline-offset-4 hover:underline [font-size:clamp(1.4rem,2.6vw,2.2rem)]\">{phone}</a>}\n          {address && <p className=\"type-body text-(--color-muted)\">{address}</p>}\n          <L href={action.href} className=\"type-body inline-block rounded-(--radius-button) bg-(--color-primary) px-7 py-3.5 text-(--color-background)\">{action.label}</L>\n        </div>\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*1.25)]\">\n      <div className=\"mx-auto max-w-(--container)\">\n        {title}\n        <div className=\"mt-10 flex flex-wrap items-center gap-x-8 gap-y-4\">\n          <L href={action.href} className=\"type-body rounded-(--radius-button) bg-(--color-primary) px-7 py-3.5 text-(--color-background)\">{action.label}</L>\n          {email && <a href={`mailto:${email}`} className=\"type-body underline underline-offset-4\">{email}</a>}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "chapters": "// OpusKit section — Colour Chapters: each offer is a chapter; its text sits on the neutral half, the other half is a\n// full field in that chapter's colour (--color-chapter-1..3, the recipe's colour chapters) holding a sticky photo or clip.\nexport type Chapter = { eyebrow: string; title: string; text: string; media: { src: string; alt: string; video?: boolean }; sticker?: { src: string; alt: string } }\n\nexport function ColourChaptersSection({ chapters }: { chapters: Chapter[] }) {\n  return (\n    <section>\n      {chapters.map((c, i) => (\n        <article key={c.title} className=\"grid md:min-h-[140svh] md:grid-cols-2\">\n          <div className=\"md:order-2\">\n            <div className=\"grid place-items-center px-8 py-16 md:sticky md:top-0 md:h-svh md:px-14\" style={{ background: `var(--color-chapter-${(i % 3) + 1}, var(--color-accent))` }}>\n              {c.media.video\n                ? <video src={c.media.src} autoPlay muted loop playsInline aria-label={c.media.alt} className=\"aspect-(--ratio-card) w-full max-w-[34rem] rounded-(--radius-media) object-cover\" />\n                : <img src={c.media.src} alt={c.media.alt} loading=\"lazy\" className=\"aspect-(--ratio-card) w-full max-w-[34rem] rounded-(--radius-media) object-cover\" />}\n            </div>\n          </div>\n          <div className=\"relative grid content-start px-6 py-20 text-center md:sticky md:top-0 md:h-svh md:content-center md:px-16\">\n            {c.sticker && <img src={c.sticker.src} alt={c.sticker.alt} loading=\"lazy\" className=\"absolute left-6 top-24 w-28 -rotate-6 md:left-10 md:w-36\" />}\n            <p className=\"type-utility\">{c.eyebrow}</p>\n            <h2 className=\"type-display mt-2 [font-size:clamp(3rem,7vw,6rem)]\">{c.title}</h2>\n            <p className=\"type-body mx-auto mt-5 max-w-[44ch]\">{c.text}</p>\n          </div>\n        </article>\n      ))}\n    </section>\n  )\n}\n",
  "feature-rows": "import type { ElementType } from 'react'\n// OpusKit section — Feature rows: one capability or offer per row. `media`: side (picture beside words, sides\n// alternating on desktop), full (each row a wide picture with its words in two columns under it) or over (each row's\n// words on a card laid over its picture).\ntype Row = { name: string; text: string; image?: string; alt?: string; link?: { label: string; href: string } }\ntype P = { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; media?: 'side' | 'full' | 'over'; link?: ElementType; title?: string; rows: Row[] }\nexport function FeatureRowsSection({ tone, media = 'side', link: L = 'a', title, rows }: P) {\n  const words = (r: Row) => <>\n    <h3 className=\"type-heading text-balance [font-size:clamp(1.5rem,2.6vw,2.4rem)]\">{r.name}</h3>\n    {r.text && <p className=\"type-body mt-4 max-w-[46ch] text-(--color-muted)\">{r.text}</p>}\n    {r.link && <L href={r.link.href} className=\"type-body mt-6 inline-block underline underline-offset-4\">{r.link.label}</L>}\n  </>\n  const pic = (r: Row, cls: string) => r.image && <img src={r.image} alt={r.alt ?? ''} loading=\"lazy\" className={`w-full rounded-(--radius-media) bg-(--color-surface) object-cover ${cls}`} />\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        {title && <h2 className=\"type-heading mb-16 max-w-[24ch] md:mb-24\">{title}</h2>}\n        <ul className=\"space-y-20 md:space-y-32\">\n          {rows.map((r, i) => media === 'over' && r.image ? (\n            <li key={r.name} className=\"relative\">\n              {pic(r, 'aspect-(--ratio-media)')}\n              <div className={`relative -mt-24 w-[88%] rounded-(--radius-card) bg-(--color-background) p-8 md:absolute md:bottom-10 md:mt-0 md:w-[min(30rem,40%)] ${i % 2 ? 'md:left-10' : 'ml-auto md:right-10'}`}>{words(r)}</div>\n            </li>\n          ) : media === 'full' && r.image ? (\n            <li key={r.name}>\n              {pic(r, 'aspect-(--ratio-media)')}\n              <div className=\"mt-8 grid gap-6 md:grid-cols-12\"><div className=\"md:col-span-5\">{words({ ...r, text: '', link: undefined })}</div><div className=\"md:col-span-6 md:col-start-7\"><p className=\"type-body max-w-[46ch] text-(--color-muted)\">{r.text}</p>{r.link && <L href={r.link.href} className=\"type-body mt-6 inline-block underline underline-offset-4\">{r.link.label}</L>}</div></div>\n            </li>\n          ) : (\n            <li key={r.name} className=\"grid items-center gap-8 md:grid-cols-12 md:gap-10\">\n              {pic(r, `aspect-[4/3] md:col-span-7 ${i % 2 ? 'md:order-2 md:col-start-6' : ''}`)}\n              <div className={!r.image ? 'md:col-span-8' : i % 2 ? 'md:order-1 md:col-span-4 md:col-start-1' : 'md:col-span-4 md:col-start-9'}>{words(r)}</div>\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "newsletter": "// OpusKit section — Newsletter: one reason to subscribe, an email field and a button, and a plain note on how often.\nexport function NewsletterSection({ tone, title, text, placeholder, button, note, action, label = 'Email address' }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; text: string; placeholder: string; button: string; note?: string; action?: string; label?: string }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12 md:items-end\">\n        <div className=\"md:col-span-6\">\n          <h2 className=\"type-heading text-balance\">{title}</h2>\n          <p className=\"type-body mt-4 max-w-[52ch] text-(--color-muted)\">{text}</p>\n        </div>\n        <form action={action} method={action ? 'post' : undefined} className=\"md:col-span-5 md:col-start-8\">\n          <div className=\"flex flex-col gap-3 sm:flex-row sm:items-end\">\n            <label className=\"type-utility flex-1 text-(--color-muted)\">{label}\n              <input required type=\"email\" name=\"email\" autoComplete=\"email\" placeholder={placeholder} className=\"type-body mt-2 block w-full rounded-(--radius-button) border border-(--color-border) bg-(--color-surface) px-4 py-3 text-(--color-text) placeholder:text-(--color-muted)\" />\n            </label>\n            <button type=\"submit\" className=\"type-body shrink-0 rounded-(--radius-button) bg-(--color-primary) px-6 py-3 text-(--color-background)\">{button}</button>\n          </div>\n          {note && <p className=\"type-utility mt-3 text-(--color-muted)\">{note}</p>}\n        </form>\n      </div>\n    </section>\n  )\n}\n",
  "categories": "import type { ElementType } from 'react'\n// OpusKit section — Categories: tiles that show the range at a glance — a picture, a name and how many are inside.\nexport function CategoriesSection({ tone, link: L = 'a', title, items }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; link?: ElementType; title: string; items: { name: string; href?: string; image?: string; alt?: string; count?: string }[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <ul className={`mt-10 grid grid-cols-2 gap-x-4 gap-y-8 md:gap-x-6 ${items.length % 3 === 0 ? 'md:grid-cols-3' : 'md:grid-cols-4'}`}>\n          {items.map((c) => {\n            const tile = (\n              <>\n                <div className=\"aspect-(--ratio-card) overflow-hidden rounded-(--radius-media) bg-(--color-surface)\">\n                  {c.image && <img src={c.image} alt={c.alt ?? ''} loading=\"lazy\" className=\"size-full object-cover transition-transform duration-500 motion-safe:group-hover:scale-[1.03]\" />}\n                </div>\n                <div className=\"mt-4 flex items-baseline justify-between gap-3\">\n                  <h3 className=\"type-heading [font-size:clamp(1.1rem,1.6vw,1.4rem)] group-hover:underline group-hover:underline-offset-4\">{c.name}</h3>\n                  {c.count && <span className=\"type-utility shrink-0 text-(--color-muted)\">{c.count}</span>}\n                </div>\n              </>\n            )\n            return <li key={c.name}>{c.href ? <L href={c.href} className=\"group block\">{tile}</L> : tile}</li>\n          })}\n        </ul>\n      </div>\n    </section>\n  )\n}\n",
  "press": "// OpusKit section — Press: what outlets wrote, the outlet set as type (no borrowed logos), awards in a quiet line.\n// Two designs:\n//   grid  — every quote in a ruled cell, its outlet large beneath.\n//   quote — the best line as one big pull quote, the other outlets named in a row under it.\nexport function PressSection({ tone, variant = 'grid', title, quotes, awards }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'grid' | 'quote'; title: string; quotes: { outlet: string; quote: string }[]; awards?: string[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  const [lead, ...rest] = quotes\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*0.85)]\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        {variant === 'quote' && lead ? (\n          <figure className=\"mt-10\">\n            <blockquote className=\"type-heading max-w-[30ch] text-balance [font-size:clamp(1.8rem,4vw,3.6rem)] leading-[1.08]\">“{lead.quote}”</blockquote>\n            <figcaption className=\"type-display mt-8 [font-size:clamp(1.3rem,2.2vw,1.9rem)]\">{lead.outlet}</figcaption>\n            {rest.length > 0 && <p className=\"type-utility mt-10 flex flex-wrap gap-x-8 gap-y-2 border-t border-(--color-border) pt-6 text-(--color-muted)\"><span>Also in</span>{rest.map((q) => <span key={q.outlet} className=\"text-(--color-text)\">{q.outlet}</span>)}</p>}\n          </figure>\n        ) : (\n          <ul className=\"mt-8 grid border-l border-t border-(--color-border) md:grid-cols-3\">\n            {quotes.map((q) => (\n              <li key={q.outlet} className=\"border-b border-r border-(--color-border) p-6 md:p-8\">\n                <figure className=\"flex h-full flex-col justify-between gap-10\">\n                  <blockquote className=\"type-body text-balance [font-size:clamp(1.05rem,1.4vw,1.25rem)]\">“{q.quote}”</blockquote>\n                  <figcaption className=\"type-display [font-size:clamp(1.2rem,1.8vw,1.6rem)]\">{q.outlet}</figcaption>\n                </figure>\n              </li>\n            ))}\n          </ul>\n        )}\n        {awards && awards.length > 0 && (\n          <ul aria-label=\"Awards\" className=\"type-utility mt-8 flex flex-wrap gap-x-8 gap-y-2 text-(--color-muted)\">\n            {awards.map((a) => <li key={a}>{a}</li>)}\n          </ul>\n        )}\n      </div>\n    </section>\n  )\n}\n",
  "cta-band": "import type { ElementType } from 'react'\n// OpusKit section — CTA band: a slim mid-page offer — one line and one action — that keeps the page going rather than ending it.\nexport function CtaBandSection({ tone, link: L = 'a', text, action, note }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; link?: ElementType; text: string; action: { label: string; href: string }; note?: string }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-[calc(var(--section-y)*0.35)]\">\n      <div className=\"mx-auto flex max-w-(--container) flex-col gap-6 rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) px-6 py-8 md:flex-row md:items-center md:justify-between md:px-10\">\n        <div>\n          <h2 className=\"type-heading text-balance [font-size:clamp(1.3rem,2.4vw,2rem)]\">{text}</h2>\n          {note && <p className=\"type-utility mt-2 text-(--color-muted)\">{note}</p>}\n        </div>\n        <L href={action.href} className=\"type-body shrink-0 self-start rounded-(--radius-button) bg-(--color-primary) px-6 py-3 text-(--color-background) md:self-auto\">{action.label}</L>\n      </div>\n    </section>\n  )\n}\n",
  "trust": "// OpusKit section — Trust strip: 3–5 short promises (shipping, returns, trial, guarantee) in one quiet row.\nconst COLS: Record<number, string> = { 3: 'lg:grid-cols-3', 4: 'lg:grid-cols-4', 5: 'lg:grid-cols-5' }\n\nexport function TrustSection({ tone, items }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; items: { title: string; text: string }[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} aria-label=\"Our promises\" className=\"px-(--gutter) py-[calc(var(--section-y)*0.6)]\">\n      <ul className={`mx-auto grid max-w-(--container) border-y border-(--color-border) sm:grid-cols-2 ${COLS[items.length] ?? 'lg:grid-cols-4'}`}>\n        {items.map((t, i) => (\n          <li key={t.title} className={`py-8 sm:px-6 lg:py-10 ${i ? 'border-t border-(--color-border) sm:border-t-0 lg:border-l' : 'sm:pl-0'}`}>\n            <span aria-hidden className=\"block h-px w-6 bg-(--color-accent)\" />\n            <p className=\"type-heading mt-5 [font-size:clamp(1.15rem,1.7vw,1.45rem)]\">{t.title}</p>\n            <p className=\"type-body mt-2 max-w-[30ch] text-(--color-muted)\">{t.text}</p>\n          </li>\n        ))}\n      </ul>\n    </section>\n  )\n}\n",
  "schedule": "// OpusKit section — Schedule: the programme day by day — time, what happens, a line of detail. Days sit side by side\n// on wide screens and stack on phones; no tabs, so everything stays readable and searchable.\nexport function ScheduleSection({ tone, title, days }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; days: { label: string; items: { time: string; title: string; detail?: string }[] }[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        <div className={`mt-12 grid gap-12 md:gap-10 ${days.length > 1 ? 'md:grid-cols-2' : ''} ${days.length > 2 ? 'xl:grid-cols-3' : ''}`}>\n          {days.map((d) => (\n            <div key={d.label}>\n              <h3 className=\"type-utility border-b border-(--color-text) pb-3\">{d.label}</h3>\n              <ol className=\"divide-y divide-(--color-border)\">\n                {d.items.map((it) => (\n                  <li key={it.time + it.title} className=\"grid grid-cols-[5rem_1fr] gap-4 py-4\">\n                    <span className=\"type-body text-(--color-muted) tabular-nums\">{it.time}</span>\n                    <div>\n                      <p className=\"type-heading [font-size:clamp(1.05rem,1.4vw,1.25rem)]\">{it.title}</p>\n                      {it.detail && <p className=\"type-body mt-1 text-(--color-muted)\">{it.detail}</p>}\n                    </div>\n                  </li>\n                ))}\n              </ol>\n            </div>\n          ))}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "product-buy": "'use client'\n// OpusKit section — Product buy box: everything needed to buy one product on its own page — the pictures, the name and\n// price, one choice (colour or size) as buttons, how many, the button, and the details people check before paying, each\n// opening in place. Two designs:\n//   sticky — the pictures stacked down the left (a swipeable row on phones); the buy column stays in view beside them.\n//   mosaic — the pictures as a mosaic (the first one large); the buy column beside it.\nimport { useState, type ElementType, type ReactNode } from 'react'\n\ntype Img = { src: string; alt: string }\nexport type BuyDetail = { title: string; text: string }\n\nexport function ProductBuySection({ tone, variant = 'sticky', link: L = 'a', name, price, line, images, option, details = [], action, onAction, note }: {\n  tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'sticky' | 'mosaic'; link?: ElementType\n  name: ReactNode; price: string; line?: string; images: Img[]\n  /** One choice, e.g. { label: 'Colour', values: ['Oat', 'Ink'] }. */ option?: { label: string; values: string[] }\n  details?: BuyDetail[]; action: { label: string; href: string }; note?: string\n  /** When given, the action is a button that hands over the chosen quantity and option (e.g. add to a client-side bag). */\n  onAction?: (qty: number, option?: string) => void\n}) {\n  const [pick, setPick] = useState(0)\n  const [qty, setQty] = useState(1)\n  const [open, setOpen] = useState<number | null>(0)\n  const pics = variant === 'mosaic' ? (\n    <div className=\"grid grid-cols-2 gap-3 md:col-span-7\">\n      {images.map((m, i) => <img key={m.src + i} src={m.src} alt={m.alt} loading={i ? 'lazy' : undefined} className={`w-full rounded-(--radius-media) object-cover ${i === 0 ? 'col-span-2 aspect-(--ratio-media)' : 'aspect-(--ratio-card)'}`} />)}\n    </div>\n  ) : (\n    <div className=\"-mx-(--gutter) flex snap-x snap-mandatory gap-3 overflow-x-auto px-(--gutter) md:col-span-7 md:mx-0 md:block md:space-y-3 md:overflow-visible md:px-0\">\n      {images.map((m, i) => <img key={m.src + i} src={m.src} alt={m.alt} loading={i ? 'lazy' : undefined} className={`aspect-(--ratio-card) shrink-0 snap-center rounded-(--radius-media) object-cover md:w-full ${images.length > 1 ? 'w-[85%]' : 'w-full'}`} />)}\n    </div>\n  )\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-[calc(var(--section-y)*0.6)]\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        {pics}\n        <div className={`md:col-span-5 ${variant === 'sticky' ? 'self-start md:sticky md:top-24' : ''}`}>\n          <h1 className=\"type-heading [font-size:clamp(1.8rem,3vw,2.8rem)]\">{name}</h1>\n          <p className=\"type-heading mt-3 tabular-nums [font-size:1.4rem]\">{price}</p>\n          {line && <p className=\"type-body mt-4 max-w-[48ch] text-(--color-muted)\">{line}</p>}\n          {option && (\n            <div className=\"mt-8\">\n              <p className=\"type-utility text-(--color-muted)\">{option.label}: <span className=\"text-(--color-text)\">{option.values[pick]}</span></p>\n              <div role=\"radiogroup\" aria-label={option.label} className=\"mt-3 flex flex-wrap gap-2\">\n                {option.values.map((v, i) => (\n                  <button key={v} type=\"button\" role=\"radio\" aria-checked={i === pick} onClick={() => setPick(i)}\n                    className={`type-body rounded-(--radius-button) border px-4 py-2 ${i === pick ? 'border-(--color-text)' : 'border-(--color-border) text-(--color-muted) hover:border-(--color-text)'}`}>{v}</button>\n                ))}\n              </div>\n            </div>\n          )}\n          <div className=\"mt-8 flex gap-3\">\n            <div className=\"type-body flex items-center rounded-(--radius-button) border border-(--color-border)\">\n              <button type=\"button\" aria-label=\"One fewer\" onClick={() => setQty((q) => Math.max(1, q - 1))} className=\"px-4 py-3\">−</button>\n              <span aria-live=\"polite\" className=\"w-8 text-center tabular-nums\">{qty}</span>\n              <button type=\"button\" aria-label=\"One more\" onClick={() => setQty((q) => q + 1)} className=\"px-4 py-3\">+</button>\n            </div>\n            {onAction\n              ? <button type=\"button\" onClick={() => onAction(qty, option?.values[pick])} className=\"type-body flex-1 rounded-(--radius-button) bg-(--color-primary) px-6 py-3 text-center text-(--color-background)\">{action.label}</button>\n              : <L href={action.href} className=\"type-body flex-1 rounded-(--radius-button) bg-(--color-primary) px-6 py-3 text-center text-(--color-background)\">{action.label}</L>}\n          </div>\n          {note && <p className=\"type-utility mt-3 text-(--color-muted)\">{note}</p>}\n          {details.length > 0 && (\n            <ul className=\"mt-10 border-t border-(--color-border)\">\n              {details.map((d, i) => (\n                <li key={d.title} className=\"border-b border-(--color-border)\">\n                  <button type=\"button\" aria-expanded={open === i} onClick={() => setOpen(open === i ? null : i)} className=\"type-body flex w-full items-center justify-between py-4 text-left\">\n                    {d.title}<span aria-hidden className=\"text-(--color-muted)\">{open === i ? '−' : '+'}</span>\n                  </button>\n                  {open === i && <p className=\"type-body pb-5 text-(--color-muted)\">{d.text}</p>}\n                </li>\n              ))}\n            </ul>\n          )}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "specs": "// OpusKit section — Specs: the facts people check before deciding — a product's dimensions and materials, a property's\n// rooms and area, a project's place, year and team. Two designs:\n//   table — one ruled line per fact, the name on the left and the value on the right (exact, easy to scan).\n//   grid  — each fact in its own cell, the value large and the name small under it (a few facts that matter).\nexport type Spec = { label: string; value: string }\n\nexport function SpecsSection({ tone, variant = 'table', title, text, specs, note }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'table' | 'grid'; title: string; text?: string; specs: Spec[]; note?: string }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <div className=\"md:col-span-4\">\n          <h2 className=\"type-heading\">{title}</h2>\n          {text && <p className=\"type-body mt-4 max-w-[40ch] text-(--color-muted)\">{text}</p>}\n        </div>\n        <div className=\"md:col-span-8\">\n          {variant === 'grid' ? (\n            <dl className=\"grid grid-cols-2 border-l border-t border-(--color-border) lg:grid-cols-3\">\n              {specs.map((s) => (\n                <div key={s.label} className=\"flex flex-col border-b border-r border-(--color-border) p-5 md:p-6\">\n                  <dt className=\"type-utility order-2 mt-2 text-(--color-muted)\">{s.label}</dt>\n                  <dd className=\"type-heading order-1 [font-size:clamp(1.3rem,2.2vw,1.9rem)]\">{s.value}</dd>\n                </div>\n              ))}\n            </dl>\n          ) : (\n            <dl className=\"border-t border-(--color-text)\">\n              {specs.map((s) => (\n                <div key={s.label} className=\"grid grid-cols-[minmax(8rem,1fr)_2fr] gap-6 border-b border-(--color-border) py-4\">\n                  <dt className=\"type-body text-(--color-muted)\">{s.label}</dt>\n                  <dd className=\"type-body\">{s.value}</dd>\n                </div>\n              ))}\n            </dl>\n          )}\n          {note && <p className=\"type-utility mt-6 text-(--color-muted)\">{note}</p>}\n        </div>\n      </div>\n    </section>\n  )\n}\n",
  "article": "// OpusKit section — Article: one story, for reading. A title block (kicker, headline, a line under it, who and when), the\n// lead picture across the page, then one calm reading column where pull quotes and pictures break out wider, and the\n// author at the end. The page's h1 is the headline.\nimport type { ReactNode } from 'react'\nexport type ArticleBlock = string | { quote: string; by?: string } | { image: string; alt: string; caption?: string }\n\nexport function ArticleSection({ tone, kicker, title, dek, author, date, image, body, tags }: {\n  tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; kicker?: string; title: ReactNode; dek?: string\n  author: { name: string; role?: string; image?: string; bio?: string }; date: string\n  image?: { src: string; alt: string; caption?: string }; body: ArticleBlock[]; tags?: string[]\n}) {\n  return (\n    <article data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-[calc(var(--section-y)*0.7)]\">\n      <header className=\"mx-auto max-w-[56rem] text-center\">\n        {kicker && <p className=\"type-utility text-(--color-muted)\">{kicker}</p>}\n        <h1 className=\"type-display mt-4 text-balance [font-size:clamp(2.4rem,6vw,5.2rem)] leading-[1.02]\">{title}</h1>\n        {dek && <p className=\"type-body mx-auto mt-6 max-w-[52ch] text-balance [font-size:1.2rem] text-(--color-muted)\">{dek}</p>}\n        <p className=\"type-utility mt-6 text-(--color-muted)\">{author.name}<span aria-hidden>{'  /  '}</span><time>{date}</time></p>\n      </header>\n      {image && (\n        <figure className=\"mx-auto mt-12 max-w-(--container)\">\n          <img src={image.src} alt={image.alt} className=\"aspect-(--ratio-media) w-full rounded-(--radius-media) object-cover\" />\n          {image.caption && <figcaption className=\"type-utility mt-3 text-(--color-muted)\">{image.caption}</figcaption>}\n        </figure>\n      )}\n      <div className=\"type-body mx-auto mt-14 max-w-[64ch] space-y-6 [font-size:1.125rem] leading-[1.7]\">\n        {body.map((b, i) => typeof b === 'string' ? <p key={i}>{b}</p> : 'quote' in b ? (\n          <blockquote key={i} className=\"type-heading -mx-0 my-12 border-l-2 border-(--color-accent) pl-6 text-balance [font-size:clamp(1.5rem,3vw,2.3rem)] leading-[1.15] md:-mx-16\">\n            “{b.quote}”{b.by && <footer className=\"type-utility mt-4 text-(--color-muted)\">{b.by}</footer>}\n          </blockquote>\n        ) : (\n          <figure key={i} className=\"my-12 md:-mx-24\">\n            <img src={b.image} alt={b.alt} loading=\"lazy\" className=\"w-full rounded-(--radius-media) object-cover\" />\n            {b.caption && <figcaption className=\"type-utility mt-3 text-(--color-muted)\">{b.caption}</figcaption>}\n          </figure>\n        ))}\n      </div>\n      <footer className=\"mx-auto mt-16 flex max-w-[64ch] items-start gap-5 border-t border-(--color-border) pt-8\">\n        {author.image && <img src={author.image} alt=\"\" className=\"size-16 shrink-0 rounded-full object-cover\" />}\n        <div>\n          <p className=\"type-heading [font-size:1.2rem]\">{author.name}</p>\n          {author.role && <p className=\"type-utility text-(--color-muted)\">{author.role}</p>}\n          {author.bio && <p className=\"type-body mt-2 text-(--color-muted)\">{author.bio}</p>}\n          {tags && tags.length > 0 && <ul aria-label=\"Tags\" className=\"type-utility mt-4 flex flex-wrap gap-2\">{tags.map((t) => <li key={t} className=\"rounded-(--radius-button) border border-(--color-border) px-3 py-1\">{t}</li>)}</ul>}\n        </div>\n      </footer>\n    </article>\n  )\n}\n",
  "curriculum": "// OpusKit section — Curriculum: a course week by week. Each module is a row: its number and length, the title, a line on\n// what it covers, the lessons in it, and what the student makes or hands in. The rows are real sequence, so they keep\n// their numbers. Each lesson list is open on the page (nothing hidden behind a click), so it reads like a syllabus.\nexport type Module = { label: string; title: string; text?: string; lessons: string[]; outcome?: { label: string; value: string } }\n\nexport function CurriculumSection({ tone, title, text, modules, note }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; text?: string; modules: Module[]; note?: string }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-heading\">{title}</h2>\n        {text && <p className=\"type-body mt-4 max-w-[56ch] text-(--color-muted)\">{text}</p>}\n        <ol className=\"mt-12 border-t border-(--color-border)\">\n          {modules.map((m) => (\n            <li key={m.title} className=\"grid gap-x-8 gap-y-4 border-b border-(--color-border) py-8 md:grid-cols-12\">\n              <p className=\"type-utility text-(--color-muted) md:col-span-2\">{m.label}</p>\n              <div className=\"md:col-span-4\">\n                <h3 className=\"type-heading [font-size:clamp(1.2rem,2vw,1.6rem)]\">{m.title}</h3>\n                {m.text && <p className=\"type-body mt-3 text-(--color-muted)\">{m.text}</p>}\n              </div>\n              <ul className=\"type-body space-y-2 md:col-span-4\">\n                {m.lessons.map((l) => <li key={l} className=\"border-l border-(--color-border) pl-4\">{l}</li>)}\n              </ul>\n              {m.outcome && (\n                <div className=\"md:col-span-2\">\n                  <p className=\"type-utility text-(--color-muted)\">{m.outcome.label}</p>\n                  <p className=\"type-body mt-1\">{m.outcome.value}</p>\n                </div>\n              )}\n            </li>\n          ))}\n        </ol>\n        {note && <p className=\"type-utility mt-8 text-(--color-muted)\">{note}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "listen": "'use client'\n// OpusKit section — Listen: tracks to play right on the page. One <audio> for all of them, so only one ever plays; each\n// row has a play button, the title, its length and a few plain facts (where it was recorded, what it was made for).\n// Starting a track turns the site's own sound off (it presses the AmbientSound switch, `data-opuskit-sound`, so the\n// switch shows \"off\" too), and turning that sound on pauses the track.\nimport { useEffect, useRef, useState } from 'react'\n\nexport type ListenTrack = { title: string; src: string; length: string; details?: { label: string; value: string }[] }\n\nconst clock = (t: number) => { const s = Math.floor(t % 60); return `${Math.floor(t / 60)}:${s < 10 ? '0' : ''}${s}` }\nconst soundSwitch = () => document.querySelector<HTMLButtonElement>('[data-opuskit-sound]')\nconst Icon = ({ on }: { on: boolean }) => (\n  <svg viewBox=\"0 0 16 16\" aria-hidden className=\"size-5\" fill=\"currentColor\">{on ? <path d=\"M4 2h3v12H4zM9 2h3v12H9z\" /> : <path d=\"M5 2.5v11l9-5.5z\" />}</svg>\n)\n\nexport function ListenSection({ tone, title, text, tracks, play = 'Play', pause = 'Pause' }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title?: string; text?: string; tracks: ListenTrack[]; play?: string; pause?: string }) {\n  const audio = useRef<HTMLAudioElement>(null)\n  const [current, setCurrent] = useState<number | null>(null)\n  const [playing, setPlaying] = useState(false)\n  const [time, setTime] = useState(0)\n  const [length, setLength] = useState(0)\n\n  useEffect(() => {\n    // The site's sound switched on while a track plays: the track gives way.\n    const s = soundSwitch()\n    if (!s) return\n    const mo = new MutationObserver(() => { if (s.getAttribute('aria-pressed') === 'true') audio.current?.pause() })\n    mo.observe(s, { attributes: true, attributeFilter: ['aria-pressed'] })\n    return () => mo.disconnect()\n  }, [])\n\n  const toggle = (i: number) => {\n    const a = audio.current\n    if (!a) return\n    if (current === i && !a.paused) return a.pause()\n    if (current !== i) { a.src = tracks[i].src; setCurrent(i); setTime(0) }\n    const s = soundSwitch()\n    if (s?.getAttribute('aria-pressed') === 'true') s.click()\n    a.play().catch(() => setPlaying(false))\n  }\n\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        {title && <h2 className=\"type-heading\">{title}</h2>}\n        {text && <p className=\"type-body mt-4 max-w-[52ch] text-(--color-muted)\">{text}</p>}\n        <audio ref={audio} preload=\"none\" onPlay={() => setPlaying(true)} onPause={() => setPlaying(false)}\n          onEnded={() => { setPlaying(false); setTime(0) }} onTimeUpdate={(e) => setTime(e.currentTarget.currentTime)} onDurationChange={(e) => setLength(e.currentTarget.duration || 0)} />\n        <ol className={`${title || text ? 'mt-12' : ''} border-t border-(--color-border)`}>\n          {tracks.map((t, i) => {\n            const on = current === i && playing\n            return (\n              <li key={t.src} className=\"grid grid-cols-[auto_1fr] items-start gap-x-5 gap-y-3 border-b border-(--color-border) py-7 md:grid-cols-12 md:items-center md:gap-8\">\n                <button type=\"button\" onClick={() => toggle(i)} aria-pressed={on} aria-label={`${on ? pause : play} ${t.title}`}\n                  className={`grid size-14 cursor-pointer place-items-center rounded-full border transition-colors duration-150 md:col-span-1 ${on ? 'border-(--color-text) bg-(--color-text) text-(--color-background)' : 'border-(--color-muted) text-(--color-text) hover:border-(--color-text)'}`}>\n                  <Icon on={on} />\n                </button>\n                <div className=\"md:col-span-4\">\n                  <h3 className=\"type-heading [font-size:clamp(1.15rem,1.8vw,1.5rem)]\">{t.title}</h3>\n                  <p className=\"type-utility mt-2 tabular-nums text-(--color-muted)\" aria-live={current === i ? 'polite' : undefined}>{current === i ? `${clock(time)} / ${t.length}` : t.length}</p>\n                </div>\n                {t.details && t.details.length > 0 && (\n                  <dl className=\"col-span-2 grid gap-3 sm:grid-cols-2 md:col-span-7 md:gap-8\">\n                    {t.details.map((d) => <div key={d.label}><dt className=\"type-body text-(--color-muted)\">{d.label}</dt><dd className=\"type-body mt-1\">{d.value}</dd></div>)}\n                  </dl>\n                )}\n                {current === i && length > 0 && (\n                  <div aria-hidden className=\"col-span-2 h-px bg-(--color-border) md:col-span-12\">\n                    <div className=\"h-px origin-left bg-(--color-text)\" style={{ transform: `scaleX(${Math.min(1, time / length)})` }} />\n                  </div>\n                )}\n              </li>\n            )\n          })}\n        </ol>\n      </div>\n    </section>\n  )\n}\n",
  "donate": "// OpusKit section — Donate: preset gifts that each say what they pay for, beside the pledge form, then where the money\n// goes. The form is the project's own, built from shadcn/ui (a ToggleGroup for once/monthly and the amounts, Inputs, a\n// Button) and passed in as `form`; it hands off to the payment page or link — no fake \"thank you, charged\". This section\n// only lays it out, so no plain browser radio or number input ships.\nimport type { ReactNode } from 'react'\n\nexport type Gift = { amount: string; what: string; detail?: string }\nexport type Spend = { label: string; share: number }\n\nexport function DonateSection({ tone, title, text, gifts, form, spend, spendTitle = 'Where the money goes', note }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; text?: string; gifts: Gift[]; form: ReactNode; spend?: Spend[]; spendTitle?: string; note?: string }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <div className=\"grid gap-12 md:grid-cols-12\">\n          <div className=\"md:col-span-6\">\n            <h2 className=\"type-heading\">{title}</h2>\n            {text && <p className=\"type-body mt-4 max-w-[52ch] text-(--color-muted)\">{text}</p>}\n            <ul className=\"mt-10 border-t border-(--color-border)\">\n              {gifts.map((g) => (\n                <li key={g.amount} className=\"grid grid-cols-[minmax(5.5rem,auto)_1fr] items-baseline gap-x-6 border-b border-(--color-border) py-5\">\n                  <span className=\"type-display [font-size:clamp(1.8rem,3vw,2.6rem)]\">{g.amount}</span>\n                  <span><span className=\"type-body block\">{g.what}</span>{g.detail && <span className=\"type-utility mt-1 block text-(--color-muted)\">{g.detail}</span>}</span>\n                </li>\n              ))}\n            </ul>\n          </div>\n          <div className=\"rounded-(--radius-card) border border-(--color-border) bg-(--color-surface) p-6 shadow-(--shadow-card) md:col-span-5 md:col-start-8 md:self-start\">{form}</div>\n        </div>\n        {spend && spend.length > 0 && (\n          <div className=\"mt-16\">\n            <p className=\"type-utility text-(--color-muted)\">{spendTitle}</p>\n            <div className=\"mt-4 flex h-3 overflow-hidden rounded-(--radius-button) border border-(--color-text)\" aria-hidden>\n              {spend.map((s, i) => <span key={s.label} style={{ width: `${s.share}%`, opacity: 1 - i * (0.7 / spend.length) }} className=\"border-r-2 border-(--color-background) bg-(--color-text) last:border-r-0\" />)}\n            </div>\n            <ul className=\"mt-4 grid gap-4 sm:grid-cols-2 md:grid-cols-4\">\n              {spend.map((s) => <li key={s.label}><span className=\"type-heading [font-size:1.4rem]\">{s.share}%</span><span className=\"type-body mt-1 block text-(--color-muted)\">{s.label}</span></li>)}\n            </ul>\n          </div>\n        )}\n        {note && <p className=\"type-utility mt-10 text-(--color-muted)\">{note}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "timeline": "// OpusKit section — Timeline: the story in dated steps — year, what happened, one line on why it mattered — along a\n// hairline, oldest first, the latest step marked. The heading and a short line sit beside it on wide screens and above\n// it on phones. Everything stays readable at once: no carousel, no tabs.\nexport function TimelineSection({ tone, title, text, steps }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; title: string; text?: string; steps: { when: string; title: string; detail?: string }[] }) {\n  return (\n    <section data-tone={tone === 'ground' ? undefined : tone} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto grid max-w-(--container) gap-12 md:grid-cols-12\">\n        <div className=\"md:col-span-4\">\n          <h2 className=\"type-heading md:sticky md:top-28\">{title}</h2>\n          {text && <p className=\"type-body mt-4 max-w-[34ch] text-(--color-muted)\">{text}</p>}\n        </div>\n        <ol className=\"relative border-l border-(--color-border) md:col-span-7 md:col-start-6\">\n          {steps.map((s, i) => (\n            <li key={s.when + s.title} className=\"relative grid gap-1 pb-12 pl-8 last:pb-0 md:grid-cols-[8rem_1fr] md:gap-8\">\n              <span aria-hidden className={`absolute -left-[5px] top-2 size-[9px] rounded-full border border-(--color-text) ${i === steps.length - 1 ? 'bg-(--color-accent) border-(--color-accent)' : 'bg-(--color-background)'}`} />\n              <span className=\"type-display tabular-nums [font-size:clamp(1.6rem,2.6vw,2.4rem)] leading-none\">{s.when}</span>\n              <div>\n                <p className=\"type-heading [font-size:clamp(1.1rem,1.5vw,1.35rem)]\">{s.title}</p>\n                {s.detail && <p className=\"type-body mt-1 max-w-[52ch] text-(--color-muted)\">{s.detail}</p>}\n              </div>\n            </li>\n          ))}\n        </ol>\n      </div>\n    </section>\n  )\n}\n",
  "integrations": "// OpusKit section — Name wall: who you work with or what it connects to, real names set as type (no borrowed logos).\n// Three designs:\n//   grid   — names in ruled cells, a quiet wall of proof.\n//   inline — the names run as one big paragraph, the way a credits list reads.\n//   split  — a title and a line on the left, the names in cells on the right (tools, partners) — names only, never letters standing in for logos.\nexport function NameWallSection({ tone, variant = 'grid', title, text, names }: { tone?: 'ground' | 'surface' | 'inverse' | 'chapter'; variant?: 'grid' | 'inline' | 'split'; title: string; text?: string; names: string[] }) {\n  const t = tone === 'ground' ? undefined : tone\n  if (variant === 'split') return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*0.85)]\">\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <div className=\"md:col-span-4\">\n          <h2 className=\"type-heading text-balance\">{title}</h2>\n          {text && <p className=\"type-body mt-4 max-w-[40ch] text-(--color-muted)\">{text}</p>}\n        </div>\n        <ul className=\"grid grid-cols-2 self-start border-l border-t border-(--color-border) sm:grid-cols-3 md:col-span-8\">\n          {names.map((n) => (\n            <li key={n} className=\"type-body border-b border-r border-(--color-border) px-4 py-5 md:px-5 md:py-6\">{n}</li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  )\n  if (variant === 'inline') return (\n    <section data-tone={t} className=\"px-(--gutter) py-(--section-y)\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        <ul className=\"mt-8 flex flex-wrap gap-x-[0.6em] gap-y-1 type-display text-balance [font-size:clamp(1.8rem,4.6vw,4.2rem)] leading-[1.05]\">\n          {names.map((n, i) => <li key={n} className={i % 2 ? 'text-(--color-muted)' : undefined}>{n}{i < names.length - 1 ? ',' : ''}</li>)}\n        </ul>\n        {text && <p className=\"type-body mt-8 max-w-[56ch] text-(--color-muted)\">{text}</p>}\n      </div>\n    </section>\n  )\n  return (\n    <section data-tone={t} className=\"px-(--gutter) py-[calc(var(--section-y)*0.85)]\">\n      <div className=\"mx-auto max-w-(--container)\">\n        <h2 className=\"type-utility text-(--color-muted)\">{title}</h2>\n        <ul className=\"mt-8 grid grid-cols-2 border-l border-t border-(--color-border) md:grid-cols-4\">\n          {names.map((n) => <li key={n} className=\"type-heading border-b border-r border-(--color-border) px-5 py-8 [font-size:clamp(1.05rem,1.6vw,1.35rem)]\">{n}</li>)}\n        </ul>\n        {text && <p className=\"type-body mt-6 max-w-[56ch] text-(--color-muted)\">{text}</p>}\n      </div>\n    </section>\n  )\n}\n",
  "footer": "// OpusKit section — Footer in four variants (the recipe's footer style):\n//   signature — a big signature logo, columns of links, the legal line. Dark.\n//   wordmark  — links and contact in a row, then the brand name spanning the full width — set whole (`full`), cut off\n//               by the bottom edge (`cropped`), or drawn as an outline (`outline`).\n//   contact   — one big invitation with the email/phone as large links, details beside it.\n//   line      — logo, a few links and © in one quiet line.\n//   index     — every page, service and post in 3–4 columns, a map of the whole site, on the page ground.\nimport type { ElementType, ReactNode } from 'react'\n\nexport type FooterColumn = { title: string; links: { label: string; href: string; current?: boolean }[] }\nexport type FooterVariant = 'signature' | 'wordmark' | 'contact' | 'line' | 'index'\ntype Link = { label: string; href: string }\n\n// A plain underline on hover — the site's Links behaviour (scribble, roll, fill…) replaces it when one is picked.\nconst plain = 'underline decoration-transparent decoration-1 underline-offset-4 transition-[text-decoration-color] duration-200 hover:decoration-current focus-visible:decoration-current aria-[current=page]:decoration-current'\n\nexport function FooterSection({ link: L = 'a', variant = 'signature', wordmark = 'full', logo, brand, columns, legal, copyright, invite = 'Let’s talk', contact = [], light = false }: {\n  link?: ElementType; variant?: FooterVariant; wordmark?: 'full' | 'cropped' | 'outline'; logo: ReactNode; /** The name as text — the wordmark variant sets it huge. */ brand?: string; columns: FooterColumn[]\n  legal?: Link[]; copyright: string; /** contact variant: the invitation and the ways to reach you. */ invite?: string; contact?: Link[]; light?: boolean\n}) {\n  const links = columns.flatMap((c) => c.links)\n  const item = (l: Link & { current?: boolean }) => <L key={l.href + l.label} href={l.href} aria-current={l.current ? 'page' : undefined} className={plain}>{l.label}</L>\n  const bottom = (\n    <div className=\"type-utility mx-auto mt-16 flex max-w-(--container) flex-wrap justify-between gap-4 border-t border-current/20 pt-6 [font-size:0.9rem] opacity-70\">\n      <span>{copyright}</span>\n      {legal && <span className=\"flex gap-6\">{legal.map(item)}</span>}\n    </div>\n  )\n  const ground = light || variant === 'line' || variant === 'index' ? 'bg-(--color-background) text-(--color-text)' : 'bg-(--color-text) text-(--color-background)'\n\n  if (variant === 'line') return (\n    <footer className={`px-(--gutter) py-8 ${ground}`}>\n      <div className=\"type-utility mx-auto flex max-w-(--container) flex-col items-center gap-4 border-t border-current/20 pt-6 text-center md:flex-row md:justify-between md:text-left\">\n        <div>{logo}</div>\n        <nav aria-label=\"Footer\" className=\"flex flex-wrap justify-center gap-6\">{links.slice(0, 5).map(item)}</nav>\n        <span className=\"opacity-70 [font-size:0.9rem]\">{copyright}</span>\n      </div>\n    </footer>\n  )\n\n  if (variant === 'index') return (\n    <footer className={`px-(--gutter) pb-8 pt-16 ${ground}`}>\n      <div className=\"mx-auto max-w-(--container) border-t border-current/20 pt-10\">\n        <div className=\"flex flex-wrap items-baseline justify-between gap-6\">\n          <div>{logo}</div>\n          {contact.length > 0 && <p className=\"type-body flex flex-wrap gap-x-6 gap-y-1\">{contact.map(item)}</p>}\n        </div>\n        <div className=\"mt-12 grid grid-cols-2 gap-x-8 gap-y-10 md:grid-cols-4\">\n          {columns.map((col) => (\n            <nav key={col.title} aria-label={col.title}>\n              <h2 className=\"type-utility opacity-70\">{col.title}</h2>\n              <ul className=\"type-body mt-3 space-y-1.5\">{col.links.map((l) => <li key={l.href + l.label}>{item(l)}</li>)}</ul>\n            </nav>\n          ))}\n        </div>\n      </div>\n      {bottom}\n    </footer>\n  )\n\n  if (variant === 'wordmark' && wordmark === 'cropped') return (\n    <footer className={`overflow-hidden px-(--gutter) pt-16 ${ground}`}>\n      <nav aria-label=\"Footer\" className=\"type-utility mx-auto flex max-w-(--container) flex-wrap gap-x-8 gap-y-3\">{links.map(item)}</nav>\n      <div className=\"type-utility mx-auto mt-8 flex max-w-(--container) flex-wrap justify-between gap-4 [font-size:0.9rem] opacity-70\"><span>{copyright}</span>{legal && <span className=\"flex gap-6\">{legal.map(item)}</span>}</div>\n      <p aria-hidden className=\"type-display mx-auto mt-10 -mb-[0.22em] max-w-(--container) whitespace-nowrap leading-[0.8] [font-size:clamp(5rem,23vw,22rem)]\">{brand ?? logo}</p>\n    </footer>\n  )\n\n  if (variant === 'wordmark') return (\n    <footer className={`overflow-hidden px-(--gutter) pb-8 pt-16 ${ground}`}>\n      <nav aria-label=\"Footer\" className=\"type-utility mx-auto flex max-w-(--container) flex-wrap gap-x-8 gap-y-3\">{links.map(item)}</nav>\n      <p aria-hidden className={`type-display mx-auto mt-12 max-w-(--container) whitespace-nowrap leading-[0.8] [font-size:clamp(4rem,17vw,16rem)] ${wordmark === 'outline' ? '[-webkit-text-fill-color:transparent] [-webkit-text-stroke:1.5px_currentColor]' : ''}`}>{brand ?? logo}</p>\n      {bottom}\n    </footer>\n  )\n\n  if (variant === 'contact') return (\n    <footer className={`px-(--gutter) pb-8 pt-20 ${ground}`}>\n      <div className=\"mx-auto grid max-w-(--container) gap-10 md:grid-cols-12\">\n        <div className=\"md:col-span-8\">\n          <h2 className=\"type-display [font-size:clamp(2.6rem,6vw,5.5rem)]\">{invite}</h2>\n          <ul className=\"type-heading mt-8 space-y-2 [font-size:clamp(1.3rem,2.4vw,2rem)]\">{contact.map((l) => <li key={l.href + l.label}>{item(l)}</li>)}</ul>\n        </div>\n        <div className=\"type-body space-y-6 opacity-90 md:col-span-4\">\n          {logo}\n          {columns.map((col) => (\n            <nav key={col.title} aria-label={col.title}>\n              <h3 className=\"type-utility opacity-70\">{col.title}</h3>\n              <ul className=\"mt-2 space-y-1\">{col.links.map((l) => <li key={l.href + l.label}>{item(l)}</li>)}</ul>\n            </nav>\n          ))}\n        </div>\n      </div>\n      {bottom}\n    </footer>\n  )\n\n  return (\n    <footer className={`px-(--gutter) pb-8 pt-16 ${ground}`}>\n      <div className=\"mx-auto grid max-w-(--container) gap-12 border-t border-current/20 pt-16 md:grid-cols-12\">\n        <div className=\"md:col-span-5\">{logo}</div>\n        {columns.map((col) => (\n          <nav key={col.title} aria-label={col.title} className=\"md:col-span-2\">\n            <h2 className=\"type-heading [font-size:1.15rem]\">{col.title}</h2>\n            <ul className=\"type-utility mt-4 space-y-2 opacity-90\">\n              {col.links.map((l) => <li key={l.href + l.label}>{item(l)}</li>)}\n            </ul>\n          </nav>\n        ))}\n      </div>\n      {bottom}\n    </footer>\n  )\n}\n",
}

export const heroSource: Partial<Record<HeroId, string>> = {
  "orbit-stickers": "'use client'\n// OpusKit section — Sticker orbit hero: a two-voice headline with brand stickers and photos on an ellipse around it.\n// Scrolling turns the ring (each sticker travels around the headline) while the ring drifts up and away.\n// Reduced motion: the ring stays still. Tokens only; the loud and quiet halves use the display and heading families.\nimport { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from 'motion/react'\nimport { useRef } from 'react'\n\nexport type OrbitItem = { src: string; alt: string; size?: number; tilt?: number }\n\nfunction Orbiter({ item, i, n, turn }: { item: OrbitItem; i: number; n: number; turn: MotionValue<number> }) {\n  const angle = (deg: number) => ((i / n) * 360 + deg) * (Math.PI / 180)\n  const left = useTransform(turn, (d) => `${50 + Math.cos(angle(d)) * 46}%`)\n  const top = useTransform(turn, (d) => `${50 + Math.sin(angle(d)) * 43}%`)\n  return (\n    <motion.img src={item.src} alt={item.alt} draggable={false} className=\"absolute -translate-x-1/2 -translate-y-1/2 select-none object-contain\"\n      style={{ left, top, width: item.size ?? 120, rotate: item.tilt ?? 0 }}\n      initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: 'spring', stiffness: 260, damping: 18, delay: 0.2 + i * 0.05 }} />\n  )\n}\n\nexport function OrbitHeroSection({ eyebrow, loud, quiet, line, items }: { eyebrow?: string; loud: string; quiet: string; line?: string; items: OrbitItem[] }) {\n  const ref = useRef<HTMLElement>(null)\n  const reduce = useReducedMotion()\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end start'] })\n  const turn = useTransform(scrollYProgress, [0, 1], [0, reduce ? 0 : 140])\n  const lift = useTransform(scrollYProgress, [0, 1], ['0%', reduce ? '0%' : '-35%'])\n  return (\n    <section ref={ref} className=\"relative h-[100svh] min-h-[640px] overflow-hidden px-(--gutter)\">\n      <motion.div aria-hidden={false} className=\"absolute inset-0\" style={{ y: lift }}>\n        {items.map((it, i) => <Orbiter key={it.src + i} item={it} i={i} n={items.length} turn={turn} />)}\n      </motion.div>\n      <div className=\"relative z-10 mx-auto grid h-full max-w-[1100px] place-content-center text-center\">\n        {eyebrow && <p className=\"type-utility\">{eyebrow}</p>}\n        <h1 className=\"type-display mt-3 flex flex-wrap items-baseline justify-center gap-x-[0.25em]\">\n          <span>{loud}</span>\n          <span className=\"font-(family-name:--font-heading) [font-stretch:var(--type-heading-stretch)] [font-weight:var(--type-heading-weight)]\">{quiet}</span>\n        </h1>\n        {line && <p className=\"type-utility mx-auto mt-6 max-w-[34ch]\">{line}</p>}\n      </div>\n    </section>\n  )\n}\n",
}
